-- ===== bai-06-cach-mang-thang-tam.json =====
insert into public.exam_passages (title, body, source_citation, lesson_slug)
select 'Tuyên ngôn độc lập (2-9-1945) — đoạn kết', '“Nước Việt Nam có quyền hưởng tự do và độc lập, và sự thật đã thành một nước tự do, độc lập. Toàn thể dân tộc Việt Nam quyết đem tất cả tinh thần và lực lượng, tính mạng và của cải để giữ vững quyền tự do, độc lập ấy.”', 'Hồ Chí Minh, Tuyên ngôn độc lập, đọc tại Quảng trường Ba Đình, Hà Nội, ngày 2-9-1945', '6-cach-mang-thang-tam-nam-1945'
where not exists (select 1 from public.exam_passages where title = 'Tuyên ngôn độc lập (2-9-1945) — đoạn kết' and body = '“Nước Việt Nam có quyền hưởng tự do và độc lập, và sự thật đã thành một nước tự do, độc lập. Toàn thể dân tộc Việt Nam quyết đem tất cả tinh thần và lực lượng, tính mạng và của cải để giữ vững quyền tự do, độc lập ấy.”');
insert into public.exam_passages (title, body, source_citation, lesson_slug)
select 'Tuyên ngôn độc lập (2-9-1945) — đoạn mở đầu', '“Hỡi đồng bào cả nước,
Tất cả mọi người đều sinh ra có quyền bình đẳng. Tạo hóa cho họ những quyền không ai có thể xâm phạm được; trong những quyền ấy, có quyền được sống, quyền tự do và quyền mưu cầu hạnh phúc.
Lời bất hủ ấy ở trong bản Tuyên ngôn Độc lập năm 1776 của nước Mỹ. Suy rộng ra, câu ấy có ý nghĩa là: tất cả các dân tộc trên thế giới đều sinh ra bình đẳng, dân tộc nào cũng có quyền sống, quyền sung sướng và quyền tự do.
Bản Tuyên ngôn Nhân quyền và Dân quyền của Cách mạng Pháp năm 1791 cũng nói: Người ta sinh ra tự do và bình đẳng về quyền lợi; và phải luôn luôn được tự do và bình đẳng về quyền lợi.
Đó là những lẽ phải không ai chối cãi được.”', 'Hồ Chí Minh, Tuyên ngôn độc lập, đọc tại Quảng trường Ba Đình, Hà Nội, ngày 2-9-1945', '6-cach-mang-thang-tam-nam-1945'
where not exists (select 1 from public.exam_passages where title = 'Tuyên ngôn độc lập (2-9-1945) — đoạn mở đầu' and body = '“Hỡi đồng bào cả nước,
Tất cả mọi người đều sinh ra có quyền bình đẳng. Tạo hóa cho họ những quyền không ai có thể xâm phạm được; trong những quyền ấy, có quyền được sống, quyền tự do và quyền mưu cầu hạnh phúc.
Lời bất hủ ấy ở trong bản Tuyên ngôn Độc lập năm 1776 của nước Mỹ. Suy rộng ra, câu ấy có ý nghĩa là: tất cả các dân tộc trên thế giới đều sinh ra bình đẳng, dân tộc nào cũng có quyền sống, quyền sung sướng và quyền tự do.
Bản Tuyên ngôn Nhân quyền và Dân quyền của Cách mạng Pháp năm 1791 cũng nói: Người ta sinh ra tự do và bình đẳng về quyền lợi; và phải luôn luôn được tự do và bình đẳng về quyền lợi.
Đó là những lẽ phải không ai chối cãi được.”');
insert into public.exam_passages (title, body, source_citation, lesson_slug)
select 'Tuyên ngôn độc lập (2-9-1945) — đoạn về “sự thật”', '“Sự thật là từ mùa thu năm 1940, nước ta đã thành thuộc địa của Nhật, chứ không phải thuộc địa của Pháp nữa. Khi Nhật hàng Đồng minh thì nhân dân cả nước ta đã nổi dậy giành chính quyền, lập nên nước Việt Nam Dân chủ Cộng hòa.
Sự thật là dân ta đã lấy lại nước Việt Nam từ tay Nhật, chứ không phải từ tay Pháp.
Pháp chạy, Nhật hàng, vua Bảo Đại thoái vị. Dân ta đã đánh đổ các xiềng xích thực dân gần 100 năm nay để gây dựng nên nước Việt Nam độc lập. Dân ta lại đánh đổ chế độ quân chủ mấy mươi thế kỷ mà lập nên chế độ Dân chủ Cộng hòa.”', 'Hồ Chí Minh, Tuyên ngôn độc lập, đọc tại Quảng trường Ba Đình, Hà Nội, ngày 2-9-1945', '6-cach-mang-thang-tam-nam-1945'
where not exists (select 1 from public.exam_passages where title = 'Tuyên ngôn độc lập (2-9-1945) — đoạn về “sự thật”' and body = '“Sự thật là từ mùa thu năm 1940, nước ta đã thành thuộc địa của Nhật, chứ không phải thuộc địa của Pháp nữa. Khi Nhật hàng Đồng minh thì nhân dân cả nước ta đã nổi dậy giành chính quyền, lập nên nước Việt Nam Dân chủ Cộng hòa.
Sự thật là dân ta đã lấy lại nước Việt Nam từ tay Nhật, chứ không phải từ tay Pháp.
Pháp chạy, Nhật hàng, vua Bảo Đại thoái vị. Dân ta đã đánh đổ các xiềng xích thực dân gần 100 năm nay để gây dựng nên nước Việt Nam độc lập. Dân ta lại đánh đổ chế độ quân chủ mấy mươi thế kỷ mà lập nên chế độ Dân chủ Cộng hòa.”');
insert into public.exam_passages (title, body, source_citation, lesson_slug)
select 'Thời cơ của Tổng khởi nghĩa tháng Tám năm 1945', 'Ngày 15-8-1945, Nhật Bản tuyên bố đầu hàng Đồng minh không điều kiện. Quân Nhật ở Đông Dương rệu rã, mất tinh thần; chính phủ thân Nhật Trần Trọng Kim hoang mang, lo sợ. Theo thỏa thuận của các nước Đồng minh, quân Trung Hoa Dân quốc sẽ vào miền Bắc, quân Anh vào miền Nam (lấy vĩ tuyến 16 làm ranh giới) để giải giáp quân Nhật.
Ngay khi biết tin Nhật sắp đầu hàng, Ủy ban Khởi nghĩa toàn quốc được thành lập và đêm 13-8-1945 ban bố Quân lệnh số 1. Hội nghị toàn quốc của Đảng (14 – 15-8) và Quốc dân Đại hội ở Tân Trào (16-8) quyết định phát động Tổng khởi nghĩa, giành chính quyền từ tay Nhật và tay sai trước khi quân Đồng minh vào Đông Dương. Chủ tịch Hồ Chí Minh gửi thư kêu gọi: “Giờ quyết định cho vận mệnh dân tộc ta đã đến. Toàn quốc đồng bào hãy đứng dậy đem sức ta mà tự giải phóng cho ta.”', 'Tóm lược của biên tập viên theo SGK Lịch sử 12 (KNTT), Bài 6, mục 1; câu trích từ Thư kêu gọi Tổng khởi nghĩa của Hồ Chí Minh (8-1945)', '6-cach-mang-thang-tam-nam-1945'
where not exists (select 1 from public.exam_passages where title = 'Thời cơ của Tổng khởi nghĩa tháng Tám năm 1945' and body = 'Ngày 15-8-1945, Nhật Bản tuyên bố đầu hàng Đồng minh không điều kiện. Quân Nhật ở Đông Dương rệu rã, mất tinh thần; chính phủ thân Nhật Trần Trọng Kim hoang mang, lo sợ. Theo thỏa thuận của các nước Đồng minh, quân Trung Hoa Dân quốc sẽ vào miền Bắc, quân Anh vào miền Nam (lấy vĩ tuyến 16 làm ranh giới) để giải giáp quân Nhật.
Ngay khi biết tin Nhật sắp đầu hàng, Ủy ban Khởi nghĩa toàn quốc được thành lập và đêm 13-8-1945 ban bố Quân lệnh số 1. Hội nghị toàn quốc của Đảng (14 – 15-8) và Quốc dân Đại hội ở Tân Trào (16-8) quyết định phát động Tổng khởi nghĩa, giành chính quyền từ tay Nhật và tay sai trước khi quân Đồng minh vào Đông Dương. Chủ tịch Hồ Chí Minh gửi thư kêu gọi: “Giờ quyết định cho vận mệnh dân tộc ta đã đến. Toàn quốc đồng bào hãy đứng dậy đem sức ta mà tự giải phóng cho ta.”');
insert into public.exam_passages (title, body, source_citation, lesson_slug)
select 'Diễn biến Tổng khởi nghĩa tháng Tám năm 1945', 'Từ ngày 14-8-1945, ở nhiều địa phương, quần chúng dưới sự lãnh đạo của Việt Minh nổi dậy giành chính quyền. Ngày 18-8, bốn tỉnh Bắc Giang, Hải Dương, Hà Tĩnh và Quảng Nam giành chính quyền ở tỉnh lị sớm nhất. Ngày 19-8, khởi nghĩa giành chính quyền ở Hà Nội thắng lợi. Tiếp đó, ngày 23-8 nhân dân Huế và ngày 25-8 nhân dân Sài Gòn giành chính quyền. Đến ngày 28-8-1945, Tổng khởi nghĩa thành công trong cả nước; Đồng Nai Thượng và Hà Tiên là những nơi giành chính quyền muộn nhất.
Ngày 30-8-1945, vua Bảo Đại thoái vị. Ngày 2-9-1945, tại Quảng trường Ba Đình (Hà Nội), Chủ tịch Hồ Chí Minh đọc Tuyên ngôn độc lập, khai sinh nước Việt Nam Dân chủ Cộng hòa.', 'Tóm lược của biên tập viên theo SGK Lịch sử 12 (KNTT), Bài 6, mục 1', '6-cach-mang-thang-tam-nam-1945'
where not exists (select 1 from public.exam_passages where title = 'Diễn biến Tổng khởi nghĩa tháng Tám năm 1945' and body = 'Từ ngày 14-8-1945, ở nhiều địa phương, quần chúng dưới sự lãnh đạo của Việt Minh nổi dậy giành chính quyền. Ngày 18-8, bốn tỉnh Bắc Giang, Hải Dương, Hà Tĩnh và Quảng Nam giành chính quyền ở tỉnh lị sớm nhất. Ngày 19-8, khởi nghĩa giành chính quyền ở Hà Nội thắng lợi. Tiếp đó, ngày 23-8 nhân dân Huế và ngày 25-8 nhân dân Sài Gòn giành chính quyền. Đến ngày 28-8-1945, Tổng khởi nghĩa thành công trong cả nước; Đồng Nai Thượng và Hà Tiên là những nơi giành chính quyền muộn nhất.
Ngày 30-8-1945, vua Bảo Đại thoái vị. Ngày 2-9-1945, tại Quảng trường Ba Đình (Hà Nội), Chủ tịch Hồ Chí Minh đọc Tuyên ngôn độc lập, khai sinh nước Việt Nam Dân chủ Cộng hòa.');
insert into public.exam_passages (title, body, source_citation, lesson_slug)
select 'Nguyên nhân thắng lợi của Cách mạng tháng Tám năm 1945', 'Cách mạng tháng Tám năm 1945 thành công trước hết bắt nguồn từ truyền thống yêu nước, đấu tranh kiên cường chống ngoại xâm của dân tộc Việt Nam. Đảng Cộng sản Đông Dương, đứng đầu là Hồ Chí Minh, đã đề ra đường lối cách mạng đúng đắn, đặt nhiệm vụ giải phóng dân tộc lên hàng đầu, xây dựng khối đoàn kết toàn dân trong Mặt trận Việt Minh. Cuộc cách mạng là kết quả của quá trình chuẩn bị suốt 15 năm, qua ba cao trào cách mạng 1930 – 1931, 1936 – 1939 và 1939 – 1945. Khi thời cơ đến, Đảng kịp thời phát động Tổng khởi nghĩa.
Bên cạnh đó, thắng lợi của Liên Xô và quân Đồng minh trong cuộc chiến tranh chống chủ nghĩa phát xít đã cổ vũ tinh thần và tạo thời cơ khách quan thuận lợi để nhân dân Việt Nam đứng lên giành chính quyền.', 'Tóm lược của biên tập viên theo SGK Lịch sử 12 (KNTT), Bài 6, mục 2', '6-cach-mang-thang-tam-nam-1945'
where not exists (select 1 from public.exam_passages where title = 'Nguyên nhân thắng lợi của Cách mạng tháng Tám năm 1945' and body = 'Cách mạng tháng Tám năm 1945 thành công trước hết bắt nguồn từ truyền thống yêu nước, đấu tranh kiên cường chống ngoại xâm của dân tộc Việt Nam. Đảng Cộng sản Đông Dương, đứng đầu là Hồ Chí Minh, đã đề ra đường lối cách mạng đúng đắn, đặt nhiệm vụ giải phóng dân tộc lên hàng đầu, xây dựng khối đoàn kết toàn dân trong Mặt trận Việt Minh. Cuộc cách mạng là kết quả của quá trình chuẩn bị suốt 15 năm, qua ba cao trào cách mạng 1930 – 1931, 1936 – 1939 và 1939 – 1945. Khi thời cơ đến, Đảng kịp thời phát động Tổng khởi nghĩa.
Bên cạnh đó, thắng lợi của Liên Xô và quân Đồng minh trong cuộc chiến tranh chống chủ nghĩa phát xít đã cổ vũ tinh thần và tạo thời cơ khách quan thuận lợi để nhân dân Việt Nam đứng lên giành chính quyền.');
