 where content_key is null and fingerprint = public.exam_item_fingerprint('true_false', 'Cho thông tin: “Từ ngày 14 đến ngày 28-8-1945, cuộc Tổng khởi nghĩa giành chính quyền diễn ra trong cả nước.”', null, '[{"text":"Khởi nghĩa giành chính quyền ở Hà Nội thắng lợi trước Huế và Sài Gòn.","is_true":true,"explanation":"Hà Nội giành chính quyền ngày 19-8, Huế ngày 23-8, Sài Gòn ngày 25-8-1945.","section_id":"muc-1"},{"text":"Bắc Giang, Hải Dương, Hà Tĩnh và Quảng Nam là những địa phương giành chính quyền ở tỉnh lị sớm nhất (18-8-1945).","is_true":true,"explanation":"Ngày 18-8-1945, đây là bốn tỉnh giành chính quyền ở tỉnh lị sớm nhất trong cả nước.","section_id":"muc-1"},{"text":"Cách mạng tháng Tám thắng lợi chủ yếu nhờ quân Đồng minh đánh đuổi phát xít Nhật ở Việt Nam.","is_true":false,"explanation":"Đề đánh tráo chủ thể: nhân dân Việt Nam tự lực giành chính quyền trước khi quân Đồng minh vào; thắng lợi của Đồng minh chỉ tạo thời cơ khách quan.","section_id":"muc-2","trap":"chu_the"},{"text":"Tổng khởi nghĩa nổ ra khi quân Nhật đang ở thế mạnh, chưa đầu hàng Đồng minh.","is_true":false,"explanation":"Đề sai bản chất: Tổng khởi nghĩa nổ ra khi phát xít Nhật đã chấp nhận đầu hàng Đồng minh (tuyên bố ngày 15-8-1945), quân Nhật ở Đông Dương rệu rã — không phải lúc Nhật còn mạnh.","section_id":"muc-1","trap":"ban_chat"}]'::jsonb)
   and not exists (select 1 from public.exam_items where content_key = 'b6-m1-ds-01');
