update public.exam_items set content_key = 'b6-m1-ds-02'
 where content_key is null and fingerprint = public.exam_item_fingerprint('true_false', 'Đọc đoạn tư liệu và cho biết mỗi ý sau đúng hay sai.', null, '[{"text":"Đoạn tư liệu khẳng định quyền hưởng tự do, độc lập của nước Việt Nam.","is_true":true,"explanation":"Câu đầu đoạn tư liệu: “Nước Việt Nam có quyền hưởng tự do và độc lập…”.","section_id":"muc-1"},{"text":"Đoạn tư liệu thể hiện quyết tâm của toàn dân tộc giữ vững quyền tự do, độc lập.","is_true":true,"explanation":"“Toàn thể dân tộc Việt Nam quyết đem tất cả tinh thần và lực lượng, tính mạng và của cải để giữ vững quyền tự do, độc lập ấy.”","section_id":"muc-1"},{"text":"Theo đoạn tư liệu, Việt Nam sẽ giữ vững độc lập bằng cách dựa hoàn toàn vào nước ngoài.","is_true":false,"explanation":"Đề đánh tráo bản chất: tư liệu nói dân tộc Việt Nam đem tất cả lực lượng CỦA CHÍNH MÌNH để giữ độc lập, không nói dựa vào nước ngoài.","section_id":"muc-1","trap":"ban_chat"},{"text":"Đoạn tư liệu ra đời sau khi cuộc kháng chiến chống thực dân Pháp thắng lợi.","is_true":false,"explanation":"Đề sai thời gian: Tuyên ngôn độc lập được đọc ngày 2-9-1945, trước cuộc kháng chiến toàn quốc chống Pháp (19-12-1946).","lesson_slug":"7-khang-chien-chong-phap","section_id":"muc-1","trap":"thoi_gian"}]'::jsonb)
   and not exists (select 1 from public.exam_items where content_key = 'b6-m1-ds-02');
insert into public.exam_items (content_key, kind, stem, passage_id, choices, correct_index, statements, choice_notes, explanation, remember, grade, lesson_slug, section_id, topic_tag, level, competency, event_id, source_note)
values ('b6-m1-ds-02', 'true_false', 'Đọc đoạn tư liệu và cho biết mỗi ý sau đúng hay sai.', (select id from public.exam_passages where title = 'Tuyên ngôn độc lập (2-9-1945) — đoạn kết' and body = '“Nước Việt Nam có quyền hưởng tự do và độc lập, và sự thật đã thành một nước tự do, độc lập. Toàn thể dân tộc Việt Nam quyết đem tất cả tinh thần và lực lượng, tính mạng và của cải để giữ vững quyền tự do, độc lập ấy.”' order by created_at limit 1), null, null, '[{"text":"Đoạn tư liệu khẳng định quyền hưởng tự do, độc lập của nước Việt Nam.","is_true":true,"explanation":"Câu đầu đoạn tư liệu: “Nước Việt Nam có quyền hưởng tự do và độc lập…”.","section_id":"muc-1"},{"text":"Đoạn tư liệu thể hiện quyết tâm của toàn dân tộc giữ vững quyền tự do, độc lập.","is_true":true,"explanation":"“Toàn thể dân tộc Việt Nam quyết đem tất cả tinh thần và lực lượng, tính mạng và của cải để giữ vững quyền tự do, độc lập ấy.”","section_id":"muc-1"},{"text":"Theo đoạn tư liệu, Việt Nam sẽ giữ vững độc lập bằng cách dựa hoàn toàn vào nước ngoài.","is_true":false,"explanation":"Đề đánh tráo bản chất: tư liệu nói dân tộc Việt Nam đem tất cả lực lượng CỦA CHÍNH MÌNH để giữ độc lập, không nói dựa vào nước ngoài.","section_id":"muc-1","trap":"ban_chat"},{"text":"Đoạn tư liệu ra đời sau khi cuộc kháng chiến chống thực dân Pháp thắng lợi.","is_true":false,"explanation":"Đề sai thời gian: Tuyên ngôn độc lập được đọc ngày 2-9-1945, trước cuộc kháng chiến toàn quốc chống Pháp (19-12-1946).","lesson_slug":"7-khang-chien-chong-phap","section_id":"muc-1","trap":"thoi_gian"}]'::jsonb, null, 'Câu đọc hiểu tư liệu: phân biệt nội dung có trong tư liệu với suy diễn sai và bối cảnh thời gian.', 'Đoạn kết Tuyên ngôn: khẳng định quyền độc lập và quyết tâm giữ vững độc lập bằng mọi giá.', 12, '6-cach-mang-thang-tam-nam-1945', 'muc-1', null, 'thong_hieu', 'nhan_thuc_tu_duy', null, 'SGK Lịch sử 12 (KNTT), Bài 6, mục 1')
