update public.exam_items set content_key = 'b6-m1-ds-03'
 where content_key is null and fingerprint = public.exam_item_fingerprint('true_false', 'Đọc đoạn tư liệu về diễn biến Tổng khởi nghĩa tháng Tám năm 1945 và xác định mỗi ý sau đúng hay sai.', null, '[{"text":"Quần chúng nổi dậy giành chính quyền dưới sự lãnh đạo của Việt Minh.","is_true":true,"explanation":"Tư liệu: “quần chúng dưới sự lãnh đạo của Việt Minh nổi dậy giành chính quyền”.","section_id":"muc-1"},{"text":"Sài Gòn là nơi giành chính quyền muộn nhất trong cả nước.","is_true":false,"explanation":"Tư liệu ghi Đồng Nai Thượng và Hà Tiên là những nơi giành chính quyền muộn nhất (28-8), sau Sài Gòn (25-8).","section_id":"muc-1","trap":"dia_diem"},{"text":"Từ ngày 14 đến ngày 28-8-1945, Tổng khởi nghĩa giành thắng lợi trên cả nước.","is_true":true,"explanation":"Khoảng 15 ngày, như tư liệu nêu.","section_id":"muc-1"},{"text":"Vua Bảo Đại thoái vị trước khi nhân dân Huế giành chính quyền.","is_true":false,"explanation":"Đề đảo thứ tự: Huế giành chính quyền ngày 23-8, vua Bảo Đại thoái vị ngày 30-8-1945.","section_id":"muc-1","trap":"thoi_gian"}]'::jsonb)
   and not exists (select 1 from public.exam_items where content_key = 'b6-m1-ds-03');
insert into public.exam_items (content_key, kind, stem, passage_id, choices, correct_index, statements, choice_notes, explanation, remember, grade, lesson_slug, section_id, topic_tag, level, competency, event_id, source_note)
values ('b6-m1-ds-03', 'true_false', 'Đọc đoạn tư liệu về diễn biến Tổng khởi nghĩa tháng Tám năm 1945 và xác định mỗi ý sau đúng hay sai.', (select id from public.exam_passages where title = 'Diễn biến Tổng khởi nghĩa tháng Tám năm 1945' and body = 'Từ ngày 14-8-1945, ở nhiều địa phương, quần chúng dưới sự lãnh đạo của Việt Minh nổi dậy giành chính quyền. Ngày 18-8, bốn tỉnh Bắc Giang, Hải Dương, Hà Tĩnh và Quảng Nam giành chính quyền ở tỉnh lị sớm nhất. Ngày 19-8, khởi nghĩa giành chính quyền ở Hà Nội thắng lợi. Tiếp đó, ngày 23-8 nhân dân Huế và ngày 25-8 nhân dân Sài Gòn giành chính quyền. Đến ngày 28-8-1945, Tổng khởi nghĩa thành công trong cả nước; Đồng Nai Thượng và Hà Tiên là những nơi giành chính quyền muộn nhất.
Ngày 30-8-1945, vua Bảo Đại thoái vị. Ngày 2-9-1945, tại Quảng trường Ba Đình (Hà Nội), Chủ tịch Hồ Chí Minh đọc Tuyên ngôn độc lập, khai sinh nước Việt Nam Dân chủ Cộng hòa.' order by created_at limit 1), null, null, '[{"text":"Quần chúng nổi dậy giành chính quyền dưới sự lãnh đạo của Việt Minh.","is_true":true,"explanation":"Tư liệu: “quần chúng dưới sự lãnh đạo của Việt Minh nổi dậy giành chính quyền”.","section_id":"muc-1"},{"text":"Sài Gòn là nơi giành chính quyền muộn nhất trong cả nước.","is_true":false,"explanation":"Tư liệu ghi Đồng Nai Thượng và Hà Tiên là những nơi giành chính quyền muộn nhất (28-8), sau Sài Gòn (25-8).","section_id":"muc-1","trap":"dia_diem"},{"text":"Từ ngày 14 đến ngày 28-8-1945, Tổng khởi nghĩa giành thắng lợi trên cả nước.","is_true":true,"explanation":"Khoảng 15 ngày, như tư liệu nêu.","section_id":"muc-1"},{"text":"Vua Bảo Đại thoái vị trước khi nhân dân Huế giành chính quyền.","is_true":false,"explanation":"Đề đảo thứ tự: Huế giành chính quyền ngày 23-8, vua Bảo Đại thoái vị ngày 30-8-1945.","section_id":"muc-1","trap":"thoi_gian"}]'::jsonb, null, 'Câu kiểm tra trình tự thời gian của Tổng khởi nghĩa qua tư liệu.', '14-8 → 18-8 (bốn tỉnh) → 19-8 Hà Nội → 23-8 Huế → 25-8 Sài Gòn → 28-8 cả nước → 30-8 Bảo Đại thoái vị.', 12, '6-cach-mang-thang-tam-nam-1945', 'muc-1', null, 'nhan_biet', 'tim_hieu_lich_su', null, 'SGK Lịch sử 12 (KNTT), Bài 6, mục 1')
