update public.exam_items set content_key = 'b6-m1-ds-04'
 where content_key is null and fingerprint = public.exam_item_fingerprint('true_false', 'Đọc đoạn tư liệu về thời cơ của Tổng khởi nghĩa (tháng 8-1945) rồi cho biết mỗi ý sau đúng hay sai.', null, '[{"text":"Việc Nhật Bản đầu hàng Đồng minh (15-8-1945) là điều kiện khách quan tạo ra thời cơ.","is_true":true,"explanation":"Quân Nhật rệu rã, chính quyền tay sai hoang mang — thời cơ khách quan.","section_id":"muc-1"},{"text":"Quân lệnh số 1 do Quốc dân Đại hội Tân Trào ban bố.","is_true":false,"explanation":"Đề đánh tráo chủ thể: Quân lệnh số 1 do Ủy ban Khởi nghĩa toàn quốc ban bố (đêm 13-8), trước Quốc dân Đại hội (16-8).","section_id":"muc-1","trap":"chu_the"},{"text":"Thời cơ tồn tại trong khoảng từ khi Nhật đầu hàng đến trước khi quân Đồng minh vào Đông Dương.","is_true":true,"explanation":"Kẻ thù cũ đã gục ngã, kẻ thù mới chưa vào — thời cơ “ngàn năm có một”.","section_id":"muc-1"},{"text":"Theo tư liệu, nếu chờ quân Đồng minh vào giải giáp quân Nhật thì việc giành chính quyền sẽ thuận lợi hơn.","is_true":false,"explanation":"Suy luận sai: khi quân Trung Hoa Dân quốc và quân Anh đã vào, các thế lực thù địch có chỗ dựa để can thiệp — vì vậy Đảng chủ trương giành chính quyền trước khi Đồng minh vào.","section_id":"muc-1","trap":"ban_chat"}]'::jsonb)
   and not exists (select 1 from public.exam_items where content_key = 'b6-m1-ds-04');
insert into public.exam_items (content_key, kind, stem, passage_id, choices, correct_index, statements, choice_notes, explanation, remember, grade, lesson_slug, section_id, topic_tag, level, competency, event_id, source_note)
values ('b6-m1-ds-04', 'true_false', 'Đọc đoạn tư liệu về thời cơ của Tổng khởi nghĩa (tháng 8-1945) rồi cho biết mỗi ý sau đúng hay sai.', (select id from public.exam_passages where title = 'Thời cơ của Tổng khởi nghĩa tháng Tám năm 1945' and body = 'Ngày 15-8-1945, Nhật Bản tuyên bố đầu hàng Đồng minh không điều kiện. Quân Nhật ở Đông Dương rệu rã, mất tinh thần; chính phủ thân Nhật Trần Trọng Kim hoang mang, lo sợ. Theo thỏa thuận của các nước Đồng minh, quân Trung Hoa Dân quốc sẽ vào miền Bắc, quân Anh vào miền Nam (lấy vĩ tuyến 16 làm ranh giới) để giải giáp quân Nhật.
Ngay khi biết tin Nhật sắp đầu hàng, Ủy ban Khởi nghĩa toàn quốc được thành lập và đêm 13-8-1945 ban bố Quân lệnh số 1. Hội nghị toàn quốc của Đảng (14 – 15-8) và Quốc dân Đại hội ở Tân Trào (16-8) quyết định phát động Tổng khởi nghĩa, giành chính quyền từ tay Nhật và tay sai trước khi quân Đồng minh vào Đông Dương. Chủ tịch Hồ Chí Minh gửi thư kêu gọi: “Giờ quyết định cho vận mệnh dân tộc ta đã đến. Toàn quốc đồng bào hãy đứng dậy đem sức ta mà tự giải phóng cho ta.”' order by created_at limit 1), null, null, '[{"text":"Việc Nhật Bản đầu hàng Đồng minh (15-8-1945) là điều kiện khách quan tạo ra thời cơ.","is_true":true,"explanation":"Quân Nhật rệu rã, chính quyền tay sai hoang mang — thời cơ khách quan.","section_id":"muc-1"},{"text":"Quân lệnh số 1 do Quốc dân Đại hội Tân Trào ban bố.","is_true":false,"explanation":"Đề đánh tráo chủ thể: Quân lệnh số 1 do Ủy ban Khởi nghĩa toàn quốc ban bố (đêm 13-8), trước Quốc dân Đại hội (16-8).","section_id":"muc-1","trap":"chu_the"},{"text":"Thời cơ tồn tại trong khoảng từ khi Nhật đầu hàng đến trước khi quân Đồng minh vào Đông Dương.","is_true":true,"explanation":"Kẻ thù cũ đã gục ngã, kẻ thù mới chưa vào — thời cơ “ngàn năm có một”.","section_id":"muc-1"},{"text":"Theo tư liệu, nếu chờ quân Đồng minh vào giải giáp quân Nhật thì việc giành chính quyền sẽ thuận lợi hơn.","is_true":false,"explanation":"Suy luận sai: khi quân Trung Hoa Dân quốc và quân Anh đã vào, các thế lực thù địch có chỗ dựa để can thiệp — vì vậy Đảng chủ trương giành chính quyền trước khi Đồng minh vào.","section_id":"muc-1","trap":"ban_chat"}]'::jsonb, null, 'Câu đọc hiểu và suy luận về thời cơ và chủ trương của Đảng tháng 8-1945.', 'Thời cơ: sau khi Nhật đầu hàng, trước khi Đồng minh vào — Đảng chớp thời cơ phát động Tổng khởi nghĩa.', 12, '6-cach-mang-thang-tam-nam-1945', 'muc-1', null, 'van_dung', 'nhan_thuc_tu_duy', null, 'SGK Lịch sử 12 (KNTT), Bài 6, mục 1')
