update public.exam_items set content_key = 'b6-m1-ds-05'
 where content_key is null and fingerprint = public.exam_item_fingerprint('true_false', 'Dựa vào đoạn trích Tuyên ngôn độc lập về “sự thật” của nước Việt Nam, hãy xác định mỗi ý sau đúng hay sai.', null, '[{"text":"Theo tư liệu, nhân dân Việt Nam giành chính quyền từ tay Nhật khi Nhật đầu hàng Đồng minh.","is_true":true,"explanation":"“Dân ta đã lấy lại nước Việt Nam từ tay Nhật, chứ không phải từ tay Pháp.”","section_id":"muc-1"},{"text":"Tư liệu cho biết Việt Nam vẫn là thuộc địa của Pháp cho đến tháng 8-1945.","is_true":false,"explanation":"Trái tư liệu: “từ mùa thu năm 1940, nước ta đã thành thuộc địa của Nhật, chứ không phải thuộc địa của Pháp nữa”.","section_id":"muc-1","trap":"ban_chat"},{"text":"Tư liệu khẳng định cách mạng đã xóa bỏ cả ách thực dân lẫn chế độ quân chủ.","is_true":true,"explanation":"Đánh đổ “xiềng xích thực dân gần 100 năm” và “chế độ quân chủ mấy mươi thế kỷ”.","section_id":"muc-1"},{"text":"Lập luận của đoạn tư liệu nhằm thừa nhận quyền của Pháp được trở lại cai trị Đông Dương.","is_true":false,"explanation":"Ngược lại: lập luận này bác bỏ cơ sở để Pháp đòi quay lại, vì Pháp đã mất Đông Dương vào tay Nhật và nhân dân giành chính quyền từ tay Nhật.","section_id":"muc-1","trap":"ban_chat"}]'::jsonb)
   and not exists (select 1 from public.exam_items where content_key = 'b6-m1-ds-05');
insert into public.exam_items (content_key, kind, stem, passage_id, choices, correct_index, statements, choice_notes, explanation, remember, grade, lesson_slug, section_id, topic_tag, level, competency, event_id, source_note)
values ('b6-m1-ds-05', 'true_false', 'Dựa vào đoạn trích Tuyên ngôn độc lập về “sự thật” của nước Việt Nam, hãy xác định mỗi ý sau đúng hay sai.', (select id from public.exam_passages where title = 'Tuyên ngôn độc lập (2-9-1945) — đoạn về “sự thật”' and body = '“Sự thật là từ mùa thu năm 1940, nước ta đã thành thuộc địa của Nhật, chứ không phải thuộc địa của Pháp nữa. Khi Nhật hàng Đồng minh thì nhân dân cả nước ta đã nổi dậy giành chính quyền, lập nên nước Việt Nam Dân chủ Cộng hòa.
Sự thật là dân ta đã lấy lại nước Việt Nam từ tay Nhật, chứ không phải từ tay Pháp.
Pháp chạy, Nhật hàng, vua Bảo Đại thoái vị. Dân ta đã đánh đổ các xiềng xích thực dân gần 100 năm nay để gây dựng nên nước Việt Nam độc lập. Dân ta lại đánh đổ chế độ quân chủ mấy mươi thế kỷ mà lập nên chế độ Dân chủ Cộng hòa.”' order by created_at limit 1), null, null, '[{"text":"Theo tư liệu, nhân dân Việt Nam giành chính quyền từ tay Nhật khi Nhật đầu hàng Đồng minh.","is_true":true,"explanation":"“Dân ta đã lấy lại nước Việt Nam từ tay Nhật, chứ không phải từ tay Pháp.”","section_id":"muc-1"},{"text":"Tư liệu cho biết Việt Nam vẫn là thuộc địa của Pháp cho đến tháng 8-1945.","is_true":false,"explanation":"Trái tư liệu: “từ mùa thu năm 1940, nước ta đã thành thuộc địa của Nhật, chứ không phải thuộc địa của Pháp nữa”.","section_id":"muc-1","trap":"ban_chat"},{"text":"Tư liệu khẳng định cách mạng đã xóa bỏ cả ách thực dân lẫn chế độ quân chủ.","is_true":true,"explanation":"Đánh đổ “xiềng xích thực dân gần 100 năm” và “chế độ quân chủ mấy mươi thế kỷ”.","section_id":"muc-1"},{"text":"Lập luận của đoạn tư liệu nhằm thừa nhận quyền của Pháp được trở lại cai trị Đông Dương.","is_true":false,"explanation":"Ngược lại: lập luận này bác bỏ cơ sở để Pháp đòi quay lại, vì Pháp đã mất Đông Dương vào tay Nhật và nhân dân giành chính quyền từ tay Nhật.","section_id":"muc-1","trap":"ban_chat"}]'::jsonb, null, 'Câu đọc hiểu và đánh giá lập luận pháp lí của Tuyên ngôn độc lập.', 'Tuyên ngôn: nhân dân giành chính quyền từ tay Nhật, đánh đổ cả thực dân lẫn quân chủ — Pháp không còn cơ sở quay lại.', 12, '6-cach-mang-thang-tam-nam-1945', 'muc-1', null, 'van_dung', 'nhan_thuc_tu_duy', null, 'SGK Lịch sử 12 (KNTT), Bài 6, mục 1')
