 where content_key is null and fingerprint = public.exam_item_fingerprint('mcq', 'Hội nghị toàn quốc của Đảng (8-1945) quyết định phát động Tổng khởi nghĩa giành chính quyền họp ở đâu?', array['Đình Bảng (Bắc Ninh)', 'Hương Cảng (Trung Quốc)', 'Tân Trào (Tuyên Quang)', 'Pác Bó (Cao Bằng)'], null)
   and not exists (select 1 from public.exam_items where content_key = 'b6-m1-tn-01');
insert into public.exam_items (content_key, kind, stem, passage_id, choices, correct_index, statements, choice_notes, explanation, remember, grade, lesson_slug, section_id, topic_tag, level, competency, event_id, source_note)
values ('b6-m1-tn-01', 'mcq', 'Hội nghị toàn quốc của Đảng (8-1945) quyết định phát động Tổng khởi nghĩa giành chính quyền họp ở đâu?', null, array['Đình Bảng (Bắc Ninh)', 'Hương Cảng (Trung Quốc)', 'Tân Trào (Tuyên Quang)', 'Pác Bó (Cao Bằng)'], 2, null, '[{"note":"Đình Bảng (Từ Sơn, Bắc Ninh) là nơi Ban Thường vụ Trung ương Đảng họp tháng 3-1945, ra Chỉ thị “Nhật – Pháp bắn nhau và hành động của chúng ta” — không phải nơi họp Hội nghị toàn quốc tháng 8-1945.","section_id":"muc-1","trap":"dia_diem"},{"note":"Hương Cảng (Trung Quốc) là nơi Nguyễn Ái Quốc chủ trì hội nghị hợp nhất các tổ chức cộng sản, thành lập Đảng Cộng sản Việt Nam (đầu năm 1930) — 15 năm trước Tổng khởi nghĩa.","lesson_slug":"16-ho-chi-minh-anh-hung-giai-phong-dan-toc","section_id":"muc-1","trap":"dia_diem"},{"note":"Đúng. Hội nghị toàn quốc của Đảng họp ở Tân Trào (Tuyên Quang) ngày 14 và 15-8-1945, quyết định phát động Tổng khởi nghĩa giành chính quyền trước khi quân Đồng minh vào Đông Dương.","section_id":"muc-1"},{"note":"Pác Bó (Cao Bằng) là nơi Nguyễn Ái Quốc về nước (1941) và chủ trì Hội nghị Trung ương 8 (5-1941) thành lập Mặt trận Việt Minh — không phải nơi họp Hội nghị toàn quốc tháng 8-1945.","lesson_slug":"16-ho-chi-minh-anh-hung-giai-phong-dan-toc","section_id":"muc-2","trap":"dia_diem"}]'::jsonb, 'Hội nghị toàn quốc của Đảng họp ở Tân Trào ngày 14 và 15-8-1945, quyết định phát động Tổng khởi nghĩa; tiếp đó Quốc dân Đại hội cũng họp ở Tân Trào (16-8-1945).', 'Tân Trào (Tuyên Quang), 14 – 15-8-1945: Hội nghị toàn quốc của Đảng quyết định Tổng khởi nghĩa; ngày 16-8: Quốc dân Đại hội.', 12, '6-cach-mang-thang-tam-nam-1945', 'muc-1', null, 'nhan_biet', 'tim_hieu_lich_su', null, 'SGK Lịch sử 12 (KNTT), Bài 6, mục 1')
