 where content_key is null and fingerprint = public.exam_item_fingerprint('mcq', 'Thời cơ “ngàn năm có một” để nhân dân Việt Nam tiến hành Tổng khởi nghĩa tháng Tám năm 1945 xuất hiện khi', array['Pháp đưa quân trở lại Đông Dương', 'Nhật Bản đầu hàng Đồng minh không điều kiện', 'Nhật đảo chính Pháp ở Đông Dương', 'quân Đồng minh vào giải giáp quân Nhật'], null)
   and not exists (select 1 from public.exam_items where content_key = 'b6-m1-tn-02');
insert into public.exam_items (content_key, kind, stem, passage_id, choices, correct_index, statements, choice_notes, explanation, remember, grade, lesson_slug, section_id, topic_tag, level, competency, event_id, source_note)
values ('b6-m1-tn-02', 'mcq', 'Thời cơ “ngàn năm có một” để nhân dân Việt Nam tiến hành Tổng khởi nghĩa tháng Tám năm 1945 xuất hiện khi', null, array['Pháp đưa quân trở lại Đông Dương', 'Nhật Bản đầu hàng Đồng minh không điều kiện', 'Nhật đảo chính Pháp ở Đông Dương', 'quân Đồng minh vào giải giáp quân Nhật'], 1, null, '[{"note":"Pháp đưa quân trở lại (từ tháng 9-1945 ở Nam Bộ) diễn ra SAU Tổng khởi nghĩa và là nguy cơ đối với chính quyền cách mạng, không phải thời cơ.","lesson_slug":"7-khang-chien-chong-phap","section_id":"muc-1","trap":"thoi_gian"},{"note":"Đúng. Ngày 15-8-1945 Nhật đầu hàng Đồng minh không điều kiện: quân Nhật ở Đông Dương rệu rã, chính quyền tay sai hoang mang, trong khi quân Đồng minh chưa vào — thời cơ “ngàn năm có một”.","section_id":"muc-1"},{"note":"Nhật đảo chính Pháp (9-3-1945) mở ra cao trào kháng Nhật cứu nước, tạo điều kiện cho khởi nghĩa từng phần — chưa phải thời cơ Tổng khởi nghĩa vì quân Nhật còn mạnh.","section_id":"muc-1","trap":"thoi_gian"},{"note":"Khi quân Đồng minh vào giải giáp quân Nhật thì thời cơ đã qua: nhân dân phải giành chính quyền TRƯỚC khi Đồng minh vào để đứng ở vị thế người làm chủ.","section_id":"muc-1","trap":"thoi_gian"}]'::jsonb, 'Ngày 15-8-1945 Nhật đầu hàng Đồng minh, quân Nhật ở Đông Dương rệu rã, chính quyền tay sai hoang mang — trước khi quân Đồng minh vào. Đó là thời cơ để Tổng khởi nghĩa.', 'Thời cơ Tổng khởi nghĩa: sau khi Nhật đầu hàng Đồng minh (15-8-1945) và trước khi quân Đồng minh vào Đông Dương.', 12, '6-cach-mang-thang-tam-nam-1945', 'muc-1', null, 'thong_hieu', 'nhan_thuc_tu_duy', null, 'SGK Lịch sử 12 (KNTT), Bài 6, mục 1')
