values ('b6-m1-tn-03', 'mcq', 'Ngày 30-8-1945 diễn ra sự kiện nào?', null, array['Vua Bảo Đại thoái vị', 'Khởi nghĩa giành chính quyền ở Hà Nội thắng lợi', 'Quốc dân Đại hội họp ở Tân Trào', 'Chủ tịch Hồ Chí Minh đọc Tuyên ngôn độc lập'], 0, null, '[{"note":"Đúng. Ngày 30-8-1945, tại Ngọ Môn (Huế), vua Bảo Đại thoái vị — chế độ quân chủ ở Việt Nam sụp đổ.","section_id":"muc-1"},{"note":"Khởi nghĩa ở Hà Nội thắng lợi ngày 19-8-1945, trước đó 11 ngày.","section_id":"muc-1","trap":"thoi_gian"},{"note":"Quốc dân Đại hội họp ở Tân Trào ngày 16-8-1945.","section_id":"muc-1","trap":"thoi_gian"},{"note":"Tuyên ngôn độc lập được đọc ngày 2-9-1945 tại Quảng trường Ba Đình.","section_id":"muc-1","trap":"thoi_gian"}]'::jsonb, 'Ngày 30-8-1945 vua Bảo Đại thoái vị, chế độ quân chủ chấm dứt. Hà Nội giành chính quyền ngày 19-8; Quốc dân Đại hội họp ngày 16-8; Tuyên ngôn độc lập được đọc ngày 2-9.', '30-8-1945: vua Bảo Đại thoái vị tại Ngọ Môn (Huế) — chế độ quân chủ sụp đổ.', 12, '6-cach-mang-thang-tam-nam-1945', 'muc-1', null, 'nhan_biet', 'tim_hieu_lich_su', null, 'SGK Lịch sử 12 (KNTT), Bài 6, mục 1')
