values ('b6-m1-tn-04', 'mcq', 'Quốc dân Đại hội họp ở Tân Trào (16-8-1945) đã', null, array['thành lập Mặt trận Việt Nam độc lập đồng minh', 'đọc Tuyên ngôn độc lập, khai sinh nước Việt Nam Dân chủ Cộng hòa', 'ra Quân lệnh số 1, phát lệnh Tổng khởi nghĩa trong cả nước', 'cử ra Ủy ban Dân tộc giải phóng Việt Nam do Hồ Chí Minh làm Chủ tịch'], 3, null, '[{"note":"Mặt trận Việt Minh thành lập ngày 19-5-1941 theo quyết định của Hội nghị Trung ương 8 ở Pác Bó, không phải tại Quốc dân Đại hội.","lesson_slug":"16-ho-chi-minh-anh-hung-giai-phong-dan-toc","section_id":"muc-2","trap":"thoi_gian"},{"note":"Tuyên ngôn độc lập được Chủ tịch Hồ Chí Minh đọc ngày 2-9-1945 ở Hà Nội — sau khi Tổng khởi nghĩa thắng lợi.","section_id":"muc-1","trap":"thoi_gian"},{"note":"Quân lệnh số 1 do Ủy ban Khởi nghĩa toàn quốc ban bố đêm 13-8-1945, trước Quốc dân Đại hội.","section_id":"muc-1","trap":"chu_the"},{"note":"Đúng. Quốc dân Đại hội tán thành chủ trương Tổng khởi nghĩa, thông qua 10 chính sách lớn của Việt Minh, quy định Quốc kì, Quốc ca và cử ra Ủy ban Dân tộc giải phóng Việt Nam do Hồ Chí Minh làm Chủ tịch.","section_id":"muc-1"}]'::jsonb, 'Phân biệt bốn sự kiện ở Tân Trào và Hà Nội tháng 8 – 9-1945: Quân lệnh số 1 (13-8), Hội nghị toàn quốc của Đảng (14 – 15-8), Quốc dân Đại hội (16-8), Tuyên ngôn độc lập (2-9).', 'Quốc dân Đại hội Tân Trào (16-8-1945) cử ra Ủy ban Dân tộc giải phóng Việt Nam — sau này cải tổ thành Chính phủ lâm thời.', 12, '6-cach-mang-thang-tam-nam-1945', 'muc-1', null, 'nhan_biet', 'tim_hieu_lich_su', null, 'SGK Lịch sử 12 (KNTT), Bài 6, mục 1')
