insert into public.exam_items (content_key, kind, stem, passage_id, choices, correct_index, statements, choice_notes, explanation, remember, grade, lesson_slug, section_id, topic_tag, level, competency, event_id, source_note)
values ('b6-m1-tn-05', 'mcq', 'Địa phương nào sau đây là một trong bốn tỉnh giành chính quyền ở tỉnh lị sớm nhất trong cả nước (ngày 18-8-1945)?', null, array['Hà Tĩnh', 'Hà Nội', 'Huế', 'Hà Tiên'], 0, null, '[{"note":"Đúng. Ngày 18-8-1945, Bắc Giang, Hải Dương, Hà Tĩnh và Quảng Nam là bốn tỉnh giành chính quyền ở tỉnh lị sớm nhất.","section_id":"muc-1"},{"note":"Hà Nội giành chính quyền ngày 19-8-1945, sau bốn tỉnh trên một ngày.","section_id":"muc-1","trap":"thoi_gian"},{"note":"Huế giành chính quyền ngày 23-8-1945.","section_id":"muc-1","trap":"thoi_gian"},{"note":"Hà Tiên cùng Đồng Nai Thượng là những nơi giành chính quyền muộn nhất (28-8-1945).","section_id":"muc-1","trap":"thoi_gian"}]'::jsonb, 'Thứ tự giành chính quyền: bốn tỉnh Bắc Giang, Hải Dương, Hà Tĩnh, Quảng Nam (18-8) → Hà Nội (19-8) → Huế (23-8) → Sài Gòn (25-8) → Đồng Nai Thượng, Hà Tiên (28-8).', '18-8-1945: Bắc Giang, Hải Dương, Hà Tĩnh, Quảng Nam giành chính quyền ở tỉnh lị sớm nhất.', 12, '6-cach-mang-thang-tam-nam-1945', 'muc-1', null, 'nhan_biet', 'tim_hieu_lich_su', null, 'SGK Lịch sử 12 (KNTT), Bài 6, mục 1')
