values ('b6-m1-tn-06', 'mcq', 'Khởi nghĩa giành chính quyền ở Hà Nội thắng lợi vào ngày', null, array['23-8-1945', '25-8-1945', '19-8-1945', '2-9-1945'], 2, null, '[{"note":"Ngày 23-8-1945 là ngày khởi nghĩa giành chính quyền thắng lợi ở Huế.","section_id":"muc-1","trap":"thoi_gian"},{"note":"Ngày 25-8-1945 là ngày khởi nghĩa giành chính quyền thắng lợi ở Sài Gòn.","section_id":"muc-1","trap":"thoi_gian"},{"note":"Đúng. Ngày 19-8-1945, cuộc mít tinh lớn ở Quảng trường Nhà hát Lớn chuyển thành khởi nghĩa; quần chúng chiếm Phủ Khâm sai và các cơ quan đầu não của chính quyền tay sai — Hà Nội giành chính quyền.","section_id":"muc-1"},{"note":"Ngày 2-9-1945 là ngày Chủ tịch Hồ Chí Minh đọc Tuyên ngôn độc lập ở Quảng trường Ba Đình.","section_id":"muc-1","trap":"thoi_gian"}]'::jsonb, 'Ba trung tâm lớn: Hà Nội 19-8, Huế 23-8, Sài Gòn 25-8-1945.', 'Hà Nội 19-8 · Huế 23-8 · Sài Gòn 25-8-1945.', 12, '6-cach-mang-thang-tam-nam-1945', 'muc-1', null, 'nhan_biet', 'tim_hieu_lich_su', (select id from public.historical_events where slug = 'tong-khoi-nghia-gianh-chinh-quyen-o-ha-noi'), 'SGK Lịch sử 12 (KNTT), Bài 6, mục 1')
