values ('b6-m1-tn-07', 'mcq', 'Ngày 2-9-1945, tại Quảng trường Ba Đình (Hà Nội), Chủ tịch Hồ Chí Minh đã', null, array['đọc Lời kêu gọi toàn quốc kháng chiến', 'đọc Tuyên ngôn độc lập, khai sinh nước Việt Nam Dân chủ Cộng hòa', 'kí Hiệp định Sơ bộ với đại diện Chính phủ Pháp', 'công bố Quân lệnh số 1, phát động Tổng khởi nghĩa'], 1, null, '[{"note":"Lời kêu gọi toàn quốc kháng chiến ra đời ngày 19-12-1946, mở đầu cuộc kháng chiến toàn quốc chống Pháp.","lesson_slug":"7-khang-chien-chong-phap","section_id":"muc-1","trap":"thoi_gian"},{"note":"Đúng. Ngày 2-9-1945, Chủ tịch Hồ Chí Minh đọc Tuyên ngôn độc lập, tuyên bố thành lập nước Việt Nam Dân chủ Cộng hòa.","section_id":"muc-1"},{"note":"Hiệp định Sơ bộ được kí ngày 6-3-1946 tại Hà Nội, không phải ngày 2-9-1945.","lesson_slug":"7-khang-chien-chong-phap","section_id":"muc-1","trap":"thoi_gian"},{"note":"Quân lệnh số 1 do Ủy ban Khởi nghĩa toàn quốc ban bố đêm 13-8-1945, trước khi Tổng khởi nghĩa nổ ra.","section_id":"muc-1","trap":"thoi_gian"}]'::jsonb, 'Ba văn kiện dễ nhầm: Tuyên ngôn độc lập (2-9-1945), Hiệp định Sơ bộ (6-3-1946), Lời kêu gọi toàn quốc kháng chiến (19-12-1946).', '2-9-1945: Tuyên ngôn độc lập — nước Việt Nam Dân chủ Cộng hòa ra đời.', 12, '6-cach-mang-thang-tam-nam-1945', 'muc-1', null, 'nhan_biet', 'tim_hieu_lich_su', (select id from public.historical_events where slug = 'tuyen-ngon-doc-lap'), 'SGK Lịch sử 12 (KNTT), Bài 6, mục 1')
