insert into public.exam_items (content_key, kind, stem, passage_id, choices, correct_index, statements, choice_notes, explanation, remember, grade, lesson_slug, section_id, topic_tag, level, competency, event_id, source_note)
values ('b6-m1-tn-08', 'mcq', 'Cuộc Tổng khởi nghĩa tháng Tám năm 1945 giành thắng lợi trong cả nước trong khoảng thời gian', null, array['khoảng 1 tháng (từ 15-8 đến 15-9-1945)', 'gần 6 tháng (từ 9-3 đến 2-9-1945)', 'đúng 1 ngày (ngày 19-8-1945)', 'khoảng 15 ngày (từ 14 đến 28-8-1945)'], 3, null, '[{"note":"Đến ngày 28-8-1945 cả nước đã giành chính quyền; mốc 15-9 không gắn với sự kiện nào của Tổng khởi nghĩa.","section_id":"muc-1","trap":"so_lieu"},{"note":"Từ 9-3-1945 (Nhật đảo chính Pháp) là cao trào kháng Nhật cứu nước — giai đoạn chuẩn bị, không phải thời gian Tổng khởi nghĩa.","section_id":"muc-1","trap":"ban_chat"},{"note":"Ngày 19-8-1945 chỉ là ngày Hà Nội giành chính quyền; các địa phương khác nổi dậy từ 14 đến 28-8.","section_id":"muc-1","trap":"tuyet_doi"},{"note":"Đúng. Chỉ trong khoảng 15 ngày (từ 14 đến 28-8-1945), Tổng khởi nghĩa giành thắng lợi trên cả nước.","section_id":"muc-1"}]'::jsonb, 'Tổng khởi nghĩa diễn ra nhanh, ít đổ máu vì nổ ra đúng thời cơ, sau quá trình chuẩn bị lâu dài.', 'Tổng khởi nghĩa: 14 → 28-8-1945, khoảng 15 ngày.', 12, '6-cach-mang-thang-tam-nam-1945', 'muc-1', null, 'nhan_biet', 'tim_hieu_lich_su', null, 'SGK Lịch sử 12 (KNTT), Bài 6, mục 1')
