 where content_key is null and fingerprint = public.exam_item_fingerprint('mcq', 'Khởi nghĩa giành chính quyền ở Hà Nội (19-8-1945) có ý nghĩa đặc biệt quan trọng vì', array['Hà Nội là địa phương đầu tiên giành chính quyền trong cả nước', 'thắng lợi ở Hà Nội buộc vua Bảo Đại thoái vị ngay trong ngày', 'Hà Nội là trung tâm chính trị, thắng lợi ở đây cổ vũ cả nước nổi dậy', 'Hà Nội là nơi quân Đồng minh vào giải giáp quân Nhật đầu tiên'], null)
