insert into public.exam_items (content_key, kind, stem, passage_id, choices, correct_index, statements, choice_notes, explanation, remember, grade, lesson_slug, section_id, topic_tag, level, competency, event_id, source_note)
values ('b6-m1-tn-09', 'mcq', 'Khởi nghĩa giành chính quyền ở Hà Nội (19-8-1945) có ý nghĩa đặc biệt quan trọng vì', null, array['Hà Nội là địa phương đầu tiên giành chính quyền trong cả nước', 'thắng lợi ở Hà Nội buộc vua Bảo Đại thoái vị ngay trong ngày', 'Hà Nội là trung tâm chính trị, thắng lợi ở đây cổ vũ cả nước nổi dậy', 'Hà Nội là nơi quân Đồng minh vào giải giáp quân Nhật đầu tiên'], 2, null, '[{"note":"Sai thời gian: bốn tỉnh Bắc Giang, Hải Dương, Hà Tĩnh, Quảng Nam đã giành chính quyền ngày 18-8, trước Hà Nội.","section_id":"muc-1","trap":"thoi_gian"},{"note":"Vua Bảo Đại thoái vị ngày 30-8-1945, sau khi Huế (23-8) và Sài Gòn (25-8) đã giành chính quyền.","section_id":"muc-1","trap":"thoi_gian"},{"note":"Đúng. Hà Nội là trung tâm chính trị, nơi đặt cơ quan đầu não của chính quyền tay sai ở Bắc Bộ; thắng lợi ở Hà Nội cùng Huế, Sài Gòn có ý nghĩa quyết định, cổ vũ các địa phương khác.","section_id":"muc-1"},{"note":"Quân Trung Hoa Dân quốc chỉ vào miền Bắc sau khi ta đã giành chính quyền; thắng lợi ở Hà Nội không gắn với việc giải giáp quân Nhật.","lesson_slug":"7-khang-chien-chong-phap","section_id":"muc-1","trap":"ban_chat"}]'::jsonb, 'Thắng lợi ở các trung tâm chính trị lớn (Hà Nội, Huế, Sài Gòn) quyết định thắng lợi của Tổng khởi nghĩa.', 'Thắng lợi ở Hà Nội, Huế, Sài Gòn có ý nghĩa quyết định đối với Tổng khởi nghĩa.', 12, '6-cach-mang-thang-tam-nam-1945', 'muc-1', null, 'thong_hieu', 'nhan_thuc_tu_duy', (select id from public.historical_events where slug = 'tong-khoi-nghia-gianh-chinh-quyen-o-ha-noi'), 'SGK Lịch sử 12 (KNTT), Bài 6, mục 1')
