 where content_key is null and fingerprint = public.exam_item_fingerprint('mcq', 'Sau cuộc đảo chính ngày 9-3-1945, Đảng xác định kẻ thù chính, cụ thể, trước mắt của nhân dân Đông Dương là', array['phát xít Nhật', 'thực dân Pháp', 'cả thực dân Pháp và phát xít Nhật', 'chính phủ thân Nhật Trần Trọng Kim'], null)
   and not exists (select 1 from public.exam_items where content_key = 'b6-m1-tn-10');
insert into public.exam_items (content_key, kind, stem, passage_id, choices, correct_index, statements, choice_notes, explanation, remember, grade, lesson_slug, section_id, topic_tag, level, competency, event_id, source_note)
values ('b6-m1-tn-10', 'mcq', 'Sau cuộc đảo chính ngày 9-3-1945, Đảng xác định kẻ thù chính, cụ thể, trước mắt của nhân dân Đông Dương là', null, array['phát xít Nhật', 'thực dân Pháp', 'cả thực dân Pháp và phát xít Nhật', 'chính phủ thân Nhật Trần Trọng Kim'], 0, null, '[{"note":"Đúng. Chỉ thị “Nhật – Pháp bắn nhau và hành động của chúng ta” (12-3-1945) xác định phát xít Nhật là kẻ thù chính, phát động cao trào kháng Nhật cứu nước.","section_id":"muc-1"},{"note":"Sau khi bị Nhật đảo chính (9-3-1945), Pháp mất quyền thống trị ở Đông Dương; Pháp chỉ trở lại thành kẻ thù chính từ sau tháng 9-1945.","lesson_slug":"7-khang-chien-chong-phap","section_id":"muc-1","trap":"thoi_gian"},{"note":"Pháp – Nhật cùng là kẻ thù chỉ đúng với thời kì trước ngày 9-3-1945, khi Nhật – Pháp cùng thống trị Đông Dương; sau đảo chính, Pháp đã mất quyền thống trị.","section_id":"muc-1","trap":"thoi_gian"},{"note":"Chính phủ Trần Trọng Kim (thành lập tháng 4-1945) chỉ là tay sai của Nhật; kẻ thù chính, cụ thể, trước mắt là phát xít Nhật.","section_id":"muc-1","trap":"chu_the"}]'::jsonb, 'Nhật đảo chính Pháp làm thay đổi kẻ thù chính: từ đây đến tháng 8-1945, nhân dân Đông Dương đấu tranh chống phát xít Nhật.', 'Sau 9-3-1945: kẻ thù chính là phát xít Nhật → cao trào kháng Nhật cứu nước.', 12, '6-cach-mang-thang-tam-nam-1945', 'muc-1', null, 'thong_hieu', 'nhan_thuc_tu_duy', null, 'SGK Lịch sử 12 (KNTT), Bài 6, mục 1')
