update public.exam_items set content_key = 'b6-m1-tn-11'
 where content_key is null and fingerprint = public.exam_item_fingerprint('mcq', 'Việc Quốc dân Đại hội Tân Trào quy định Quốc kì, Quốc ca và cử ra Ủy ban Dân tộc giải phóng Việt Nam ngay trước Tổng khởi nghĩa có tác dụng gì?', array['Thay thế hoàn toàn việc phải khởi nghĩa giành chính quyền ở các địa phương', 'Chuẩn bị sẵn những yếu tố của một nhà nước mới để thay thế chính quyền cũ', 'Giúp nước Việt Nam được quân Đồng minh công nhận ngay lập tức', 'Tạo cơ sở để thương lượng với Nhật về việc trao trả chính quyền'], null)
   and not exists (select 1 from public.exam_items where content_key = 'b6-m1-tn-11');
insert into public.exam_items (content_key, kind, stem, passage_id, choices, correct_index, statements, choice_notes, explanation, remember, grade, lesson_slug, section_id, topic_tag, level, competency, event_id, source_note)
values ('b6-m1-tn-11', 'mcq', 'Việc Quốc dân Đại hội Tân Trào quy định Quốc kì, Quốc ca và cử ra Ủy ban Dân tộc giải phóng Việt Nam ngay trước Tổng khởi nghĩa có tác dụng gì?', null, array['Thay thế hoàn toàn việc phải khởi nghĩa giành chính quyền ở các địa phương', 'Chuẩn bị sẵn những yếu tố của một nhà nước mới để thay thế chính quyền cũ', 'Giúp nước Việt Nam được quân Đồng minh công nhận ngay lập tức', 'Tạo cơ sở để thương lượng với Nhật về việc trao trả chính quyền'], 1, null, '[{"note":"Hiểu sai bản chất: Quốc dân Đại hội tán thành chủ trương Tổng khởi nghĩa — chính quyền vẫn phải do nhân dân các địa phương nổi dậy giành lấy.","section_id":"muc-1","trap":"ban_chat"},{"note":"Đúng. Quốc kì, Quốc ca và cơ quan lãnh đạo (Ủy ban Dân tộc giải phóng, sau cải tổ thành Chính phủ lâm thời) đã có trước, nên khi giành được chính quyền, nhà nước mới ra đời ngay.","section_id":"muc-1"},{"note":"Các nước Đồng minh không công nhận nước Việt Nam Dân chủ Cộng hòa trong năm 1945; quân Đồng minh vào Đông Dương với danh nghĩa giải giáp quân Nhật.","lesson_slug":"7-khang-chien-chong-phap","section_id":"muc-1","trap":"ban_chat"},{"note":"Chủ trương của Đảng là giành chính quyền bằng khởi nghĩa của toàn dân, không thương lượng để Nhật trao trả chính quyền.","section_id":"muc-1","trap":"ban_chat"}]'::jsonb, 'Câu đánh giá tác dụng của Quốc dân Đại hội: chuẩn bị về mặt nhà nước cho chính quyền cách mạng.', 'Quốc dân Đại hội Tân Trào: tán thành Tổng khởi nghĩa, 10 chính sách của Việt Minh, Quốc kì – Quốc ca, Ủy ban Dân tộc giải phóng.', 12, '6-cach-mang-thang-tam-nam-1945', 'muc-1', null, 'van_dung', 'nhan_thuc_tu_duy', null, 'SGK Lịch sử 12 (KNTT), Bài 6, mục 1')
