update public.exam_items set content_key = 'b6-m1-tn-12'
 where content_key is null and fingerprint = public.exam_item_fingerprint('mcq', 'Những điều mà tác giả gọi là “lẽ phải không ai chối cãi được” giữ vai trò gì trong lập luận của Tuyên ngôn độc lập?', array['Khẳng định Việt Nam sẽ đi theo con đường cách mạng của Mỹ', 'Chủ yếu nhằm ca ngợi các cuộc cách mạng ở Mỹ và Pháp', 'Khẳng định quyền con người quan trọng hơn quyền dân tộc', 'Làm cơ sở chính nghĩa cho quyền độc lập của Việt Nam'], null)
   and not exists (select 1 from public.exam_items where content_key = 'b6-m1-tn-12');
insert into public.exam_items (content_key, kind, stem, passage_id, choices, correct_index, statements, choice_notes, explanation, remember, grade, lesson_slug, section_id, topic_tag, level, competency, event_id, source_note)
values ('b6-m1-tn-12', 'mcq', 'Những điều mà tác giả gọi là “lẽ phải không ai chối cãi được” giữ vai trò gì trong lập luận của Tuyên ngôn độc lập?', (select id from public.exam_passages where title = 'Tuyên ngôn độc lập (2-9-1945) — đoạn mở đầu' and body = '“Hỡi đồng bào cả nước,
Tất cả mọi người đều sinh ra có quyền bình đẳng. Tạo hóa cho họ những quyền không ai có thể xâm phạm được; trong những quyền ấy, có quyền được sống, quyền tự do và quyền mưu cầu hạnh phúc.
Lời bất hủ ấy ở trong bản Tuyên ngôn Độc lập năm 1776 của nước Mỹ. Suy rộng ra, câu ấy có ý nghĩa là: tất cả các dân tộc trên thế giới đều sinh ra bình đẳng, dân tộc nào cũng có quyền sống, quyền sung sướng và quyền tự do.
Bản Tuyên ngôn Nhân quyền và Dân quyền của Cách mạng Pháp năm 1791 cũng nói: Người ta sinh ra tự do và bình đẳng về quyền lợi; và phải luôn luôn được tự do và bình đẳng về quyền lợi.
Đó là những lẽ phải không ai chối cãi được.”' order by created_at limit 1), array['Khẳng định Việt Nam sẽ đi theo con đường cách mạng của Mỹ', 'Chủ yếu nhằm ca ngợi các cuộc cách mạng ở Mỹ và Pháp', 'Khẳng định quyền con người quan trọng hơn quyền dân tộc', 'Làm cơ sở chính nghĩa cho quyền độc lập của Việt Nam'], 3, null, '[{"note":"Hiểu sai: Tuyên ngôn dẫn văn kiện của Mỹ để lập luận về quyền bình đẳng, không tuyên bố đi theo con đường cách mạng của Mỹ.","section_id":"muc-1","trap":"ban_chat"},{"note":"Tuyệt đối hóa: trích dẫn là để làm tiền đề cho lập luận về quyền dân tộc, không chủ yếu để ca ngợi cách mạng nước khác.","section_id":"muc-1","trap":"tuyet_doi"},{"note":"Ngược tư liệu: tác giả “suy rộng ra” từ quyền con người thành quyền dân tộc — không đặt hai quyền đối lập nhau.","section_id":"muc-1","trap":"ban_chat"},{"note":"Đúng. Dẫn những “lẽ phải không ai chối cãi được” từ chính văn kiện của Mỹ và Pháp, Hồ Chí Minh khẳng định quyền độc lập của Việt Nam là chính đáng, đồng thời ngăn trước luận điệu của thực dân Pháp.","section_id":"muc-1"}]'::jsonb, 'Câu đọc hiểu cách lập luận của Tuyên ngôn độc lập: dùng giá trị phổ quát để khẳng định quyền dân tộc.', 'Tuyên ngôn độc lập dẫn văn kiện của Mỹ (1776) và Pháp để khẳng định quyền độc lập của dân tộc là “lẽ phải không ai chối cãi được”.', 12, '6-cach-mang-thang-tam-nam-1945', 'muc-1', null, 'van_dung', 'van_dung_kien_thuc', (select id from public.historical_events where slug = 'tuyen-ngon-doc-lap'), 'SGK Lịch sử 12 (KNTT), Bài 6, mục 1')
