values ('b6-m1-tn-13', 'mcq', 'Theo đoạn tư liệu, từ quyền của mỗi con người, tác giả “suy rộng ra” thành quyền nào của các dân tộc?', (select id from public.exam_passages where title = 'Tuyên ngôn độc lập (2-9-1945) — đoạn mở đầu' and body = '“Hỡi đồng bào cả nước,
Tất cả mọi người đều sinh ra có quyền bình đẳng. Tạo hóa cho họ những quyền không ai có thể xâm phạm được; trong những quyền ấy, có quyền được sống, quyền tự do và quyền mưu cầu hạnh phúc.
Lời bất hủ ấy ở trong bản Tuyên ngôn Độc lập năm 1776 của nước Mỹ. Suy rộng ra, câu ấy có ý nghĩa là: tất cả các dân tộc trên thế giới đều sinh ra bình đẳng, dân tộc nào cũng có quyền sống, quyền sung sướng và quyền tự do.
Bản Tuyên ngôn Nhân quyền và Dân quyền của Cách mạng Pháp năm 1791 cũng nói: Người ta sinh ra tự do và bình đẳng về quyền lợi; và phải luôn luôn được tự do và bình đẳng về quyền lợi.
Đó là những lẽ phải không ai chối cãi được.”' order by created_at limit 1), array['Quyền bình đẳng, quyền sống, quyền sung sướng và quyền tự do', 'Quyền sống, quyền tự do và quyền mưu cầu hạnh phúc của mỗi người', 'Quyền tự do và bình đẳng về quyền lợi của mỗi người', 'Quyền bầu cử và ứng cử của mọi công dân'], 0, null, '[{"note":"Đúng. “Tất cả các dân tộc trên thế giới đều sinh ra bình đẳng, dân tộc nào cũng có quyền sống, quyền sung sướng và quyền tự do.”","section_id":"muc-1"},{"note":"Nhầm khái niệm: đây là quyền con người trong Tuyên ngôn của Mỹ — điểm xuất phát, chưa phải điều tác giả “suy rộng ra”.","section_id":"muc-1","trap":"khai_niem"},{"note":"Nhầm khái niệm: đây là quyền của mỗi người trong Tuyên ngôn của Cách mạng Pháp, không phải quyền của các dân tộc.","section_id":"muc-1","trap":"khai_niem"},{"note":"Nhầm khái niệm: quyền bầu cử, ứng cử là quyền công dân (thực hiện trong Tổng tuyển cử ngày 6-1-1946), không phải nội dung “suy rộng ra” của tư liệu.","lesson_slug":"7-khang-chien-chong-phap","section_id":"muc-1","trap":"khai_niem"}]'::jsonb, 'Từ quyền con người (Tuyên ngôn của Mỹ), Hồ Chí Minh phát triển thành quyền dân tộc — đóng góp quan trọng về lí luận.', 'Từ quyền con người, Hồ Chí Minh “suy rộng ra” quyền dân tộc: mọi dân tộc đều bình đẳng, có quyền sống, sung sướng và tự do.', 12, '6-cach-mang-thang-tam-nam-1945', 'muc-1', null, 'thong_hieu', 'nhan_thuc_tu_duy', null, 'SGK Lịch sử 12 (KNTT), Bài 6, mục 1')
