insert into public.exam_items (content_key, kind, stem, passage_id, choices, correct_index, statements, choice_notes, explanation, remember, grade, lesson_slug, section_id, topic_tag, level, competency, event_id, source_note)
values ('b6-m1-tn-14', 'mcq', 'Theo đoạn trích Tuyên ngôn độc lập, nhân dân Việt Nam đã lấy lại nước Việt Nam từ tay', (select id from public.exam_passages where title = 'Tuyên ngôn độc lập (2-9-1945) — đoạn về “sự thật”' and body = '“Sự thật là từ mùa thu năm 1940, nước ta đã thành thuộc địa của Nhật, chứ không phải thuộc địa của Pháp nữa. Khi Nhật hàng Đồng minh thì nhân dân cả nước ta đã nổi dậy giành chính quyền, lập nên nước Việt Nam Dân chủ Cộng hòa.
Sự thật là dân ta đã lấy lại nước Việt Nam từ tay Nhật, chứ không phải từ tay Pháp.
Pháp chạy, Nhật hàng, vua Bảo Đại thoái vị. Dân ta đã đánh đổ các xiềng xích thực dân gần 100 năm nay để gây dựng nên nước Việt Nam độc lập. Dân ta lại đánh đổ chế độ quân chủ mấy mươi thế kỷ mà lập nên chế độ Dân chủ Cộng hòa.”' order by created_at limit 1), array['thực dân Pháp', 'phát xít Nhật', 'quân Trung Hoa Dân quốc', 'quân Anh'], 1, null, '[{"note":"Đánh tráo chủ thể: Tuyên ngôn viết rõ “dân ta đã lấy lại nước Việt Nam từ tay Nhật, chứ không phải từ tay Pháp” — từ mùa thu 1940 nước ta đã thành thuộc địa của Nhật.","section_id":"muc-1","trap":"chu_the"},{"note":"Đúng. Khi Nhật hàng Đồng minh, nhân dân cả nước nổi dậy giành chính quyền từ tay Nhật và tay sai.","section_id":"muc-1"},{"note":"Quân Trung Hoa Dân quốc vào miền Bắc sau khi ta đã giành chính quyền, với danh nghĩa giải giáp quân Nhật.","lesson_slug":"7-khang-chien-chong-phap","section_id":"muc-1","trap":"chu_the"},{"note":"Quân Anh vào miền Nam (9-1945) để giải giáp quân Nhật, sau khi Sài Gòn đã giành chính quyền (25-8).","lesson_slug":"7-khang-chien-chong-phap","section_id":"muc-1","trap":"chu_the"}]'::jsonb, 'Câu đọc hiểu: Tuyên ngôn nhấn mạnh nhân dân giành chính quyền từ tay Nhật để bác bỏ việc Pháp đòi quay lại.', '“Dân ta đã lấy lại nước Việt Nam từ tay Nhật, chứ không phải từ tay Pháp.”', 12, '6-cach-mang-thang-tam-nam-1945', 'muc-1', null, 'nhan_biet', 'tim_hieu_lich_su', null, 'SGK Lịch sử 12 (KNTT), Bài 6, mục 1')
