 where content_key is null and fingerprint = public.exam_item_fingerprint('mcq', 'Câu “Pháp chạy, Nhật hàng, vua Bảo Đại thoái vị” trong đoạn tư liệu nhằm khẳng định điều gì?', array['Việt Nam được thực dân Pháp trao trả độc lập', 'Quân Đồng minh đã giải phóng Việt Nam khỏi phát xít Nhật', 'Chế độ quân chủ được duy trì dưới một hình thức mới', 'Chính quyền cũ đã sụp đổ, chính quyền mới của nhân dân là hợp pháp'], null)
