values ('b6-m1-tn-15', 'mcq', 'Câu “Pháp chạy, Nhật hàng, vua Bảo Đại thoái vị” trong đoạn tư liệu nhằm khẳng định điều gì?', (select id from public.exam_passages where title = 'Tuyên ngôn độc lập (2-9-1945) — đoạn về “sự thật”' and body = '“Sự thật là từ mùa thu năm 1940, nước ta đã thành thuộc địa của Nhật, chứ không phải thuộc địa của Pháp nữa. Khi Nhật hàng Đồng minh thì nhân dân cả nước ta đã nổi dậy giành chính quyền, lập nên nước Việt Nam Dân chủ Cộng hòa.
