insert into public.exam_items (content_key, kind, stem, passage_id, choices, correct_index, statements, choice_notes, explanation, remember, grade, lesson_slug, section_id, topic_tag, level, competency, event_id, source_note)
values ('b6-m1-tn-16', 'mcq', 'Đoạn tư liệu cho thấy Cách mạng tháng Tám năm 1945 đã cùng lúc giải quyết những nhiệm vụ nào?', (select id from public.exam_passages where title = 'Tuyên ngôn độc lập (2-9-1945) — đoạn về “sự thật”' and body = '“Sự thật là từ mùa thu năm 1940, nước ta đã thành thuộc địa của Nhật, chứ không phải thuộc địa của Pháp nữa. Khi Nhật hàng Đồng minh thì nhân dân cả nước ta đã nổi dậy giành chính quyền, lập nên nước Việt Nam Dân chủ Cộng hòa.
Sự thật là dân ta đã lấy lại nước Việt Nam từ tay Nhật, chứ không phải từ tay Pháp.
Pháp chạy, Nhật hàng, vua Bảo Đại thoái vị. Dân ta đã đánh đổ các xiềng xích thực dân gần 100 năm nay để gây dựng nên nước Việt Nam độc lập. Dân ta lại đánh đổ chế độ quân chủ mấy mươi thế kỷ mà lập nên chế độ Dân chủ Cộng hòa.”' order by created_at limit 1), array['Đánh đuổi quân Đồng minh và giải giáp quân Nhật', 'Đánh đổ ách thực dân – phát xít và lật đổ chế độ quân chủ', 'Cải cách ruộng đất và xây dựng chủ nghĩa xã hội', 'Đánh bại thực dân Pháp và quân Trung Hoa Dân quốc'], 1, null, '[{"note":"Sai bản chất nhiệm vụ: cách mạng không nhằm đánh Đồng minh; việc giải giáp quân Nhật do quân Đồng minh đảm nhiệm.","section_id":"muc-1","trap":"ban_chat"},{"note":"Đúng. “Đánh đổ các xiềng xích thực dân gần 100 năm nay” (nhiệm vụ dân tộc) và “đánh đổ chế độ quân chủ mấy mươi thế kỷ” (nhiệm vụ dân chủ).","section_id":"muc-1"},{"note":"Cải cách ruộng đất (phát động năm 1953, trong kháng chiến chống Pháp) và xây dựng chủ nghĩa xã hội (ở miền Bắc sau năm 1954) là nhiệm vụ của những giai đoạn sau.","lesson_slug":"7-khang-chien-chong-phap","section_id":"muc-3","trap":"thoi_gian"},{"note":"Kháng chiến chống Pháp bắt đầu sau Cách mạng tháng Tám; với quân Trung Hoa Dân quốc, ta chủ trương hòa hoãn (1945 – 1946).","lesson_slug":"7-khang-chien-chong-phap","section_id":"muc-1","trap":"thoi_gian"}]'::jsonb, 'Cách mạng tháng Tám là cuộc cách mạng giải phóng dân tộc mang tính dân chủ.', 'Cách mạng tháng Tám: vừa giải phóng dân tộc (đánh đổ thực dân – phát xít), vừa dân chủ (lật đổ chế độ quân chủ).', 12, '6-cach-mang-thang-tam-nam-1945', 'muc-1', null, 'van_dung', 'nhan_thuc_tu_duy', null, 'SGK Lịch sử 12 (KNTT), Bài 6, mục 1')
