update public.exam_items set content_key = 'b6-m1-tn-17'
 where content_key is null and fingerprint = public.exam_item_fingerprint('mcq', 'Dựa vào đoạn tư liệu, nếu Tổng khởi nghĩa nổ ra muộn, khi quân Trung Hoa Dân quốc và quân Anh đã vào Đông Dương, thì điều gì có thể xảy ra?', array['Nhân dân sẽ được quân Đồng minh trao lại chính quyền', 'Quân Nhật sẽ tự rút về nước, nhường chính quyền cho Việt Minh', 'Việc giành chính quyền khó khăn hơn vì có thêm lực lượng can thiệp', 'Tổng khởi nghĩa thuận lợi hơn vì quân Nhật đã bị giải giáp'], null)
   and not exists (select 1 from public.exam_items where content_key = 'b6-m1-tn-17');
insert into public.exam_items (content_key, kind, stem, passage_id, choices, correct_index, statements, choice_notes, explanation, remember, grade, lesson_slug, section_id, topic_tag, level, competency, event_id, source_note)
values ('b6-m1-tn-17', 'mcq', 'Dựa vào đoạn tư liệu, nếu Tổng khởi nghĩa nổ ra muộn, khi quân Trung Hoa Dân quốc và quân Anh đã vào Đông Dương, thì điều gì có thể xảy ra?', (select id from public.exam_passages where title = 'Thời cơ của Tổng khởi nghĩa tháng Tám năm 1945' and body = 'Ngày 15-8-1945, Nhật Bản tuyên bố đầu hàng Đồng minh không điều kiện. Quân Nhật ở Đông Dương rệu rã, mất tinh thần; chính phủ thân Nhật Trần Trọng Kim hoang mang, lo sợ. Theo thỏa thuận của các nước Đồng minh, quân Trung Hoa Dân quốc sẽ vào miền Bắc, quân Anh vào miền Nam (lấy vĩ tuyến 16 làm ranh giới) để giải giáp quân Nhật.
Ngay khi biết tin Nhật sắp đầu hàng, Ủy ban Khởi nghĩa toàn quốc được thành lập và đêm 13-8-1945 ban bố Quân lệnh số 1. Hội nghị toàn quốc của Đảng (14 – 15-8) và Quốc dân Đại hội ở Tân Trào (16-8) quyết định phát động Tổng khởi nghĩa, giành chính quyền từ tay Nhật và tay sai trước khi quân Đồng minh vào Đông Dương. Chủ tịch Hồ Chí Minh gửi thư kêu gọi: “Giờ quyết định cho vận mệnh dân tộc ta đã đến. Toàn quốc đồng bào hãy đứng dậy đem sức ta mà tự giải phóng cho ta.”' order by created_at limit 1), array['Nhân dân sẽ được quân Đồng minh trao lại chính quyền', 'Quân Nhật sẽ tự rút về nước, nhường chính quyền cho Việt Minh', 'Việc giành chính quyền khó khăn hơn vì có thêm lực lượng can thiệp', 'Tổng khởi nghĩa thuận lợi hơn vì quân Nhật đã bị giải giáp'], 2, null, '[{"note":"Hiểu sai: quân Đồng minh vào để giải giáp quân Nhật, không có nhiệm vụ trao chính quyền cho nhân dân Việt Nam.","section_id":"muc-1","trap":"ban_chat"},{"note":"Hiểu sai: theo thỏa thuận của Đồng minh, quân Nhật phải bị giải giáp, không phải tự rút và trao chính quyền cho Việt Minh.","section_id":"muc-1","trap":"ban_chat"},{"note":"Đúng. Khi quân Đồng minh đã vào, các thế lực thù địch có chỗ dựa để chống phá; thời cơ “kẻ thù cũ đã gục ngã, kẻ thù mới chưa vào” sẽ qua đi.","section_id":"muc-1"},{"note":"Đảo ngược nhân quả: lúc ấy chính quyền sẽ phải giành từ một đối thủ khác, có quân Đồng minh đứng sau — không thuận lợi hơn.","section_id":"muc-1","trap":"nhan_qua"}]'::jsonb, 'Câu đánh giá ý nghĩa của việc chớp thời cơ, dựa trên thông tin về thỏa thuận của Đồng minh.', 'Phải giành chính quyền trước khi quân Đồng minh vào để làm chủ đất nước.', 12, '6-cach-mang-thang-tam-nam-1945', 'muc-1', null, 'van_dung', 'van_dung_kien_thuc', null, 'SGK Lịch sử 12 (KNTT), Bài 6, mục 1')
