update public.exam_items set content_key = 'b6-m1-tn-18'
 where content_key is null and fingerprint = public.exam_item_fingerprint('mcq', 'Lời kêu gọi “đem sức ta mà tự giải phóng cho ta” trong đoạn tư liệu có giá trị như thế nào đối với Việt Nam hiện nay?', array['Phát huy nội lực, tinh thần tự lực tự cường trong xây dựng đất nước', 'Chỉ phát triển kinh tế bằng vốn trong nước, không hợp tác quốc tế', 'Dựa hoàn toàn vào viện trợ và đầu tư của nước ngoài', 'Chờ hoàn cảnh quốc tế thuận lợi rồi mới hành động'], null)
   and not exists (select 1 from public.exam_items where content_key = 'b6-m1-tn-18');
insert into public.exam_items (content_key, kind, stem, passage_id, choices, correct_index, statements, choice_notes, explanation, remember, grade, lesson_slug, section_id, topic_tag, level, competency, event_id, source_note)
values ('b6-m1-tn-18', 'mcq', 'Lời kêu gọi “đem sức ta mà tự giải phóng cho ta” trong đoạn tư liệu có giá trị như thế nào đối với Việt Nam hiện nay?', (select id from public.exam_passages where title = 'Thời cơ của Tổng khởi nghĩa tháng Tám năm 1945' and body = 'Ngày 15-8-1945, Nhật Bản tuyên bố đầu hàng Đồng minh không điều kiện. Quân Nhật ở Đông Dương rệu rã, mất tinh thần; chính phủ thân Nhật Trần Trọng Kim hoang mang, lo sợ. Theo thỏa thuận của các nước Đồng minh, quân Trung Hoa Dân quốc sẽ vào miền Bắc, quân Anh vào miền Nam (lấy vĩ tuyến 16 làm ranh giới) để giải giáp quân Nhật.
Ngay khi biết tin Nhật sắp đầu hàng, Ủy ban Khởi nghĩa toàn quốc được thành lập và đêm 13-8-1945 ban bố Quân lệnh số 1. Hội nghị toàn quốc của Đảng (14 – 15-8) và Quốc dân Đại hội ở Tân Trào (16-8) quyết định phát động Tổng khởi nghĩa, giành chính quyền từ tay Nhật và tay sai trước khi quân Đồng minh vào Đông Dương. Chủ tịch Hồ Chí Minh gửi thư kêu gọi: “Giờ quyết định cho vận mệnh dân tộc ta đã đến. Toàn quốc đồng bào hãy đứng dậy đem sức ta mà tự giải phóng cho ta.”' order by created_at limit 1), array['Phát huy nội lực, tinh thần tự lực tự cường trong xây dựng đất nước', 'Chỉ phát triển kinh tế bằng vốn trong nước, không hợp tác quốc tế', 'Dựa hoàn toàn vào viện trợ và đầu tư của nước ngoài', 'Chờ hoàn cảnh quốc tế thuận lợi rồi mới hành động'], 0, null, '[{"note":"Đúng. Tư tưởng dựa vào sức mình là chính vẫn có giá trị: phát huy nội lực, đồng thời tranh thủ thời cơ, nguồn lực từ hội nhập quốc tế.","section_id":"muc-1"},{"note":"Tuyệt đối hóa: tự lực không có nghĩa là đóng cửa; Việt Nam hiện nay vừa phát huy nội lực vừa chủ động hội nhập quốc tế.","lesson_slug":"11-thanh-tuu-va-bai-hoc-cua-cong-cuoc-doi-moi","section_id":"muc-2","trap":"tuyet_doi"},{"note":"Trái với tinh thần “tự giải phóng cho ta”: dựa hoàn toàn vào bên ngoài là mất tính tự chủ.","section_id":"muc-1","trap":"ban_chat"},{"note":"Hiểu sai bài học: năm 1945, Đảng chủ động chuẩn bị lực lượng và chớp thời cơ, không thụ động chờ đợi.","section_id":"muc-2","trap":"ban_chat"}]'::jsonb, 'Câu liên hệ: từ tư tưởng tự lực năm 1945 tới yêu cầu phát huy nội lực hiện nay.', '“Đem sức ta mà tự giải phóng cho ta” — tinh thần độc lập, tự chủ, tự lực, tự cường.', 12, '6-cach-mang-thang-tam-nam-1945', 'muc-1', null, 'van_dung', 'van_dung_kien_thuc', null, 'SGK Lịch sử 12 (KNTT), Bài 6, mục 1')
