update public.exam_items set content_key = 'b6-m2-ds-01'
 where content_key is null and fingerprint = public.exam_item_fingerprint('true_false', 'Cho thông tin: “Cách mạng tháng Tám năm 1945 thành công là kết quả của nhiều nguyên nhân, cả chủ quan lẫn khách quan.” Mỗi ý sau đây đúng hay sai?', null, '[{"text":"Truyền thống yêu nước của dân tộc là một nguyên nhân chủ quan.","is_true":true,"explanation":"Truyền thống yêu nước, đấu tranh chống ngoại xâm là sức mạnh bên trong của dân tộc.","section_id":"muc-2"},{"text":"Mặt trận Việt Minh được thành lập sau Cách mạng tháng Tám năm 1945.","is_true":false,"explanation":"Sai thời gian: Mặt trận Việt Minh thành lập ngày 19-5-1941, tập hợp lực lượng cho Tổng khởi nghĩa.","lesson_slug":"16-ho-chi-minh-anh-hung-giai-phong-dan-toc","section_id":"muc-2","trap":"thoi_gian"},{"text":"Chiến thắng của Liên Xô và quân Đồng minh trước phát xít là một nguyên nhân khách quan.","is_true":true,"explanation":"Đây là điều kiện bên ngoài, tạo thời cơ cho Tổng khởi nghĩa.","section_id":"muc-2"},{"text":"Đảng Cộng sản Việt Nam ra đời năm 1941, cùng lúc với Mặt trận Việt Minh.","is_true":false,"explanation":"Sai thời gian: Đảng ra đời đầu năm 1930; năm 1941 là năm thành lập Mặt trận Việt Minh.","lesson_slug":"16-ho-chi-minh-anh-hung-giai-phong-dan-toc","section_id":"muc-1","trap":"thoi_gian"}]'::jsonb)
   and not exists (select 1 from public.exam_items where content_key = 'b6-m2-ds-01');
