values ('b6-m2-ds-01', 'true_false', 'Cho thông tin: “Cách mạng tháng Tám năm 1945 thành công là kết quả của nhiều nguyên nhân, cả chủ quan lẫn khách quan.” Mỗi ý sau đây đúng hay sai?', null, null, null, '[{"text":"Truyền thống yêu nước của dân tộc là một nguyên nhân chủ quan.","is_true":true,"explanation":"Truyền thống yêu nước, đấu tranh chống ngoại xâm là sức mạnh bên trong của dân tộc.","section_id":"muc-2"},{"text":"Mặt trận Việt Minh được thành lập sau Cách mạng tháng Tám năm 1945.","is_true":false,"explanation":"Sai thời gian: Mặt trận Việt Minh thành lập ngày 19-5-1941, tập hợp lực lượng cho Tổng khởi nghĩa.","lesson_slug":"16-ho-chi-minh-anh-hung-giai-phong-dan-toc","section_id":"muc-2","trap":"thoi_gian"},{"text":"Chiến thắng của Liên Xô và quân Đồng minh trước phát xít là một nguyên nhân khách quan.","is_true":true,"explanation":"Đây là điều kiện bên ngoài, tạo thời cơ cho Tổng khởi nghĩa.","section_id":"muc-2"},{"text":"Đảng Cộng sản Việt Nam ra đời năm 1941, cùng lúc với Mặt trận Việt Minh.","is_true":false,"explanation":"Sai thời gian: Đảng ra đời đầu năm 1930; năm 1941 là năm thành lập Mặt trận Việt Minh.","lesson_slug":"16-ho-chi-minh-anh-hung-giai-phong-dan-toc","section_id":"muc-1","trap":"thoi_gian"}]'::jsonb, null, 'Câu kiểm tra nhận biết các nguyên nhân thắng lợi và mốc thời gian liên quan.', 'Đảng ra đời 1930 · Mặt trận Việt Minh 1941 · Cách mạng tháng Tám 1945.', 12, '6-cach-mang-thang-tam-nam-1945', 'muc-2', null, 'nhan_biet', 'tim_hieu_lich_su', null, 'SGK Lịch sử 12 (KNTT), Bài 6, mục 2')
