update public.exam_items set content_key = 'b6-m2-ds-02'
 where content_key is null and fingerprint = public.exam_item_fingerprint('true_false', 'Đọc đoạn tư liệu về nguyên nhân thắng lợi của Cách mạng tháng Tám năm 1945 và cho biết mỗi ý sau đúng hay sai.', null, '[{"text":"Tư liệu nêu ba cao trào cách mạng 1930 – 1931, 1936 – 1939 và 1939 – 1945.","is_true":true,"explanation":"Đây là quá trình chuẩn bị 15 năm được tư liệu nêu rõ.","section_id":"muc-2"},{"text":"Theo tư liệu, thắng lợi của quân Đồng minh là nguyên nhân quyết định nhất.","is_true":false,"explanation":"Trái tư liệu: cách mạng thành công “trước hết” do truyền thống dân tộc, sự lãnh đạo của Đảng…; “bên cạnh đó”, thắng lợi của Đồng minh chỉ “tạo thời cơ khách quan thuận lợi”.","section_id":"muc-2","trap":"ban_chat"},{"text":"Khối đoàn kết toàn dân trong Mặt trận Việt Minh là một nguyên nhân thắng lợi.","is_true":true,"explanation":"Tư liệu nêu Đảng “xây dựng khối đoàn kết toàn dân trong Mặt trận Việt Minh”.","section_id":"muc-2"},{"text":"Tư liệu cho thấy Đảng đặt nhiệm vụ chia ruộng đất cho nông dân lên hàng đầu.","is_true":false,"explanation":"Trái tư liệu: Đảng “đặt nhiệm vụ giải phóng dân tộc lên hàng đầu”.","section_id":"muc-2","trap":"ban_chat"}]'::jsonb)
   and not exists (select 1 from public.exam_items where content_key = 'b6-m2-ds-02');
insert into public.exam_items (content_key, kind, stem, passage_id, choices, correct_index, statements, choice_notes, explanation, remember, grade, lesson_slug, section_id, topic_tag, level, competency, event_id, source_note)
values ('b6-m2-ds-02', 'true_false', 'Đọc đoạn tư liệu về nguyên nhân thắng lợi của Cách mạng tháng Tám năm 1945 và cho biết mỗi ý sau đúng hay sai.', (select id from public.exam_passages where title = 'Nguyên nhân thắng lợi của Cách mạng tháng Tám năm 1945' and body = 'Cách mạng tháng Tám năm 1945 thành công trước hết bắt nguồn từ truyền thống yêu nước, đấu tranh kiên cường chống ngoại xâm của dân tộc Việt Nam. Đảng Cộng sản Đông Dương, đứng đầu là Hồ Chí Minh, đã đề ra đường lối cách mạng đúng đắn, đặt nhiệm vụ giải phóng dân tộc lên hàng đầu, xây dựng khối đoàn kết toàn dân trong Mặt trận Việt Minh. Cuộc cách mạng là kết quả của quá trình chuẩn bị suốt 15 năm, qua ba cao trào cách mạng 1930 – 1931, 1936 – 1939 và 1939 – 1945. Khi thời cơ đến, Đảng kịp thời phát động Tổng khởi nghĩa.
Bên cạnh đó, thắng lợi của Liên Xô và quân Đồng minh trong cuộc chiến tranh chống chủ nghĩa phát xít đã cổ vũ tinh thần và tạo thời cơ khách quan thuận lợi để nhân dân Việt Nam đứng lên giành chính quyền.' order by created_at limit 1), null, null, '[{"text":"Tư liệu nêu ba cao trào cách mạng 1930 – 1931, 1936 – 1939 và 1939 – 1945.","is_true":true,"explanation":"Đây là quá trình chuẩn bị 15 năm được tư liệu nêu rõ.","section_id":"muc-2"},{"text":"Theo tư liệu, thắng lợi của quân Đồng minh là nguyên nhân quyết định nhất.","is_true":false,"explanation":"Trái tư liệu: cách mạng thành công “trước hết” do truyền thống dân tộc, sự lãnh đạo của Đảng…; “bên cạnh đó”, thắng lợi của Đồng minh chỉ “tạo thời cơ khách quan thuận lợi”.","section_id":"muc-2","trap":"ban_chat"},{"text":"Khối đoàn kết toàn dân trong Mặt trận Việt Minh là một nguyên nhân thắng lợi.","is_true":true,"explanation":"Tư liệu nêu Đảng “xây dựng khối đoàn kết toàn dân trong Mặt trận Việt Minh”.","section_id":"muc-2"},{"text":"Tư liệu cho thấy Đảng đặt nhiệm vụ chia ruộng đất cho nông dân lên hàng đầu.","is_true":false,"explanation":"Trái tư liệu: Đảng “đặt nhiệm vụ giải phóng dân tộc lên hàng đầu”.","section_id":"muc-2","trap":"ban_chat"}]'::jsonb, null, 'Câu đọc hiểu: phân biệt vai trò của từng nguyên nhân.', 'Đường lối năm 1945: đặt giải phóng dân tộc lên hàng đầu, đoàn kết toàn dân trong Mặt trận Việt Minh.', 12, '6-cach-mang-thang-tam-nam-1945', 'muc-2', null, 'thong_hieu', 'nhan_thuc_tu_duy', null, 'SGK Lịch sử 12 (KNTT), Bài 6, mục 2')
