 where content_key is null and fingerprint = public.exam_item_fingerprint('true_false', 'Cho thông tin: “Cách mạng tháng Tám năm 1945 để lại nhiều bài học kinh nghiệm quý báu cho sự nghiệp xây dựng và bảo vệ Tổ quốc.” Mỗi ý sau đây đúng hay sai?', null, '[{"text":"Một bài học là kết hợp nhiệm vụ dân tộc với nhiệm vụ dân chủ, đặt giải phóng dân tộc lên hàng đầu.","is_true":true,"explanation":"Đây là bài học về đường lối của Cách mạng tháng Tám.","section_id":"muc-2"},{"text":"Bài học nắm bắt thời cơ vẫn có giá trị khi Việt Nam hội nhập quốc tế hiện nay.","is_true":true,"explanation":"Chủ động chuẩn bị, nắm bắt thời cơ — bài học vẫn được vận dụng trong phát triển đất nước.","section_id":"muc-2"},{"text":"Cách mạng tháng Tám cho thấy chỉ cần đấu tranh vũ trang là đủ để giành thắng lợi.","is_true":false,"explanation":"Tuyệt đối hóa: Tổng khởi nghĩa kết hợp đấu tranh chính trị của quần chúng với đấu tranh vũ trang.","section_id":"muc-2","trap":"tuyet_doi"},{"text":"Bài học đoàn kết toàn dân không còn phù hợp khi đất nước đã hòa bình.","is_true":false,"explanation":"Hiểu sai: đại đoàn kết toàn dân tộc vẫn là nguồn sức mạnh trong xây dựng và bảo vệ Tổ quốc.","section_id":"muc-2","trap":"ban_chat"}]'::jsonb)
   and not exists (select 1 from public.exam_items where content_key = 'b6-m2-ds-03');
