values ('b6-m2-tn-01', 'mcq', 'Nhân tố giữ vai trò quyết định hàng đầu đối với thắng lợi của Cách mạng tháng Tám năm 1945 là', null, array['chiến thắng của Liên Xô và quân Đồng minh trước phát xít', 'sự lãnh đạo của Đảng Cộng sản Đông Dương, đứng đầu là Hồ Chí Minh', 'truyền thống yêu nước, đấu tranh chống ngoại xâm của dân tộc', 'khối đoàn kết toàn dân trong Mặt trận Việt Minh'], 1, null, '[{"note":"Nhầm nguyên nhân khách quan với chủ quan: thắng lợi của Đồng minh chỉ tạo thời cơ thuận lợi.","section_id":"muc-2","trap":"nhan_qua"},{"note":"Đúng. Đảng do Hồ Chí Minh đứng đầu đề ra đường lối đúng, chuẩn bị lực lượng suốt 15 năm và chớp đúng thời cơ — nhân tố chủ quan quyết định.","section_id":"muc-2"},{"note":"Truyền thống yêu nước là nguyên nhân chủ quan, là nền tảng — nhưng phải có Đảng lãnh đạo mới tập hợp, phát huy thành sức mạnh giành chính quyền.","section_id":"muc-2","trap":"ban_chat"},{"note":"Mặt trận Việt Minh là nguyên nhân quan trọng, nhưng chính Đảng là lực lượng thành lập và lãnh đạo Mặt trận.","section_id":"muc-2","trap":"ban_chat"}]'::jsonb, 'Phân biệt nguyên nhân chủ quan (quyết định) và khách quan (tạo thời cơ).', 'Nhân tố quyết định: sự lãnh đạo của Đảng, đứng đầu là Hồ Chí Minh.', 12, '6-cach-mang-thang-tam-nam-1945', 'muc-2', null, 'nhan_biet', 'tim_hieu_lich_su', null, 'SGK Lịch sử 12 (KNTT), Bài 6, mục 2')
