values ('b6-m2-tn-03', 'mcq', 'Nước Việt Nam Dân chủ Cộng hòa ra đời năm 1945 là', null, array['nhà nước xã hội chủ nghĩa đầu tiên ở châu Á', 'nhà nước quân chủ lập hiến đầu tiên ở Đông Nam Á', 'nhà nước liên bang đầu tiên ở bán đảo Đông Dương', 'nhà nước dân chủ nhân dân đầu tiên ở Đông Nam Á'], 3, null, '[{"note":"Nhầm khái niệm: năm 1945 Việt Nam lập chế độ dân chủ cộng hòa (dân chủ nhân dân), chưa phải nhà nước xã hội chủ nghĩa.","section_id":"muc-2","trap":"khai_niem"},{"note":"Ngược với bản chất: Cách mạng tháng Tám lật đổ chế độ quân chủ, lập chế độ dân chủ cộng hòa.","section_id":"muc-2","trap":"ban_chat"},{"note":"Nhầm khái niệm: “Liên bang Đông Dương” là tổ chức do Pháp đặt ra (được nhắc tới trong Hiệp định Sơ bộ 1946), không phải nhà nước do Cách mạng tháng Tám lập nên.","lesson_slug":"7-khang-chien-chong-phap","section_id":"muc-1","trap":"khai_niem"},{"note":"Đúng. Nước Việt Nam Dân chủ Cộng hòa là nhà nước dân chủ nhân dân đầu tiên ở Đông Nam Á.","section_id":"muc-2"}]'::jsonb, 'Ý nghĩa trong nước của Cách mạng tháng Tám: lập nên nhà nước dân chủ nhân dân.', 'Nước Việt Nam Dân chủ Cộng hòa (2-9-1945) — nhà nước dân chủ nhân dân đầu tiên ở Đông Nam Á.', 12, '6-cach-mang-thang-tam-nam-1945', 'muc-2', null, 'nhan_biet', 'tim_hieu_lich_su', null, 'SGK Lịch sử 12 (KNTT), Bài 6, mục 2')
