values ('b6-m2-tn-04', 'mcq', 'Ý nghĩa quốc tế của Cách mạng tháng Tám năm 1945 là', null, array['góp phần vào chiến thắng chống phát xít, cổ vũ phong trào giải phóng dân tộc', 'làm sụp đổ hoàn toàn hệ thống thuộc địa của chủ nghĩa đế quốc', 'chấm dứt cuộc Chiến tranh lạnh giữa hai phe', 'giúp Việt Nam trở thành thành viên Liên hợp quốc'], 0, null, '[{"note":"Đúng. Cách mạng tháng Tám góp phần vào thắng lợi chung của cuộc chiến tranh chống phát xít, cổ vũ phong trào giải phóng dân tộc ở châu Á, châu Phi, Mỹ Latinh.","section_id":"muc-2"},{"note":"Tuyệt đối hóa: Cách mạng tháng Tám góp phần làm suy yếu chủ nghĩa thực dân, chứ không làm hệ thống thuộc địa “sụp đổ hoàn toàn”.","section_id":"muc-2","trap":"tuyet_doi"},{"note":"Chiến tranh lạnh diễn ra sau năm 1945 và chấm dứt năm 1989; Cách mạng tháng Tám không liên quan tới việc kết thúc Chiến tranh lạnh.","lesson_slug":"2-trat-tu-the-gioi-trong-chien-tranh-lanh","section_id":"muc-2","trap":"thoi_gian"},{"note":"Việt Nam trở thành thành viên Liên hợp quốc năm 1977.","lesson_slug":"14-doi-ngoai-tu-nam-1975-den-nay","section_id":"muc-1","trap":"thoi_gian"}]'::jsonb, 'Phân biệt ý nghĩa trong nước và ý nghĩa quốc tế; cẩn thận các phương án phóng đại.', 'Quốc tế: góp phần thắng phát xít, cổ vũ phong trào giải phóng dân tộc.', 12, '6-cach-mang-thang-tam-nam-1945', 'muc-2', null, 'thong_hieu', 'nhan_thuc_tu_duy', null, 'SGK Lịch sử 12 (KNTT), Bài 6, mục 2')
