values ('b6-m2-tn-05', 'mcq', 'Thắng lợi của Cách mạng tháng Tám năm 1945 là kết quả của quá trình chuẩn bị suốt 15 năm, tính từ khi', null, array['Nguyễn Tất Thành ra đi tìm đường cứu nước (1911)', 'Mặt trận Việt Minh được thành lập (1941)', 'Hội nghị Trung ương 6 của Đảng (1939)', 'Đảng Cộng sản Việt Nam ra đời (1930)'], 3, null, '[{"note":"Năm 1911 Nguyễn Tất Thành ra đi tìm đường cứu nước — cách năm 1945 tới 34 năm.","lesson_slug":"16-ho-chi-minh-anh-hung-giai-phong-dan-toc","section_id":"muc-1","trap":"thoi_gian"},{"note":"Mặt trận Việt Minh thành lập năm 1941, chỉ 4 năm trước Cách mạng tháng Tám.","lesson_slug":"16-ho-chi-minh-anh-hung-giai-phong-dan-toc","section_id":"muc-2","trap":"thoi_gian"},{"note":"Hội nghị Trung ương 6 (11-1939) chuyển hướng chỉ đạo chiến lược, mở đầu cao trào 1939 – 1945 — chỉ 6 năm trước Cách mạng tháng Tám.","section_id":"muc-2","trap":"thoi_gian"},{"note":"Đúng. Từ khi Đảng ra đời (đầu năm 1930), cách mạng trải qua ba cao trào 1930 – 1931, 1936 – 1939, 1939 – 1945 — 15 năm chuẩn bị.","section_id":"muc-2"}]'::jsonb, 'Cách mạng tháng Tám không phải ăn may: đó là kết quả chuẩn bị lâu dài từ năm 1930.', '15 năm chuẩn bị (1930 – 1945) qua ba cao trào: 1930 – 1931, 1936 – 1939, 1939 – 1945.', 12, '6-cach-mang-thang-tam-nam-1945', 'muc-2', null, 'nhan_biet', 'tim_hieu_lich_su', null, 'SGK Lịch sử 12 (KNTT), Bài 6, mục 2')
