values ('b6-m2-tn-06', 'mcq', 'Việc Đảng phát động Tổng khởi nghĩa ngay khi Nhật đầu hàng Đồng minh, trước khi quân Đồng minh vào Đông Dương, thể hiện bài học kinh nghiệm nào?', null, array['Đặt nhiệm vụ cải cách ruộng đất lên hàng đầu', 'Lấy đấu tranh ngoại giao làm hình thức chủ yếu', 'Nắm vững thời cơ, chọn đúng thời điểm phát động khởi nghĩa', 'Chỉ sử dụng lực lượng vũ trang để giành chính quyền'], 2, null, '[{"note":"Năm 1945, Đảng đặt nhiệm vụ giải phóng dân tộc lên hàng đầu, tạm gác khẩu hiệu cách mạng ruộng đất.","section_id":"muc-2","trap":"ban_chat"},{"note":"Hình thức chủ yếu năm 1945 là khởi nghĩa của quần chúng, không phải đấu tranh ngoại giao.","section_id":"muc-1","trap":"ban_chat"},{"note":"Đúng. Chuẩn bị chu đáo và chớp đúng thời cơ “ngàn năm có một” là bài học lớn của Cách mạng tháng Tám.","section_id":"muc-2"},{"note":"Tuyệt đối hóa: Tổng khởi nghĩa kết hợp lực lượng chính trị của quần chúng (là chủ yếu) với lực lượng vũ trang.","section_id":"muc-2","trap":"tuyet_doi"}]'::jsonb, 'Gắn sự kiện cụ thể (thời điểm phát động) với bài học kinh nghiệm tương ứng.', 'Bài học thời cơ: chuẩn bị chu đáo, chớp đúng thời điểm.', 12, '6-cach-mang-thang-tam-nam-1945', 'muc-2', null, 'thong_hieu', 'nhan_thuc_tu_duy', null, 'SGK Lịch sử 12 (KNTT), Bài 6, mục 2')
