values ('b6-m2-tn-07', 'mcq', 'Cách mạng tháng Tám năm 1945 mang tính chất dân chủ vì cuộc cách mạng đã', null, array['chia ruộng đất cho nông dân trên cả nước', 'lật đổ chế độ quân chủ, đem lại quyền làm chủ cho nhân dân', 'đưa giai cấp tư sản dân tộc lên nắm chính quyền', 'có sự tham gia trực tiếp của quân Đồng minh'], 1, null, '[{"note":"Năm 1945 chưa chia ruộng đất trên cả nước; cải cách ruộng đất tiến hành ở miền Bắc trong những năm 1953 – 1956.","lesson_slug":"7-khang-chien-chong-phap","section_id":"muc-3","trap":"thoi_gian"},{"note":"Đúng. Cách mạng lật đổ chế độ quân chủ hàng nghìn năm, lập chế độ dân chủ cộng hòa — nhân dân từ thân phận nô lệ trở thành người làm chủ.","section_id":"muc-2"},{"note":"Chính quyền mới là chính quyền của nhân dân, không phải chính quyền riêng của giai cấp tư sản.","section_id":"muc-2","trap":"ban_chat"},{"note":"Đánh tráo chủ thể: tính dân chủ thể hiện ở việc lật đổ chế độ phong kiến, không liên quan tới quân Đồng minh.","section_id":"muc-2","trap":"chu_the"}]'::jsonb, 'Tính dân tộc: giành độc lập; tính dân chủ: xóa bỏ chế độ quân chủ, đem lại quyền làm chủ cho nhân dân.', 'Tính dân chủ của Cách mạng tháng Tám: lật đổ chế độ quân chủ, nhân dân trở thành người làm chủ.', 12, '6-cach-mang-thang-tam-nam-1945', 'muc-2', null, 'thong_hieu', 'nhan_thuc_tu_duy', null, 'SGK Lịch sử 12 (KNTT), Bài 6, mục 2')
