values ('b6-m2-tn-10', 'mcq', 'Đoạn tư liệu cho thấy mối quan hệ giữa nguyên nhân chủ quan và nguyên nhân khách quan trong thắng lợi của Cách mạng tháng Tám như thế nào?', (select id from public.exam_passages where title = 'Nguyên nhân thắng lợi của Cách mạng tháng Tám năm 1945' and body = 'Cách mạng tháng Tám năm 1945 thành công trước hết bắt nguồn từ truyền thống yêu nước, đấu tranh kiên cường chống ngoại xâm của dân tộc Việt Nam. Đảng Cộng sản Đông Dương, đứng đầu là Hồ Chí Minh, đã đề ra đường lối cách mạng đúng đắn, đặt nhiệm vụ giải phóng dân tộc lên hàng đầu, xây dựng khối đoàn kết toàn dân trong Mặt trận Việt Minh. Cuộc cách mạng là kết quả của quá trình chuẩn bị suốt 15 năm, qua ba cao trào cách mạng 1930 – 1931, 1936 – 1939 và 1939 – 1945. Khi thời cơ đến, Đảng kịp thời phát động Tổng khởi nghĩa.
Bên cạnh đó, thắng lợi của Liên Xô và quân Đồng minh trong cuộc chiến tranh chống chủ nghĩa phát xít đã cổ vũ tinh thần và tạo thời cơ khách quan thuận lợi để nhân dân Việt Nam đứng lên giành chính quyền.' order by created_at limit 1), array['Khách quan tạo thời cơ, chủ quan giữ vai trò quyết định', 'Khách quan giữ vai trò quyết định, chủ quan chỉ hỗ trợ', 'Hai nguyên nhân hoàn toàn tách rời, không liên quan nhau', 'Chỉ cần nguyên nhân chủ quan, thời cơ không quan trọng'], 0, null, '[{"note":"Đúng. Thắng lợi của Đồng minh “tạo thời cơ khách quan thuận lợi”; còn truyền thống dân tộc, sự lãnh đạo của Đảng, khối đoàn kết toàn dân và 15 năm chuẩn bị là nhân tố quyết định.","section_id":"muc-2"},{"note":"Đảo ngược quan hệ: tư liệu viết cách mạng thành công “trước hết” do các yếu tố bên trong; “bên cạnh đó”, thắng lợi của Đồng minh “tạo thời cơ khách quan”.","section_id":"muc-2","trap":"nhan_qua"},{"note":"Tư liệu cho thấy hai nguyên nhân gắn bó: có thời cơ khách quan, Đảng mới “kịp thời phát động Tổng khởi nghĩa”.","section_id":"muc-2","trap":"ban_chat"},{"note":"Tuyệt đối hóa: không có thời cơ (Nhật đầu hàng) thì Tổng khởi nghĩa khó thắng lợi nhanh chóng, ít đổ máu như vậy.","section_id":"muc-1","trap":"tuyet_doi"}]'::jsonb, 'Câu đánh giá: nhận xét mối quan hệ giữa các nguyên nhân thắng lợi.', 'Thời cơ khách quan + sự chuẩn bị và lãnh đạo chủ quan → thắng lợi; nhân tố chủ quan quyết định.', 12, '6-cach-mang-thang-tam-nam-1945', 'muc-2', null, 'van_dung', 'van_dung_kien_thuc', null, 'SGK Lịch sử 12 (KNTT), Bài 6, mục 2')
