values ('b6-m2-tn-11', 'mcq', 'Theo đoạn tư liệu, ba cao trào cách mạng chuẩn bị cho Cách mạng tháng Tám năm 1945 diễn ra vào những năm', (select id from public.exam_passages where title = 'Nguyên nhân thắng lợi của Cách mạng tháng Tám năm 1945' and body = 'Cách mạng tháng Tám năm 1945 thành công trước hết bắt nguồn từ truyền thống yêu nước, đấu tranh kiên cường chống ngoại xâm của dân tộc Việt Nam. Đảng Cộng sản Đông Dương, đứng đầu là Hồ Chí Minh, đã đề ra đường lối cách mạng đúng đắn, đặt nhiệm vụ giải phóng dân tộc lên hàng đầu, xây dựng khối đoàn kết toàn dân trong Mặt trận Việt Minh. Cuộc cách mạng là kết quả của quá trình chuẩn bị suốt 15 năm, qua ba cao trào cách mạng 1930 – 1931, 1936 – 1939 và 1939 – 1945. Khi thời cơ đến, Đảng kịp thời phát động Tổng khởi nghĩa.
Bên cạnh đó, thắng lợi của Liên Xô và quân Đồng minh trong cuộc chiến tranh chống chủ nghĩa phát xít đã cổ vũ tinh thần và tạo thời cơ khách quan thuận lợi để nhân dân Việt Nam đứng lên giành chính quyền.' order by created_at limit 1), array['1919 – 1925, 1925 – 1930 và 1930 – 1931', '1930 – 1931, 1936 – 1939 và 1945 – 1946', '1936 – 1939, 1939 – 1945 và 1945 – 1954', '1930 – 1931, 1936 – 1939 và 1939 – 1945'], 3, null, '[{"note":"Những năm 1919 – 1930 là thời kì Nguyễn Ái Quốc tìm đường cứu nước và chuẩn bị thành lập Đảng — trước ba cao trào.","lesson_slug":"16-ho-chi-minh-anh-hung-giai-phong-dan-toc","section_id":"muc-1","trap":"thoi_gian"},{"note":"Những năm 1945 – 1946 là thời kì xây dựng và bảo vệ chính quyền mới, sau Cách mạng tháng Tám.","lesson_slug":"7-khang-chien-chong-phap","section_id":"muc-1","trap":"thoi_gian"},{"note":"Những năm 1945 – 1954 là thời kì kháng chiến chống thực dân Pháp, sau Cách mạng tháng Tám.","lesson_slug":"7-khang-chien-chong-phap","section_id":"muc-1","trap":"thoi_gian"},{"note":"Đúng. Ba cao trào 1930 – 1931, 1936 – 1939, 1939 – 1945 là quá trình chuẩn bị lực lượng cho Tổng khởi nghĩa.","section_id":"muc-2"}]'::jsonb, 'Cả ba cao trào đều nằm trong 15 năm 1930 – 1945; các mốc sau năm 1945 thuộc giai đoạn khác.', 'Ba cao trào: 1930 – 1931, 1936 – 1939, 1939 – 1945.', 12, '6-cach-mang-thang-tam-nam-1945', 'muc-2', null, 'thong_hieu', 'nhan_thuc_tu_duy', null, 'SGK Lịch sử 12 (KNTT), Bài 6, mục 2')
