insert into public.exam_items (content_key, kind, stem, passage_id, choices, correct_index, statements, choice_notes, explanation, remember, grade, lesson_slug, section_id, topic_tag, level, competency, event_id, source_note)
values ('b6-m2-tn-12', 'mcq', 'Từ đoạn tư liệu, có thể rút ra bài học nào cho công cuộc xây dựng đất nước hiện nay?', (select id from public.exam_passages where title = 'Nguyên nhân thắng lợi của Cách mạng tháng Tám năm 1945' and body = 'Cách mạng tháng Tám năm 1945 thành công trước hết bắt nguồn từ truyền thống yêu nước, đấu tranh kiên cường chống ngoại xâm của dân tộc Việt Nam. Đảng Cộng sản Đông Dương, đứng đầu là Hồ Chí Minh, đã đề ra đường lối cách mạng đúng đắn, đặt nhiệm vụ giải phóng dân tộc lên hàng đầu, xây dựng khối đoàn kết toàn dân trong Mặt trận Việt Minh. Cuộc cách mạng là kết quả của quá trình chuẩn bị suốt 15 năm, qua ba cao trào cách mạng 1930 – 1931, 1936 – 1939 và 1939 – 1945. Khi thời cơ đến, Đảng kịp thời phát động Tổng khởi nghĩa.
Bên cạnh đó, thắng lợi của Liên Xô và quân Đồng minh trong cuộc chiến tranh chống chủ nghĩa phát xít đã cổ vũ tinh thần và tạo thời cơ khách quan thuận lợi để nhân dân Việt Nam đứng lên giành chính quyền.' order by created_at limit 1), array['Chủ yếu trông chờ vào sự hỗ trợ của các tổ chức quốc tế', 'Chỉ dựa vào sức mạnh quân sự để phát triển', 'Phát huy nội lực, tranh thủ điều kiện quốc tế thuận lợi', 'Đóng cửa, hạn chế quan hệ với nước ngoài'], 2, null, '[{"note":"Trái tư liệu: thắng lợi “trước hết” do sức mạnh bên trong; điều kiện quốc tế chỉ tạo thời cơ — không thể trông chờ bên ngoài.","section_id":"muc-2","trap":"ban_chat"},{"note":"Tư liệu nêu nhiều nguyên nhân (truyền thống, đường lối, đoàn kết, thời cơ), không chỉ sức mạnh quân sự.","section_id":"muc-2","trap":"tuyet_doi"},{"note":"Đúng. Nội lực (truyền thống, lãnh đạo, đoàn kết) giữ vai trò quyết định, kết hợp với điều kiện quốc tế thuận lợi — bài học vẫn có giá trị khi hội nhập hiện nay.","section_id":"muc-2"},{"note":"Năm 1945, thắng lợi có phần nhờ thời cơ quốc tế; đóng cửa là đi ngược bài học kết hợp sức mạnh dân tộc với điều kiện quốc tế.","lesson_slug":"11-thanh-tuu-va-bai-hoc-cua-cong-cuoc-doi-moi","section_id":"muc-2","trap":"ban_chat"}]'::jsonb, 'Câu vận dụng: rút bài học từ nguyên nhân thắng lợi.', 'Kết hợp nội lực (quyết định) với điều kiện quốc tế thuận lợi.', 12, '6-cach-mang-thang-tam-nam-1945', 'muc-2', null, 'van_dung', 'van_dung_kien_thuc', null, 'SGK Lịch sử 12 (KNTT), Bài 6, mục 2')
