-- ===== bai-07-khang-chien-chong-phap.json =====
insert into public.exam_passages (title, body, source_citation, lesson_slug)
select 'Lời kêu gọi toàn quốc kháng chiến (12-1946)', '“Chúng ta muốn hòa bình, chúng ta phải nhân nhượng. Nhưng chúng ta càng nhân nhượng, thực dân Pháp càng lấn tới, vì chúng quyết tâm cướp nước ta lần nữa! Không! Chúng ta thà hy sinh tất cả, chứ nhất định không chịu mất nước, nhất định không chịu làm nô lệ.”', 'Hồ Chí Minh, Lời kêu gọi toàn quốc kháng chiến, ngày 19-12-1946', '7-khang-chien-chong-phap'
where not exists (select 1 from public.exam_passages where title = 'Lời kêu gọi toàn quốc kháng chiến (12-1946)' and body = '“Chúng ta muốn hòa bình, chúng ta phải nhân nhượng. Nhưng chúng ta càng nhân nhượng, thực dân Pháp càng lấn tới, vì chúng quyết tâm cướp nước ta lần nữa! Không! Chúng ta thà hy sinh tất cả, chứ nhất định không chịu mất nước, nhất định không chịu làm nô lệ.”');
insert into public.exam_passages (title, body, source_citation, lesson_slug)
select 'Lời kêu gọi toàn quốc kháng chiến (12-1946) — đoạn kêu gọi toàn dân', '“Hỡi đồng bào!
Chúng ta phải đứng lên!
Bất kỳ đàn ông, đàn bà, bất kỳ người già, người trẻ, không chia tôn giáo, đảng phái, dân tộc. Hễ là người Việt Nam thì phải đứng lên đánh thực dân Pháp để cứu Tổ quốc. Ai có súng dùng súng. Ai có gươm dùng gươm, không có gươm thì dùng cuốc, thuồng, gậy gộc. Ai cũng phải ra sức chống thực dân Pháp cứu nước.”', 'Hồ Chí Minh, Lời kêu gọi toàn quốc kháng chiến, ngày 19-12-1946', '7-khang-chien-chong-phap'
where not exists (select 1 from public.exam_passages where title = 'Lời kêu gọi toàn quốc kháng chiến (12-1946) — đoạn kêu gọi toàn dân' and body = '“Hỡi đồng bào!
Chúng ta phải đứng lên!
Bất kỳ đàn ông, đàn bà, bất kỳ người già, người trẻ, không chia tôn giáo, đảng phái, dân tộc. Hễ là người Việt Nam thì phải đứng lên đánh thực dân Pháp để cứu Tổ quốc. Ai có súng dùng súng. Ai có gươm dùng gươm, không có gươm thì dùng cuốc, thuồng, gậy gộc. Ai cũng phải ra sức chống thực dân Pháp cứu nước.”');
insert into public.exam_passages (title, body, source_citation, lesson_slug)
select 'Nước Việt Nam Dân chủ Cộng hòa những năm 1945 – 1946', 'Sau Cách mạng tháng Tám, nước Việt Nam Dân chủ Cộng hòa đứng trước muôn vàn khó khăn. Ở miền Bắc, gần 20 vạn quân Trung Hoa Dân quốc kéo vào, kéo theo các tổ chức phản động; ở miền Nam, quân Anh vào giải giáp quân Nhật, tạo điều kiện cho thực dân Pháp quay lại xâm lược (23-9-1945). Nạn đói chưa được khắc phục, hơn 90% dân số mù chữ, ngân sách nhà nước gần như trống rỗng. Đất nước ở vào tình thế “ngàn cân treo sợi tóc”.
Chính phủ tổ chức Tổng tuyển cử bầu Quốc hội (6-1-1946), phát động tăng gia sản xuất, phong trào Bình dân học vụ, quyên góp “Tuần lễ vàng”. Về đối ngoại, từ tháng 9-1945 đến trước tháng 3-1946, Chính phủ hòa hoãn, nhân nhượng một số quyền lợi cho quân Trung Hoa Dân quốc ở miền Bắc để tập trung lực lượng kháng chiến chống Pháp ở Nam Bộ. Khi Pháp và Trung Hoa Dân quốc kí Hiệp ước Hoa – Pháp (28-2-1946), Chính phủ chuyển sang hòa hoãn với Pháp, kí Hiệp định Sơ bộ (6-3-1946) để đẩy quân Trung Hoa Dân quốc về nước, tranh thủ thời gian chuẩn bị cho cuộc kháng chiến lâu dài.', 'Tóm lược của biên tập viên theo SGK Lịch sử 12 (KNTT), Bài 7, mục 1', '7-khang-chien-chong-phap'
where not exists (select 1 from public.exam_passages where title = 'Nước Việt Nam Dân chủ Cộng hòa những năm 1945 – 1946' and body = 'Sau Cách mạng tháng Tám, nước Việt Nam Dân chủ Cộng hòa đứng trước muôn vàn khó khăn. Ở miền Bắc, gần 20 vạn quân Trung Hoa Dân quốc kéo vào, kéo theo các tổ chức phản động; ở miền Nam, quân Anh vào giải giáp quân Nhật, tạo điều kiện cho thực dân Pháp quay lại xâm lược (23-9-1945). Nạn đói chưa được khắc phục, hơn 90% dân số mù chữ, ngân sách nhà nước gần như trống rỗng. Đất nước ở vào tình thế “ngàn cân treo sợi tóc”.
Chính phủ tổ chức Tổng tuyển cử bầu Quốc hội (6-1-1946), phát động tăng gia sản xuất, phong trào Bình dân học vụ, quyên góp “Tuần lễ vàng”. Về đối ngoại, từ tháng 9-1945 đến trước tháng 3-1946, Chính phủ hòa hoãn, nhân nhượng một số quyền lợi cho quân Trung Hoa Dân quốc ở miền Bắc để tập trung lực lượng kháng chiến chống Pháp ở Nam Bộ. Khi Pháp và Trung Hoa Dân quốc kí Hiệp ước Hoa – Pháp (28-2-1946), Chính phủ chuyển sang hòa hoãn với Pháp, kí Hiệp định Sơ bộ (6-3-1946) để đẩy quân Trung Hoa Dân quốc về nước, tranh thủ thời gian chuẩn bị cho cuộc kháng chiến lâu dài.');
insert into public.exam_passages (title, body, source_citation, lesson_slug)
select 'Chiến dịch Biên giới thu – đông năm 1950', 'Từ năm 1949, Pháp thực hiện kế hoạch Rơ-ve, tăng cường hệ thống phòng ngự trên Đường số 4 nhằm khóa chặt biên giới Việt – Trung. Sau ba năm kháng chiến, lực lượng vũ trang và hậu phương của ta đã trưởng thành. Đầu năm 1950, Trung Quốc, Liên Xô và nhiều nước dân chủ nhân dân lần lượt công nhận và đặt quan hệ ngoại giao với nước Việt Nam Dân chủ Cộng hòa.
Tháng 6-1950, Trung ương Đảng quyết định mở chiến dịch Biên giới nhằm tiêu diệt một bộ phận sinh lực địch, khai thông đường liên lạc với Trung Quốc và các nước dân chủ, mở rộng và củng cố căn cứ địa Việt Bắc. Ngày 16-9-1950, quân ta mở màn chiến dịch bằng trận đánh cứ điểm Đông Khê. Sau hơn một tháng chiến đấu, quân ta giải phóng tuyến biên giới từ Cao Bằng đến Đình Lập, phá vỡ thế bao vây của địch; ta giành được quyền chủ động chiến lược trên chiến trường chính Bắc Bộ.', 'Tóm lược của biên tập viên theo SGK Lịch sử 12 (KNTT), Bài 7, mục 2', '7-khang-chien-chong-phap'
where not exists (select 1 from public.exam_passages where title = 'Chiến dịch Biên giới thu – đông năm 1950' and body = 'Từ năm 1949, Pháp thực hiện kế hoạch Rơ-ve, tăng cường hệ thống phòng ngự trên Đường số 4 nhằm khóa chặt biên giới Việt – Trung. Sau ba năm kháng chiến, lực lượng vũ trang và hậu phương của ta đã trưởng thành. Đầu năm 1950, Trung Quốc, Liên Xô và nhiều nước dân chủ nhân dân lần lượt công nhận và đặt quan hệ ngoại giao với nước Việt Nam Dân chủ Cộng hòa.
Tháng 6-1950, Trung ương Đảng quyết định mở chiến dịch Biên giới nhằm tiêu diệt một bộ phận sinh lực địch, khai thông đường liên lạc với Trung Quốc và các nước dân chủ, mở rộng và củng cố căn cứ địa Việt Bắc. Ngày 16-9-1950, quân ta mở màn chiến dịch bằng trận đánh cứ điểm Đông Khê. Sau hơn một tháng chiến đấu, quân ta giải phóng tuyến biên giới từ Cao Bằng đến Đình Lập, phá vỡ thế bao vây của địch; ta giành được quyền chủ động chiến lược trên chiến trường chính Bắc Bộ.');
insert into public.exam_passages (title, body, source_citation, lesson_slug)
select 'Kế hoạch Na-va và chiến dịch Điện Biên Phủ (1953 – 1954)', 'Năm 1953, với sự giúp đỡ của Mỹ, Pháp đề ra kế hoạch Na-va, hi vọng trong vòng 18 tháng giành thắng lợi quân sự quyết định để “kết thúc chiến tranh trong danh dự”. Trong Đông – Xuân 1953 – 1954, quân ta mở nhiều cuộc tiến công trên các hướng Tây Bắc, Trung Lào, Hạ Lào, Bắc Tây Nguyên và Thượng Lào, buộc địch phải phân tán lực lượng để đối phó; kế hoạch Na-va bước đầu bị phá sản.
Pháp xây dựng Điện Biên Phủ thành tập đoàn cứ điểm mạnh nhất Đông Dương, gồm 49 cứ điểm chia thành ba phân khu: Bắc, Trung tâm và Nam. Ta quyết định mở chiến dịch Điện Biên Phủ; phương châm tác chiến được chuyển từ “đánh nhanh, giải quyết nhanh” sang “đánh chắc, tiến chắc”. Chiến dịch diễn ra từ ngày 13-3 đến ngày 7-5-1954, qua ba đợt: đợt 1 tiêu diệt cụm cứ điểm Him Lam và phân khu Bắc; đợt 2 tiến công các cứ điểm phía đông phân khu Trung tâm; đợt 3 tổng công kích. Chiều 7-5-1954, tướng Đờ Ca-xtơ-ri cùng toàn bộ Bộ chỉ huy tập đoàn cứ điểm bị bắt sống.', 'Tóm lược của biên tập viên theo SGK Lịch sử 12 (KNTT), Bài 7, mục 3', '7-khang-chien-chong-phap'
where not exists (select 1 from public.exam_passages where title = 'Kế hoạch Na-va và chiến dịch Điện Biên Phủ (1953 – 1954)' and body = 'Năm 1953, với sự giúp đỡ của Mỹ, Pháp đề ra kế hoạch Na-va, hi vọng trong vòng 18 tháng giành thắng lợi quân sự quyết định để “kết thúc chiến tranh trong danh dự”. Trong Đông – Xuân 1953 – 1954, quân ta mở nhiều cuộc tiến công trên các hướng Tây Bắc, Trung Lào, Hạ Lào, Bắc Tây Nguyên và Thượng Lào, buộc địch phải phân tán lực lượng để đối phó; kế hoạch Na-va bước đầu bị phá sản.
Pháp xây dựng Điện Biên Phủ thành tập đoàn cứ điểm mạnh nhất Đông Dương, gồm 49 cứ điểm chia thành ba phân khu: Bắc, Trung tâm và Nam. Ta quyết định mở chiến dịch Điện Biên Phủ; phương châm tác chiến được chuyển từ “đánh nhanh, giải quyết nhanh” sang “đánh chắc, tiến chắc”. Chiến dịch diễn ra từ ngày 13-3 đến ngày 7-5-1954, qua ba đợt: đợt 1 tiêu diệt cụm cứ điểm Him Lam và phân khu Bắc; đợt 2 tiến công các cứ điểm phía đông phân khu Trung tâm; đợt 3 tổng công kích. Chiều 7-5-1954, tướng Đờ Ca-xtơ-ri cùng toàn bộ Bộ chỉ huy tập đoàn cứ điểm bị bắt sống.');
insert into public.exam_passages (title, body, source_citation, lesson_slug)
select 'Hiệp định Giơ-ne-vơ về Đông Dương (1954)', 'Ngày 8-5-1954, một ngày sau chiến thắng Điện Biên Phủ, Hội nghị Giơ-ne-vơ bắt đầu thảo luận về vấn đề Đông Dương. Ngày 21-7-1954, Hiệp định Giơ-ne-vơ về chấm dứt chiến tranh, lập lại hòa bình ở Đông Dương được kí kết. Các nước tham dự hội nghị cam kết tôn trọng các quyền dân tộc cơ bản là độc lập, chủ quyền, thống nhất và toàn vẹn lãnh thổ của ba nước Việt Nam, Lào, Cam-pu-chia. Ở Việt Nam, vĩ tuyến 17 (dọc theo sông Bến Hải, Quảng Trị) được lấy làm giới tuyến quân sự tạm thời; quân đội hai bên tập kết về hai miền; tổng tuyển cử tự do thống nhất đất nước sẽ được tổ chức vào tháng 7-1956.', 'Tóm lược của biên tập viên theo SGK Lịch sử 12 (KNTT), Bài 7, mục 3', '7-khang-chien-chong-phap'
where not exists (select 1 from public.exam_passages where title = 'Hiệp định Giơ-ne-vơ về Đông Dương (1954)' and body = 'Ngày 8-5-1954, một ngày sau chiến thắng Điện Biên Phủ, Hội nghị Giơ-ne-vơ bắt đầu thảo luận về vấn đề Đông Dương. Ngày 21-7-1954, Hiệp định Giơ-ne-vơ về chấm dứt chiến tranh, lập lại hòa bình ở Đông Dương được kí kết. Các nước tham dự hội nghị cam kết tôn trọng các quyền dân tộc cơ bản là độc lập, chủ quyền, thống nhất và toàn vẹn lãnh thổ của ba nước Việt Nam, Lào, Cam-pu-chia. Ở Việt Nam, vĩ tuyến 17 (dọc theo sông Bến Hải, Quảng Trị) được lấy làm giới tuyến quân sự tạm thời; quân đội hai bên tập kết về hai miền; tổng tuyển cử tự do thống nhất đất nước sẽ được tổ chức vào tháng 7-1956.');
insert into public.exam_passages (title, body, source_citation, lesson_slug)
select 'Nguyên nhân thắng lợi và ý nghĩa của cuộc kháng chiến chống thực dân Pháp', 'Cuộc kháng chiến chống thực dân Pháp thắng lợi nhờ sự lãnh đạo sáng suốt của Đảng, đứng đầu là Chủ tịch Hồ Chí Minh, với đường lối kháng chiến toàn dân, toàn diện, trường kì, tự lực cánh sinh. Cuộc kháng chiến có hậu phương rộng lớn, vững chắc; khối đoàn kết toàn dân được củng cố; lực lượng vũ trang ba thứ quân không ngừng lớn mạnh. Bên cạnh đó là liên minh chiến đấu của ba dân tộc Việt Nam, Lào, Cam-pu-chia và sự đồng tình, giúp đỡ của Trung Quốc, Liên Xô, các nước dân chủ nhân dân, nhân dân Pháp và nhân dân tiến bộ trên thế giới.
Thắng lợi đã chấm dứt cuộc chiến tranh xâm lược và ách thống trị của thực dân Pháp trên đất nước ta; miền Bắc được hoàn toàn giải phóng, chuyển sang giai đoạn cách mạng xã hội chủ nghĩa, tạo cơ sở để giải phóng miền Nam, thống nhất đất nước. Thắng lợi cũng giáng đòn nặng nề vào tham vọng xâm lược của chủ nghĩa đế quốc, góp phần làm tan rã hệ thống thuộc địa, cổ vũ phong trào giải phóng dân tộc trên thế giới.', 'Tóm lược của biên tập viên theo SGK Lịch sử 12 (KNTT), Bài 7, mục 4', '7-khang-chien-chong-phap'
where not exists (select 1 from public.exam_passages where title = 'Nguyên nhân thắng lợi và ý nghĩa của cuộc kháng chiến chống thực dân Pháp' and body = 'Cuộc kháng chiến chống thực dân Pháp thắng lợi nhờ sự lãnh đạo sáng suốt của Đảng, đứng đầu là Chủ tịch Hồ Chí Minh, với đường lối kháng chiến toàn dân, toàn diện, trường kì, tự lực cánh sinh. Cuộc kháng chiến có hậu phương rộng lớn, vững chắc; khối đoàn kết toàn dân được củng cố; lực lượng vũ trang ba thứ quân không ngừng lớn mạnh. Bên cạnh đó là liên minh chiến đấu của ba dân tộc Việt Nam, Lào, Cam-pu-chia và sự đồng tình, giúp đỡ của Trung Quốc, Liên Xô, các nước dân chủ nhân dân, nhân dân Pháp và nhân dân tiến bộ trên thế giới.
Thắng lợi đã chấm dứt cuộc chiến tranh xâm lược và ách thống trị của thực dân Pháp trên đất nước ta; miền Bắc được hoàn toàn giải phóng, chuyển sang giai đoạn cách mạng xã hội chủ nghĩa, tạo cơ sở để giải phóng miền Nam, thống nhất đất nước. Thắng lợi cũng giáng đòn nặng nề vào tham vọng xâm lược của chủ nghĩa đế quốc, góp phần làm tan rã hệ thống thuộc địa, cổ vũ phong trào giải phóng dân tộc trên thế giới.');
update public.exam_items set content_key = 'b7-m1-ds-01'
 where content_key is null and fingerprint = public.exam_item_fingerprint('true_false', 'Cho thông tin: “Ngày 6-3-1946, Chủ tịch Hồ Chí Minh thay mặt Chính phủ kí với đại diện Chính phủ Pháp bản Hiệp định Sơ bộ.”', null, '[{"text":"Theo Hiệp định, Pháp công nhận Việt Nam là một quốc gia tự do, có chính phủ, nghị viện, quân đội và tài chính riêng.","is_true":true,"explanation":"Đây là nội dung chính của Hiệp định Sơ bộ: Pháp công nhận Việt Nam là quốc gia tự do, nằm trong Liên bang Đông Dương và khối Liên hiệp Pháp.","section_id":"muc-1"},{"text":"Việt Nam đồng ý cho 15 000 quân Pháp ra miền Bắc thay quân Trung Hoa Dân quốc.","is_true":true,"explanation":"Số quân Pháp ra Bắc thay quân Trung Hoa Dân quốc sẽ rút dần trong thời hạn 5 năm.","section_id":"muc-1"},{"text":"Hiệp định Sơ bộ công nhận Việt Nam là một quốc gia độc lập hoàn toàn.","is_true":false,"explanation":"Nhầm khái niệm: Hiệp định chỉ công nhận “quốc gia tự do”, chưa phải “độc lập hoàn toàn”.","section_id":"muc-1","trap":"khai_niem"},{"text":"Sau khi kí Hiệp định Sơ bộ, chiến tranh giữa Việt Nam và Pháp chấm dứt hẳn.","is_true":false,"explanation":"Sai bản chất: Pháp tiếp tục lấn tới (gây hấn ở Hải Phòng, Lạng Sơn, Hà Nội); ngày 19-12-1946 kháng chiến toàn quốc bùng nổ.","section_id":"muc-1","trap":"ban_chat"}]'::jsonb)
   and not exists (select 1 from public.exam_items where content_key = 'b7-m1-ds-01');
insert into public.exam_items (content_key, kind, stem, passage_id, choices, correct_index, statements, choice_notes, explanation, remember, grade, lesson_slug, section_id, topic_tag, level, competency, event_id, source_note)
values ('b7-m1-ds-01', 'true_false', 'Cho thông tin: “Ngày 6-3-1946, Chủ tịch Hồ Chí Minh thay mặt Chính phủ kí với đại diện Chính phủ Pháp bản Hiệp định Sơ bộ.”', null, null, null, '[{"text":"Theo Hiệp định, Pháp công nhận Việt Nam là một quốc gia tự do, có chính phủ, nghị viện, quân đội và tài chính riêng.","is_true":true,"explanation":"Đây là nội dung chính của Hiệp định Sơ bộ: Pháp công nhận Việt Nam là quốc gia tự do, nằm trong Liên bang Đông Dương và khối Liên hiệp Pháp.","section_id":"muc-1"},{"text":"Việt Nam đồng ý cho 15 000 quân Pháp ra miền Bắc thay quân Trung Hoa Dân quốc.","is_true":true,"explanation":"Số quân Pháp ra Bắc thay quân Trung Hoa Dân quốc sẽ rút dần trong thời hạn 5 năm.","section_id":"muc-1"},{"text":"Hiệp định Sơ bộ công nhận Việt Nam là một quốc gia độc lập hoàn toàn.","is_true":false,"explanation":"Nhầm khái niệm: Hiệp định chỉ công nhận “quốc gia tự do”, chưa phải “độc lập hoàn toàn”.","section_id":"muc-1","trap":"khai_niem"},{"text":"Sau khi kí Hiệp định Sơ bộ, chiến tranh giữa Việt Nam và Pháp chấm dứt hẳn.","is_true":false,"explanation":"Sai bản chất: Pháp tiếp tục lấn tới (gây hấn ở Hải Phòng, Lạng Sơn, Hà Nội); ngày 19-12-1946 kháng chiến toàn quốc bùng nổ.","section_id":"muc-1","trap":"ban_chat"}]'::jsonb, null, 'Câu kiểm tra nội dung và ý nghĩa của Hiệp định Sơ bộ 6-3-1946.', 'Hiệp định Sơ bộ (6-3-1946): Việt Nam là “quốc gia tự do”; 15 000 quân Pháp ra Bắc thay quân Trung Hoa Dân quốc, rút dần trong 5 năm.', 12, '7-khang-chien-chong-phap', 'muc-1', null, 'thong_hieu', 'nhan_thuc_tu_duy', (select id from public.historical_events where slug = 'hiep-dinh-so-bo-6-3-1946'), 'SGK Lịch sử 12 (KNTT), Bài 7, mục 1')
on conflict (content_key) do update set kind = excluded.kind, stem = excluded.stem, passage_id = excluded.passage_id, choices = excluded.choices, correct_index = excluded.correct_index, statements = excluded.statements, choice_notes = excluded.choice_notes, explanation = excluded.explanation, remember = excluded.remember, grade = excluded.grade, lesson_slug = excluded.lesson_slug, section_id = excluded.section_id, topic_tag = excluded.topic_tag, level = excluded.level, competency = excluded.competency, event_id = excluded.event_id, source_note = excluded.source_note
 where public.exam_items.workflow_status in ('draft', 'needs_revision');
update public.exam_items set content_key = 'b7-m1-ds-02'
 where content_key is null and fingerprint = public.exam_item_fingerprint('true_false', 'Đọc đoạn trích Lời kêu gọi toàn quốc kháng chiến của Chủ tịch Hồ Chí Minh rồi xác định mỗi ý sau đúng hay sai.', null, '[{"text":"Lời kêu gọi hướng tới mọi người Việt Nam, không phân biệt giới tính, tuổi tác, tôn giáo, đảng phái, dân tộc.","is_true":true,"explanation":"“Bất kỳ đàn ông, đàn bà, bất kỳ người già, người trẻ, không chia tôn giáo, đảng phái, dân tộc.”","section_id":"muc-1"},{"text":"Lời kêu gọi chỉ hướng tới lực lượng vũ trang và thanh niên.","is_true":false,"explanation":"Thu hẹp đối tượng: lời kêu gọi hướng tới “bất kỳ người già, người trẻ” — mọi người dân, dùng mọi thứ vũ khí có trong tay.","section_id":"muc-1","trap":"tuyet_doi"},{"text":"Đoạn tư liệu thể hiện tinh thần kháng chiến toàn dân.","is_true":true,"explanation":"Mọi người dân đều phải đứng lên — nội dung “toàn dân” của đường lối kháng chiến.","section_id":"muc-2"},{"text":"Ngày nay, tinh thần “hễ là người Việt Nam thì phải đứng lên” không còn ý nghĩa vì đất nước đã hòa bình.","is_true":false,"explanation":"Hiểu sai: tinh thần ấy vẫn là cơ sở của nền quốc phòng toàn dân và trách nhiệm bảo vệ Tổ quốc của mọi công dân.","section_id":"muc-2","trap":"ban_chat"}]'::jsonb)
   and not exists (select 1 from public.exam_items where content_key = 'b7-m1-ds-02');
insert into public.exam_items (content_key, kind, stem, passage_id, choices, correct_index, statements, choice_notes, explanation, remember, grade, lesson_slug, section_id, topic_tag, level, competency, event_id, source_note)
values ('b7-m1-ds-02', 'true_false', 'Đọc đoạn trích Lời kêu gọi toàn quốc kháng chiến của Chủ tịch Hồ Chí Minh rồi xác định mỗi ý sau đúng hay sai.', (select id from public.exam_passages where title = 'Lời kêu gọi toàn quốc kháng chiến (12-1946) — đoạn kêu gọi toàn dân' and body = '“Hỡi đồng bào!
Chúng ta phải đứng lên!
Bất kỳ đàn ông, đàn bà, bất kỳ người già, người trẻ, không chia tôn giáo, đảng phái, dân tộc. Hễ là người Việt Nam thì phải đứng lên đánh thực dân Pháp để cứu Tổ quốc. Ai có súng dùng súng. Ai có gươm dùng gươm, không có gươm thì dùng cuốc, thuồng, gậy gộc. Ai cũng phải ra sức chống thực dân Pháp cứu nước.”' order by created_at limit 1), null, null, '[{"text":"Lời kêu gọi hướng tới mọi người Việt Nam, không phân biệt giới tính, tuổi tác, tôn giáo, đảng phái, dân tộc.","is_true":true,"explanation":"“Bất kỳ đàn ông, đàn bà, bất kỳ người già, người trẻ, không chia tôn giáo, đảng phái, dân tộc.”","section_id":"muc-1"},{"text":"Lời kêu gọi chỉ hướng tới lực lượng vũ trang và thanh niên.","is_true":false,"explanation":"Thu hẹp đối tượng: lời kêu gọi hướng tới “bất kỳ người già, người trẻ” — mọi người dân, dùng mọi thứ vũ khí có trong tay.","section_id":"muc-1","trap":"tuyet_doi"},{"text":"Đoạn tư liệu thể hiện tinh thần kháng chiến toàn dân.","is_true":true,"explanation":"Mọi người dân đều phải đứng lên — nội dung “toàn dân” của đường lối kháng chiến.","section_id":"muc-2"},{"text":"Ngày nay, tinh thần “hễ là người Việt Nam thì phải đứng lên” không còn ý nghĩa vì đất nước đã hòa bình.","is_true":false,"explanation":"Hiểu sai: tinh thần ấy vẫn là cơ sở của nền quốc phòng toàn dân và trách nhiệm bảo vệ Tổ quốc của mọi công dân.","section_id":"muc-2","trap":"ban_chat"}]'::jsonb, null, 'Câu đọc hiểu và liên hệ: tinh thần toàn dân kháng chiến.', '“Hễ là người Việt Nam thì phải đứng lên đánh thực dân Pháp để cứu Tổ quốc.”', 12, '7-khang-chien-chong-phap', 'muc-1', null, 'van_dung', 'van_dung_kien_thuc', (select id from public.historical_events where slug = 'toan-quoc-khang-chien-19-12-1946'), 'SGK Lịch sử 12 (KNTT), Bài 7, mục 1')
