 where content_key is null and fingerprint = public.exam_item_fingerprint('mcq', 'Đoạn tư liệu thể hiện rõ nhất điều gì?', array['Chủ trương hòa hoãn lâu dài với thực dân Pháp', 'Mong muốn dựa vào nước ngoài để giữ hòa bình', 'Kế hoạch tổng tiến công kết thúc chiến tranh', 'Quyết tâm bảo vệ độc lập, không chịu mất nước'], null)
   and not exists (select 1 from public.exam_items where content_key = 'b7-m1-tn-01');
insert into public.exam_items (content_key, kind, stem, passage_id, choices, correct_index, statements, choice_notes, explanation, remember, grade, lesson_slug, section_id, topic_tag, level, competency, event_id, source_note)
values ('b7-m1-tn-01', 'mcq', 'Đoạn tư liệu thể hiện rõ nhất điều gì?', (select id from public.exam_passages where title = 'Lời kêu gọi toàn quốc kháng chiến (12-1946)' and body = '“Chúng ta muốn hòa bình, chúng ta phải nhân nhượng. Nhưng chúng ta càng nhân nhượng, thực dân Pháp càng lấn tới, vì chúng quyết tâm cướp nước ta lần nữa! Không! Chúng ta thà hy sinh tất cả, chứ nhất định không chịu mất nước, nhất định không chịu làm nô lệ.”' order by created_at limit 1), array['Chủ trương hòa hoãn lâu dài với thực dân Pháp', 'Mong muốn dựa vào nước ngoài để giữ hòa bình', 'Kế hoạch tổng tiến công kết thúc chiến tranh', 'Quyết tâm bảo vệ độc lập, không chịu mất nước'], 3, null, '[{"note":"Trái tư liệu: “chúng ta càng nhân nhượng, thực dân Pháp càng lấn tới” — vì vậy không thể tiếp tục hòa hoãn.","section_id":"muc-1","trap":"ban_chat"},{"note":"Tư liệu không nói tới dựa vào nước ngoài; tinh thần chung là toàn dân tự đứng lên kháng chiến.","section_id":"muc-2","trap":"ban_chat"},{"note":"Năm 1946 ta mới bắt đầu kháng chiến toàn quốc, xác định đánh lâu dài; tư liệu không nói tới kế hoạch tổng tiến công kết thúc chiến tranh.","section_id":"muc-2","trap":"thoi_gian"},{"note":"Đúng. “Thà hy sinh tất cả, chứ nhất định không chịu mất nước, nhất định không chịu làm nô lệ” — quyết tâm bảo vệ nền độc lập vừa giành được.","section_id":"muc-1"}]'::jsonb, '“Thà hy sinh tất cả, chứ nhất định không chịu mất nước, nhất định không chịu làm nô lệ” thể hiện quyết tâm bảo vệ độc lập. Tư liệu nói đã nhân nhượng nhưng Pháp lấn tới, nên không còn hòa hoãn; tư liệu không nói tới dựa vào nước ngoài hay kế hoạch tổng tiến công.', '“Chúng ta thà hy sinh tất cả, chứ nhất định không chịu mất nước, nhất định không chịu làm nô lệ.” (19-12-1946)', 12, '7-khang-chien-chong-phap', 'muc-1', null, 'van_dung', 'nhan_thuc_tu_duy', (select id from public.historical_events where slug = 'toan-quoc-khang-chien-19-12-1946'), 'SGK Lịch sử 12 (KNTT), Bài 7, mục 1')
