insert into public.exam_items (content_key, kind, stem, passage_id, choices, correct_index, statements, choice_notes, explanation, remember, grade, lesson_slug, section_id, topic_tag, level, competency, event_id, source_note)
values ('b7-m1-tn-02', 'mcq', 'Cuộc Tổng tuyển cử bầu Quốc hội đầu tiên của nước Việt Nam Dân chủ Cộng hòa diễn ra vào ngày', null, array['2-9-1945', '6-1-1946', '2-3-1946', '19-12-1946'], 1, null, '[{"note":"Ngày 2-9-1945 là ngày Chủ tịch Hồ Chí Minh đọc Tuyên ngôn độc lập.","lesson_slug":"6-cach-mang-thang-tam-nam-1945","section_id":"muc-1","trap":"thoi_gian"},{"note":"Đúng. Ngày 6-1-1946, cuộc Tổng tuyển cử bầu Quốc hội đầu tiên diễn ra trong cả nước, bầu ra 333 đại biểu.","section_id":"muc-1"},{"note":"Ngày 2-3-1946 là ngày Quốc hội khóa I họp phiên đầu tiên, lập Chính phủ liên hiệp kháng chiến do Hồ Chí Minh đứng đầu.","section_id":"muc-1","trap":"thoi_gian"},{"note":"Ngày 19-12-1946 là ngày bùng nổ kháng chiến toàn quốc chống thực dân Pháp.","section_id":"muc-1","trap":"thoi_gian"}]'::jsonb, 'Tổng tuyển cử (6-1-1946) giúp chính quyền cách mạng có cơ sở pháp lí vững chắc, khẳng định quyền làm chủ của nhân dân.', '6-1-1946: Tổng tuyển cử bầu Quốc hội đầu tiên; 2-3-1946: Quốc hội họp phiên đầu tiên.', 12, '7-khang-chien-chong-phap', 'muc-1', null, 'nhan_biet', 'tim_hieu_lich_su', null, 'SGK Lịch sử 12 (KNTT), Bài 7, mục 1')
