insert into public.exam_items (content_key, kind, stem, passage_id, choices, correct_index, statements, choice_notes, explanation, remember, grade, lesson_slug, section_id, topic_tag, level, competency, event_id, source_note)
values ('b7-m1-tn-03', 'mcq', 'Để chống “giặc dốt” sau Cách mạng tháng Tám, ngày 8-9-1945 Chủ tịch Hồ Chí Minh kí sắc lệnh thành lập', null, array['Ủy ban Khởi nghĩa toàn quốc', 'Quỹ độc lập', 'Nha Bình dân học vụ', 'Hội Liên hiệp quốc dân Việt Nam'], 2, null, '[{"note":"Ủy ban Khởi nghĩa toàn quốc lập tháng 8-1945 để lãnh đạo Tổng khởi nghĩa, không phải để xóa nạn mù chữ.","lesson_slug":"6-cach-mang-thang-tam-nam-1945","section_id":"muc-1","trap":"thoi_gian"},{"note":"Quỹ độc lập (cùng “Tuần lễ vàng”) nhằm giải quyết khó khăn về tài chính, không phải chống nạn mù chữ.","section_id":"muc-1","trap":"khai_niem"},{"note":"Đúng. Nha Bình dân học vụ ra đời ngày 8-9-1945, phát động phong trào xóa mù chữ trong cả nước.","section_id":"muc-1"},{"note":"Hội Liên hiệp quốc dân Việt Nam (Liên Việt, 5-1946) là tổ chức mặt trận nhằm mở rộng khối đoàn kết dân tộc.","section_id":"muc-1","trap":"khai_niem"}]'::jsonb, 'Ba “giặc” sau Cách mạng tháng Tám: giặc đói, giặc dốt, giặc ngoại xâm — mỗi nhiệm vụ có biện pháp riêng.', 'Chống giặc dốt: Nha Bình dân học vụ (8-9-1945); khó khăn tài chính: Quỹ độc lập, Tuần lễ vàng.', 12, '7-khang-chien-chong-phap', 'muc-1', null, 'nhan_biet', 'tim_hieu_lich_su', null, 'SGK Lịch sử 12 (KNTT), Bài 7, mục 1')
