 where content_key is null and fingerprint = public.exam_item_fingerprint('mcq', 'Tình thế nước Việt Nam Dân chủ Cộng hòa sau Cách mạng tháng Tám được ví như “ngàn cân treo sợi tóc” vì đất nước', array['phải đối phó cùng lúc với giặc đói, giặc dốt, thù trong, giặc ngoài', 'chỉ phải đối phó với thực dân Pháp quay lại ở Nam Bộ', 'vẫn bị quân Nhật chiếm đóng ở các đô thị lớn', 'bị chia cắt thành hai miền ở vĩ tuyến 17'], null)
   and not exists (select 1 from public.exam_items where content_key = 'b7-m1-tn-04');
insert into public.exam_items (content_key, kind, stem, passage_id, choices, correct_index, statements, choice_notes, explanation, remember, grade, lesson_slug, section_id, topic_tag, level, competency, event_id, source_note)
values ('b7-m1-tn-04', 'mcq', 'Tình thế nước Việt Nam Dân chủ Cộng hòa sau Cách mạng tháng Tám được ví như “ngàn cân treo sợi tóc” vì đất nước', null, array['phải đối phó cùng lúc với giặc đói, giặc dốt, thù trong, giặc ngoài', 'chỉ phải đối phó với thực dân Pháp quay lại ở Nam Bộ', 'vẫn bị quân Nhật chiếm đóng ở các đô thị lớn', 'bị chia cắt thành hai miền ở vĩ tuyến 17'], 0, null, '[{"note":"Đúng. Gần 20 vạn quân Trung Hoa Dân quốc ở miền Bắc, quân Anh mở đường cho Pháp quay lại ở miền Nam, các thế lực phản động chống phá; thêm nạn đói, hơn 90% dân số mù chữ, ngân sách gần như trống rỗng.","section_id":"muc-1"},{"note":"Tuyệt đối hóa: ngoài Pháp ở Nam Bộ, ta còn phải đối phó với gần 20 vạn quân Trung Hoa Dân quốc ở miền Bắc, nạn đói, nạn dốt và khó khăn tài chính.","section_id":"muc-1","trap":"tuyet_doi"},{"note":"Hiểu sai: quân Nhật đã đầu hàng Đồng minh, đang chờ giải giáp, không còn cai trị đất nước.","section_id":"muc-1","trap":"ban_chat"},{"note":"Đất nước bị chia cắt ở vĩ tuyến 17 sau Hiệp định Giơ-ne-vơ (1954), không phải năm 1945.","section_id":"muc-3","trap":"thoi_gian"}]'::jsonb, '“Ngàn cân treo sợi tóc”: nhiều khó khăn chồng chất cùng lúc, đe dọa sự tồn tại của chính quyền mới.', 'Sau Cách mạng tháng Tám: giặc đói, giặc dốt, giặc ngoại xâm, nội phản, ngân sách trống rỗng — “ngàn cân treo sợi tóc”.', 12, '7-khang-chien-chong-phap', 'muc-1', null, 'thong_hieu', 'nhan_thuc_tu_duy', null, 'SGK Lịch sử 12 (KNTT), Bài 7, mục 1')
