 where content_key is null and fingerprint = public.exam_item_fingerprint('mcq', 'Mục đích chủ yếu của Chính phủ Việt Nam Dân chủ Cộng hòa khi kí Hiệp định Sơ bộ (6-3-1946) là', array['chấm dứt hoàn toàn chiến tranh giữa Việt Nam và Pháp', 'được Pháp công nhận Việt Nam độc lập hoàn toàn', 'nhờ quân Pháp đánh đuổi quân Trung Hoa Dân quốc', 'đẩy quân Trung Hoa Dân quốc về nước, có thời gian chuẩn bị lực lượng'], null)
