insert into public.exam_items (content_key, kind, stem, passage_id, choices, correct_index, statements, choice_notes, explanation, remember, grade, lesson_slug, section_id, topic_tag, level, competency, event_id, source_note)
values ('b7-m1-tn-05', 'mcq', 'Mục đích chủ yếu của Chính phủ Việt Nam Dân chủ Cộng hòa khi kí Hiệp định Sơ bộ (6-3-1946) là', null, array['chấm dứt hoàn toàn chiến tranh giữa Việt Nam và Pháp', 'được Pháp công nhận Việt Nam độc lập hoàn toàn', 'nhờ quân Pháp đánh đuổi quân Trung Hoa Dân quốc', 'đẩy quân Trung Hoa Dân quốc về nước, có thời gian chuẩn bị lực lượng'], 3, null, '[{"note":"Hiệp định chỉ là sự hòa hoãn tạm thời; Pháp tiếp tục lấn tới và cuối năm 1946 kháng chiến toàn quốc bùng nổ.","section_id":"muc-1","trap":"ban_chat"},{"note":"Pháp chỉ công nhận Việt Nam là “quốc gia tự do” trong Liên bang Đông Dương, khối Liên hiệp Pháp — chưa phải độc lập hoàn toàn.","section_id":"muc-1","trap":"ban_chat"},{"note":"Hiệp định quy định quân Pháp ra Bắc THAY quân Trung Hoa Dân quốc làm nhiệm vụ giải giáp quân Nhật — không có việc Pháp đánh quân Trung Hoa Dân quốc.","section_id":"muc-1","trap":"chu_the"},{"note":"Đúng. Hòa hoãn với Pháp để gạt quân Trung Hoa Dân quốc và tay sai ra khỏi miền Bắc, tránh cùng lúc đối phó nhiều kẻ thù, tranh thủ thời gian củng cố lực lượng.","section_id":"muc-1"}]'::jsonb, 'Hiệp định Sơ bộ là chủ trương “hòa để tiến”: nhân nhượng có nguyên tắc để giữ vững chính quyền.', 'Hiệp định Sơ bộ (6-3-1946): hòa với Pháp để đuổi quân Trung Hoa Dân quốc, tranh thủ thời gian chuẩn bị kháng chiến.', 12, '7-khang-chien-chong-phap', 'muc-1', null, 'thong_hieu', 'nhan_thuc_tu_duy', (select id from public.historical_events where slug = 'hiep-dinh-so-bo-6-3-1946'), 'SGK Lịch sử 12 (KNTT), Bài 7, mục 1')
