   and not exists (select 1 from public.exam_items where content_key = 'b7-m1-tn-06');
insert into public.exam_items (content_key, kind, stem, passage_id, choices, correct_index, statements, choice_notes, explanation, remember, grade, lesson_slug, section_id, topic_tag, level, competency, event_id, source_note)
values ('b7-m1-tn-06', 'mcq', 'Đoạn trích Lời kêu gọi toàn quốc kháng chiến thể hiện rõ nhất nguyên tắc nào trong đường lối kháng chiến chống thực dân Pháp?', (select id from public.exam_passages where title = 'Lời kêu gọi toàn quốc kháng chiến (12-1946) — đoạn kêu gọi toàn dân' and body = '“Hỡi đồng bào!
Chúng ta phải đứng lên!
Bất kỳ đàn ông, đàn bà, bất kỳ người già, người trẻ, không chia tôn giáo, đảng phái, dân tộc. Hễ là người Việt Nam thì phải đứng lên đánh thực dân Pháp để cứu Tổ quốc. Ai có súng dùng súng. Ai có gươm dùng gươm, không có gươm thì dùng cuốc, thuồng, gậy gộc. Ai cũng phải ra sức chống thực dân Pháp cứu nước.”' order by created_at limit 1), array['Kháng chiến trường kì', 'Kháng chiến toàn dân', 'Kháng chiến toàn diện', 'Tự lực cánh sinh'], 1, null, '[{"note":"Nhầm khái niệm: trường kì là kháng chiến lâu dài — đoạn trích không nói về thời gian.","section_id":"muc-2","trap":"khai_niem"},{"note":"Đúng. “Bất kỳ đàn ông, đàn bà, bất kỳ người già, người trẻ… Hễ là người Việt Nam thì phải đứng lên” — mọi người dân đều tham gia kháng chiến.","section_id":"muc-2"},{"note":"Nhầm khái niệm: toàn diện là kháng chiến trên mọi mặt (quân sự, chính trị, kinh tế, văn hóa, ngoại giao); đoạn trích nhấn mạnh con người tham gia.","section_id":"muc-2","trap":"khai_niem"},{"note":"Nhầm khái niệm: tự lực cánh sinh là dựa vào sức mình là chính — không phải ý chính của đoạn trích.","section_id":"muc-2","trap":"khai_niem"}]'::jsonb, 'Phân biệt bốn nội dung của đường lối kháng chiến: toàn dân, toàn diện, trường kì, tự lực cánh sinh.', 'Toàn dân: “Hễ là người Việt Nam thì phải đứng lên đánh thực dân Pháp để cứu Tổ quốc.”', 12, '7-khang-chien-chong-phap', 'muc-1', null, 'thong_hieu', 'nhan_thuc_tu_duy', (select id from public.historical_events where slug = 'toan-quoc-khang-chien-19-12-1946'), 'SGK Lịch sử 12 (KNTT), Bài 7, mục 1')
