update public.exam_items set content_key = 'b7-m1-tn-07'
 where content_key is null and fingerprint = public.exam_item_fingerprint('mcq', 'Từ đoạn tư liệu, có thể nhận xét gì về sách lược đối ngoại của Chính phủ Việt Nam Dân chủ Cộng hòa trong những năm 1945 – 1946?', array['Hòa hoãn cùng lúc với mọi kẻ thù để tránh chiến tranh', 'Kiên quyết đánh cùng lúc cả quân Pháp và quân Trung Hoa Dân quốc', 'Mềm dẻo, hòa hoãn với từng kẻ thù để tập trung đối phó kẻ thù chính', 'Dựa vào quân Trung Hoa Dân quốc để đánh đuổi thực dân Pháp'], null)
   and not exists (select 1 from public.exam_items where content_key = 'b7-m1-tn-07');
insert into public.exam_items (content_key, kind, stem, passage_id, choices, correct_index, statements, choice_notes, explanation, remember, grade, lesson_slug, section_id, topic_tag, level, competency, event_id, source_note)
values ('b7-m1-tn-07', 'mcq', 'Từ đoạn tư liệu, có thể nhận xét gì về sách lược đối ngoại của Chính phủ Việt Nam Dân chủ Cộng hòa trong những năm 1945 – 1946?', (select id from public.exam_passages where title = 'Nước Việt Nam Dân chủ Cộng hòa những năm 1945 – 1946' and body = 'Sau Cách mạng tháng Tám, nước Việt Nam Dân chủ Cộng hòa đứng trước muôn vàn khó khăn. Ở miền Bắc, gần 20 vạn quân Trung Hoa Dân quốc kéo vào, kéo theo các tổ chức phản động; ở miền Nam, quân Anh vào giải giáp quân Nhật, tạo điều kiện cho thực dân Pháp quay lại xâm lược (23-9-1945). Nạn đói chưa được khắc phục, hơn 90% dân số mù chữ, ngân sách nhà nước gần như trống rỗng. Đất nước ở vào tình thế “ngàn cân treo sợi tóc”.
Chính phủ tổ chức Tổng tuyển cử bầu Quốc hội (6-1-1946), phát động tăng gia sản xuất, phong trào Bình dân học vụ, quyên góp “Tuần lễ vàng”. Về đối ngoại, từ tháng 9-1945 đến trước tháng 3-1946, Chính phủ hòa hoãn, nhân nhượng một số quyền lợi cho quân Trung Hoa Dân quốc ở miền Bắc để tập trung lực lượng kháng chiến chống Pháp ở Nam Bộ. Khi Pháp và Trung Hoa Dân quốc kí Hiệp ước Hoa – Pháp (28-2-1946), Chính phủ chuyển sang hòa hoãn với Pháp, kí Hiệp định Sơ bộ (6-3-1946) để đẩy quân Trung Hoa Dân quốc về nước, tranh thủ thời gian chuẩn bị cho cuộc kháng chiến lâu dài.' order by created_at limit 1), array['Hòa hoãn cùng lúc với mọi kẻ thù để tránh chiến tranh', 'Kiên quyết đánh cùng lúc cả quân Pháp và quân Trung Hoa Dân quốc', 'Mềm dẻo, hòa hoãn với từng kẻ thù để tập trung đối phó kẻ thù chính', 'Dựa vào quân Trung Hoa Dân quốc để đánh đuổi thực dân Pháp'], 2, null, '[{"note":"Trước tháng 3-1946 ta vẫn kháng chiến chống Pháp ở Nam Bộ; sau đó mới hòa hoãn với Pháp — không hòa hoãn cùng lúc với mọi kẻ thù.","section_id":"muc-1","trap":"tuyet_doi"},{"note":"Trái tư liệu: Chính phủ tránh đối đầu cùng lúc với nhiều kẻ thù.","section_id":"muc-1","trap":"ban_chat"},{"note":"Đúng. Trước 6-3-1946 hòa với Trung Hoa Dân quốc để đánh Pháp ở Nam Bộ; sau Hiệp ước Hoa – Pháp, hòa với Pháp để đẩy Trung Hoa Dân quốc về nước — lợi dụng mâu thuẫn, phân hóa kẻ thù.","section_id":"muc-1"},{"note":"Ta chỉ nhân nhượng một số quyền lợi cho quân Trung Hoa Dân quốc, không dựa vào họ; chính họ cùng tay sai còn chống phá chính quyền cách mạng.","section_id":"muc-1","trap":"chu_the"}]'::jsonb, 'Câu nhận xét sách lược: cứng rắn về nguyên tắc, mềm dẻo về sách lược.', '1945 – 1946: hòa Trung Hoa Dân quốc để đánh Pháp (trước 6-3-1946) → hòa Pháp để đuổi Trung Hoa Dân quốc (Hiệp định Sơ bộ).', 12, '7-khang-chien-chong-phap', 'muc-1', null, 'van_dung', 'nhan_thuc_tu_duy', null, 'SGK Lịch sử 12 (KNTT), Bài 7, mục 1')
