update public.exam_items set content_key = 'b7-m2-ds-01'
 where content_key is null and fingerprint = public.exam_item_fingerprint('true_false', 'Đọc đoạn tư liệu về chiến dịch Biên giới thu – đông năm 1950 và xác định mỗi ý sau đúng hay sai.', null, '[{"text":"Ta chủ động mở chiến dịch Biên giới thu – đông năm 1950.","is_true":true,"explanation":"Trung ương Đảng quyết định mở chiến dịch (6-1950); ngày 16-9-1950 ta đánh Đông Khê.","section_id":"muc-2"},{"text":"Mục tiêu của chiến dịch là làm phá sản kế hoạch Na-va.","is_true":false,"explanation":"Sai thời gian: kế hoạch Na-va ra đời năm 1953; mục tiêu năm 1950 là tiêu diệt sinh lực địch, khai thông biên giới, mở rộng căn cứ địa.","section_id":"muc-3","trap":"thoi_gian"},{"text":"Sau chiến dịch, đường liên lạc giữa Việt Nam với Trung Quốc và các nước dân chủ được khai thông.","is_true":true,"explanation":"Tuyến biên giới từ Cao Bằng đến Đình Lập được giải phóng.","section_id":"muc-2"},{"text":"Sau chiến dịch, quân Pháp hoàn toàn mất khả năng tiến công.","is_true":false,"explanation":"Tuyệt đối hóa: ta giành quyền chủ động chiến lược trên chiến trường chính Bắc Bộ, nhưng Pháp vẫn còn mạnh và tiếp tục đề ra kế hoạch mới (Đờ Lát đơ Tát-xi-nhi, Na-va).","section_id":"muc-3","trap":"tuyet_doi"}]'::jsonb)
   and not exists (select 1 from public.exam_items where content_key = 'b7-m2-ds-01');
insert into public.exam_items (content_key, kind, stem, passage_id, choices, correct_index, statements, choice_notes, explanation, remember, grade, lesson_slug, section_id, topic_tag, level, competency, event_id, source_note)
values ('b7-m2-ds-01', 'true_false', 'Đọc đoạn tư liệu về chiến dịch Biên giới thu – đông năm 1950 và xác định mỗi ý sau đúng hay sai.', (select id from public.exam_passages where title = 'Chiến dịch Biên giới thu – đông năm 1950' and body = 'Từ năm 1949, Pháp thực hiện kế hoạch Rơ-ve, tăng cường hệ thống phòng ngự trên Đường số 4 nhằm khóa chặt biên giới Việt – Trung. Sau ba năm kháng chiến, lực lượng vũ trang và hậu phương của ta đã trưởng thành. Đầu năm 1950, Trung Quốc, Liên Xô và nhiều nước dân chủ nhân dân lần lượt công nhận và đặt quan hệ ngoại giao với nước Việt Nam Dân chủ Cộng hòa.
Tháng 6-1950, Trung ương Đảng quyết định mở chiến dịch Biên giới nhằm tiêu diệt một bộ phận sinh lực địch, khai thông đường liên lạc với Trung Quốc và các nước dân chủ, mở rộng và củng cố căn cứ địa Việt Bắc. Ngày 16-9-1950, quân ta mở màn chiến dịch bằng trận đánh cứ điểm Đông Khê. Sau hơn một tháng chiến đấu, quân ta giải phóng tuyến biên giới từ Cao Bằng đến Đình Lập, phá vỡ thế bao vây của địch; ta giành được quyền chủ động chiến lược trên chiến trường chính Bắc Bộ.' order by created_at limit 1), null, null, '[{"text":"Ta chủ động mở chiến dịch Biên giới thu – đông năm 1950.","is_true":true,"explanation":"Trung ương Đảng quyết định mở chiến dịch (6-1950); ngày 16-9-1950 ta đánh Đông Khê.","section_id":"muc-2"},{"text":"Mục tiêu của chiến dịch là làm phá sản kế hoạch Na-va.","is_true":false,"explanation":"Sai thời gian: kế hoạch Na-va ra đời năm 1953; mục tiêu năm 1950 là tiêu diệt sinh lực địch, khai thông biên giới, mở rộng căn cứ địa.","section_id":"muc-3","trap":"thoi_gian"},{"text":"Sau chiến dịch, đường liên lạc giữa Việt Nam với Trung Quốc và các nước dân chủ được khai thông.","is_true":true,"explanation":"Tuyến biên giới từ Cao Bằng đến Đình Lập được giải phóng.","section_id":"muc-2"},{"text":"Sau chiến dịch, quân Pháp hoàn toàn mất khả năng tiến công.","is_true":false,"explanation":"Tuyệt đối hóa: ta giành quyền chủ động chiến lược trên chiến trường chính Bắc Bộ, nhưng Pháp vẫn còn mạnh và tiếp tục đề ra kế hoạch mới (Đờ Lát đơ Tát-xi-nhi, Na-va).","section_id":"muc-3","trap":"tuyet_doi"}]'::jsonb, null, 'Câu đọc hiểu: mục tiêu, kết quả và giới hạn của thắng lợi Biên giới 1950.', 'Biên giới 1950: ta chủ động tiến công, khai thông biên giới, giành quyền chủ động trên chiến trường chính Bắc Bộ.', 12, '7-khang-chien-chong-phap', 'muc-2', null, 'thong_hieu', 'nhan_thuc_tu_duy', null, 'SGK Lịch sử 12 (KNTT), Bài 7, mục 2')
