 where content_key is null and fingerprint = public.exam_item_fingerprint('true_false', 'Cho thông tin: “Ngày 7-10-1947, thực dân Pháp huy động lực lượng lớn tấn công lên căn cứ địa Việt Bắc.” Mỗi ý sau đây đúng hay sai?', null, '[{"text":"Pháp muốn tiêu diệt cơ quan đầu não kháng chiến và bộ đội chủ lực của ta.","is_true":true,"explanation":"Đây là mục tiêu của cuộc tấn công lên Việt Bắc.","section_id":"muc-2"},{"text":"Cuộc tấn công này diễn ra sau chiến dịch Biên giới thu – đông năm 1950.","is_true":false,"explanation":"Sai thời gian: cuộc tấn công lên Việt Bắc diễn ra năm 1947, trước chiến dịch Biên giới ba năm.","section_id":"muc-2","trap":"thoi_gian"},{"text":"Sau 75 ngày đêm chiến đấu, quân dân ta đánh bại cuộc tấn công của địch.","is_true":true,"explanation":"Thắng lợi Việt Bắc thu – đông năm 1947.","section_id":"muc-2"},{"text":"Thắng lợi Việt Bắc năm 1947 đã đập tan kế hoạch Na-va.","is_true":false,"explanation":"Sai thời gian: Việt Bắc làm phá sản chiến lược “đánh nhanh, thắng nhanh”; kế hoạch Na-va (1953) bị đập tan ở Điện Biên Phủ.","section_id":"muc-3","trap":"thoi_gian"}]'::jsonb)
   and not exists (select 1 from public.exam_items where content_key = 'b7-m2-ds-02');
