values ('b7-m2-tn-01', 'mcq', 'Đường lối kháng chiến chống thực dân Pháp (1945 – 1954) của Đảng là', null, array['đánh nhanh, thắng nhanh, dựa vào viện trợ', 'chỉ đấu tranh ngoại giao, tránh xung đột', 'dựa vào quân Đồng minh để giải phóng đất nước', 'toàn dân, toàn diện, trường kì, tự lực cánh sinh'], 3, null, '[{"note":"“Đánh nhanh, thắng nhanh” là chiến lược của thực dân Pháp (bị phá sản ở Việt Bắc năm 1947), không phải đường lối của ta.","section_id":"muc-2","trap":"chu_the"},{"note":"Tuyệt đối hóa: ta kết hợp đấu tranh quân sự, chính trị, ngoại giao…; chỉ đấu tranh ngoại giao là sai — cuối năm 1946 ta đã phải cầm súng kháng chiến.","section_id":"muc-1","trap":"tuyet_doi"},{"note":"Dựa vào quân Đồng minh trái với nguyên tắc tự lực cánh sinh của cuộc kháng chiến.","section_id":"muc-2","trap":"ban_chat"},{"note":"Đúng. Đường lối kháng chiến: toàn dân, toàn diện, trường kì, tự lực cánh sinh và tranh thủ sự ủng hộ quốc tế — thể hiện trong Lời kêu gọi toàn quốc kháng chiến, Chỉ thị Toàn dân kháng chiến và tác phẩm Kháng chiến nhất định thắng lợi.","section_id":"muc-2"}]'::jsonb, 'Đường lối kháng chiến: toàn dân, toàn diện, trường kì, tự lực cánh sinh và tranh thủ sự ủng hộ của quốc tế.', 'Đường lối kháng chiến chống Pháp: toàn dân, toàn diện, trường kì, tự lực cánh sinh.', 12, '7-khang-chien-chong-phap', 'muc-2', null, 'nhan_biet', 'tim_hieu_lich_su', null, 'SGK Lịch sử 12 (KNTT), Bài 7, mục 2')
