values ('b7-m2-tn-02', 'mcq', 'Thắng lợi của chiến dịch Việt Bắc thu – đông năm 1947 đã làm thất bại âm mưu nào của thực dân Pháp?', null, array['Khóa chặt biên giới Việt – Trung bằng tuyến phòng ngự Đường số 4', 'Dùng người Việt đánh người Việt, lấy chiến tranh nuôi chiến tranh', 'Đánh nhanh, thắng nhanh để sớm kết thúc chiến tranh', 'Giành thắng lợi quân sự quyết định trong vòng 18 tháng'], 2, null, '[{"note":"Đây là âm mưu của kế hoạch Rơ-ve (1949), bị phá vỡ trong chiến dịch Biên giới năm 1950.","section_id":"muc-2","trap":"thoi_gian"},{"note":"Âm mưu này gắn với kế hoạch Đờ Lát đơ Tát-xi-nhi (cuối năm 1950), sau chiến dịch Việt Bắc ba năm.","section_id":"muc-3","trap":"thoi_gian"},{"note":"Đúng. Sau 75 ngày đêm chiến đấu, thắng lợi Việt Bắc làm phá sản chiến lược “đánh nhanh, thắng nhanh”, buộc Pháp chuyển sang đánh lâu dài.","section_id":"muc-2"},{"note":"Đây là mục tiêu của kế hoạch Na-va (1953), bị đập tan ở Điện Biên Phủ (1954).","section_id":"muc-3","trap":"thoi_gian"}]'::jsonb, 'Mỗi thắng lợi lớn làm thất bại một âm mưu, kế hoạch của Pháp: 1947 — đánh nhanh thắng nhanh; 1950 — kế hoạch Rơ-ve; 1954 — kế hoạch Na-va.', 'Việt Bắc thu – đông 1947 → phá sản chiến lược “đánh nhanh, thắng nhanh”.', 12, '7-khang-chien-chong-phap', 'muc-2', null, 'nhan_biet', 'tim_hieu_lich_su', null, 'SGK Lịch sử 12 (KNTT), Bài 7, mục 2')
