values ('b7-m2-tn-03', 'mcq', 'Trận mở màn chiến dịch Biên giới thu – đông năm 1950 là trận đánh vào cứ điểm', null, array['Đông Khê', 'Him Lam', 'Thất Khê', 'Nà Sản'], 0, null, '[{"note":"Đúng. Ngày 16-9-1950, quân ta tiến công cứ điểm Đông Khê, mở màn chiến dịch Biên giới.","section_id":"muc-2"},{"note":"Him Lam là trận mở màn chiến dịch Điện Biên Phủ (13-3-1954).","section_id":"muc-3","trap":"thoi_gian"},{"note":"Thất Khê là nơi quân Pháp tập trung lực lượng để đón cánh quân rút khỏi Cao Bằng — không phải trận mở màn.","section_id":"muc-2","trap":"dia_diem"},{"note":"Nà Sản là tập đoàn cứ điểm Pháp xây dựng trong chiến dịch Tây Bắc (1952).","section_id":"muc-3","trap":"thoi_gian"}]'::jsonb, 'Ghi nhớ trận mở màn của các chiến dịch lớn: Đông Khê (Biên giới 1950), Him Lam (Điện Biên Phủ 1954).', 'Biên giới 1950 mở màn ở Đông Khê (16-9-1950); Điện Biên Phủ mở màn ở Him Lam (13-3-1954).', 12, '7-khang-chien-chong-phap', 'muc-2', null, 'nhan_biet', 'tim_hieu_lich_su', null, 'SGK Lịch sử 12 (KNTT), Bài 7, mục 2')
