insert into public.exam_items (content_key, kind, stem, passage_id, choices, correct_index, statements, choice_notes, explanation, remember, grade, lesson_slug, section_id, topic_tag, level, competency, event_id, source_note)
values ('b7-m2-tn-04', 'mcq', 'Theo đoạn tư liệu, thắng lợi của chiến dịch Biên giới thu – đông năm 1950 đã', (select id from public.exam_passages where title = 'Chiến dịch Biên giới thu – đông năm 1950' and body = 'Từ năm 1949, Pháp thực hiện kế hoạch Rơ-ve, tăng cường hệ thống phòng ngự trên Đường số 4 nhằm khóa chặt biên giới Việt – Trung. Sau ba năm kháng chiến, lực lượng vũ trang và hậu phương của ta đã trưởng thành. Đầu năm 1950, Trung Quốc, Liên Xô và nhiều nước dân chủ nhân dân lần lượt công nhận và đặt quan hệ ngoại giao với nước Việt Nam Dân chủ Cộng hòa.
Tháng 6-1950, Trung ương Đảng quyết định mở chiến dịch Biên giới nhằm tiêu diệt một bộ phận sinh lực địch, khai thông đường liên lạc với Trung Quốc và các nước dân chủ, mở rộng và củng cố căn cứ địa Việt Bắc. Ngày 16-9-1950, quân ta mở màn chiến dịch bằng trận đánh cứ điểm Đông Khê. Sau hơn một tháng chiến đấu, quân ta giải phóng tuyến biên giới từ Cao Bằng đến Đình Lập, phá vỡ thế bao vây của địch; ta giành được quyền chủ động chiến lược trên chiến trường chính Bắc Bộ.' order by created_at limit 1), array['đập tan hoàn toàn kế hoạch Na-va của Pháp', 'làm phá sản chiến lược “đánh nhanh, thắng nhanh”', 'buộc Pháp phải kí Hiệp định Giơ-ne-vơ', 'giúp ta nắm thế chủ động chiến lược ở Bắc Bộ'], 3, null, '[{"note":"Kế hoạch Na-va ra đời năm 1953 và bị đập tan ở Điện Biên Phủ (1954).","section_id":"muc-3","trap":"thoi_gian"},{"note":"Đây là kết quả của chiến dịch Việt Bắc thu – đông năm 1947.","section_id":"muc-2","trap":"thoi_gian"},{"note":"Hiệp định Giơ-ne-vơ (1954) là kết quả trực tiếp của chiến thắng Điện Biên Phủ.","section_id":"muc-3","trap":"nhan_qua"},{"note":"Đúng. Ta giải phóng biên giới từ Cao Bằng đến Đình Lập, khai thông đường liên lạc quốc tế, giành quyền chủ động chiến lược trên chiến trường chính Bắc Bộ.","section_id":"muc-2"}]'::jsonb, 'Gắn mỗi chiến dịch với kết quả của nó: 1947 — phá sản đánh nhanh thắng nhanh; 1950 — giành chủ động; 1954 — đập tan Na-va.', 'Biên giới 1950: khai thông biên giới Việt – Trung, ta giành quyền chủ động chiến lược trên chiến trường chính Bắc Bộ.', 12, '7-khang-chien-chong-phap', 'muc-2', null, 'thong_hieu', 'nhan_thuc_tu_duy', null, 'SGK Lịch sử 12 (KNTT), Bài 7, mục 2')
