values ('b7-m2-tn-05', 'mcq', 'Điểm khác nhau cơ bản giữa chiến dịch Việt Bắc thu – đông năm 1947 và chiến dịch Biên giới thu – đông năm 1950 là', null, array['Việt Bắc do ta chủ động mở, Biên giới là ta phản công', 'Việt Bắc là phản công địch tấn công, Biên giới do ta chủ động tiến công', 'Việt Bắc dùng pháo binh là chủ yếu, Biên giới chỉ dùng du kích', 'Việt Bắc ta có viện trợ của Trung Quốc, Biên giới thì không có'], 1, null, '[{"note":"Đảo ngược: năm 1947 Pháp tấn công lên Việt Bắc, ta phản công; năm 1950 ta chủ động mở chiến dịch.","section_id":"muc-2","trap":"ban_chat"},{"note":"Đúng. Đây là bước chuyển của cuộc kháng chiến: từ phản công (1947) sang chủ động tiến công (1950).","section_id":"muc-2"},{"note":"Hiểu sai: chiến dịch Biên giới năm 1950 là chiến dịch tiến công lớn của bộ đội chủ lực, không chỉ dùng du kích.","section_id":"muc-2","trap":"ban_chat"},{"note":"Đảo ngược thời gian: ta chỉ bắt đầu nhận viện trợ của Trung Quốc từ năm 1950, sau khi hai nước đặt quan hệ ngoại giao.","section_id":"muc-2","trap":"thoi_gian"}]'::jsonb, 'Câu so sánh: chỉ ra sự chuyển biến về thế chủ động giữa hai chiến dịch.', '1947: Pháp tấn công, ta phản công · 1950: ta chủ động tiến công.', 12, '7-khang-chien-chong-phap', 'muc-2', null, 'van_dung', 'nhan_thuc_tu_duy', null, 'SGK Lịch sử 12 (KNTT), Bài 7, mục 2')
