values ('b7-m2-tn-06', 'mcq', 'Thu – đông năm 1947, thực dân Pháp mở cuộc tấn công lên căn cứ địa Việt Bắc nhằm', null, array['khai thông đường liên lạc giữa Việt Nam với Trung Quốc', 'xây dựng tập đoàn cứ điểm mạnh nhất Đông Dương', 'tiêu diệt cơ quan đầu não kháng chiến và bộ đội chủ lực', 'đánh chiếm thành phố Hải Phòng và Hà Nội'], 2, null, '[{"note":"Đánh tráo chủ thể: khai thông biên giới Việt – Trung là mục tiêu của TA trong chiến dịch Biên giới năm 1950.","section_id":"muc-2","trap":"chu_the"},{"note":"Pháp xây dựng tập đoàn cứ điểm Điện Biên Phủ trong những năm 1953 – 1954.","section_id":"muc-3","trap":"thoi_gian"},{"note":"Đúng. Pháp muốn tiêu diệt cơ quan đầu não kháng chiến và bộ đội chủ lực, khóa biên giới Việt – Trung, nhanh chóng kết thúc chiến tranh.","section_id":"muc-2"},{"note":"Pháp gây hấn ở Hải Phòng (11-1946) và đánh chiếm Hà Nội từ cuối năm 1946 – đầu năm 1947; mục tiêu cuộc tấn công thu – đông 1947 là căn cứ địa Việt Bắc.","section_id":"muc-1","trap":"thoi_gian"}]'::jsonb, 'Mục tiêu của địch năm 1947 gắn với chiến lược “đánh nhanh, thắng nhanh”.', 'Pháp tấn công Việt Bắc (1947) nhằm tiêu diệt cơ quan đầu não kháng chiến — thất bại sau 75 ngày đêm.', 12, '7-khang-chien-chong-phap', 'muc-2', null, 'nhan_biet', 'tim_hieu_lich_su', null, 'SGK Lịch sử 12 (KNTT), Bài 7, mục 2')
