values ('b7-m2-tn-07', 'mcq', 'Theo đoạn tư liệu, vì sao năm 1950 ta có thể chủ động mở một chiến dịch tiến công lớn ở biên giới?', (select id from public.exam_passages where title = 'Chiến dịch Biên giới thu – đông năm 1950' and body = 'Từ năm 1949, Pháp thực hiện kế hoạch Rơ-ve, tăng cường hệ thống phòng ngự trên Đường số 4 nhằm khóa chặt biên giới Việt – Trung. Sau ba năm kháng chiến, lực lượng vũ trang và hậu phương của ta đã trưởng thành. Đầu năm 1950, Trung Quốc, Liên Xô và nhiều nước dân chủ nhân dân lần lượt công nhận và đặt quan hệ ngoại giao với nước Việt Nam Dân chủ Cộng hòa.
Tháng 6-1950, Trung ương Đảng quyết định mở chiến dịch Biên giới nhằm tiêu diệt một bộ phận sinh lực địch, khai thông đường liên lạc với Trung Quốc và các nước dân chủ, mở rộng và củng cố căn cứ địa Việt Bắc. Ngày 16-9-1950, quân ta mở màn chiến dịch bằng trận đánh cứ điểm Đông Khê. Sau hơn một tháng chiến đấu, quân ta giải phóng tuyến biên giới từ Cao Bằng đến Đình Lập, phá vỡ thế bao vây của địch; ta giành được quyền chủ động chiến lược trên chiến trường chính Bắc Bộ.' order by created_at limit 1), array['Lực lượng ta lớn mạnh, lại có điều kiện quốc tế thuận lợi', 'Pháp đã rút hết quân khỏi biên giới phía Bắc', 'Mỹ đã ngừng viện trợ quân sự cho Pháp', 'Hiệp định Giơ-ne-vơ đã được kí kết'], 0, null, '[{"note":"Đúng. Sau ba năm kháng chiến, lực lượng ta trưởng thành; đầu năm 1950, Trung Quốc, Liên Xô… công nhận và đặt quan hệ ngoại giao với ta — cần và có thể khai thông đường liên lạc quốc tế.","section_id":"muc-2"},{"note":"Trái tư liệu: Pháp tăng cường phòng ngự trên Đường số 4 để khóa chặt biên giới (kế hoạch Rơ-ve).","section_id":"muc-2","trap":"ban_chat"},{"note":"Ngược lại, từ năm 1950 Mỹ ngày càng can thiệp sâu, tăng viện trợ cho Pháp.","section_id":"muc-3","trap":"ban_chat"},{"note":"Hiệp định Giơ-ne-vơ kí năm 1954, sau chiến dịch Biên giới bốn năm.","section_id":"muc-3","trap":"thoi_gian"}]'::jsonb, 'Câu giải thích bối cảnh: điều kiện bên trong và bên ngoài cho chiến dịch Biên giới.', 'Năm 1950: lực lượng ta lớn mạnh + các nước công nhận và giúp đỡ → ta chủ động mở chiến dịch Biên giới.', 12, '7-khang-chien-chong-phap', 'muc-2', null, 'van_dung', 'nhan_thuc_tu_duy', null, 'SGK Lịch sử 12 (KNTT), Bài 7, mục 2')
