update public.exam_items set content_key = 'b7-m3-ds-01'
 where content_key is null and fingerprint = public.exam_item_fingerprint('true_false', 'Đọc đoạn tư liệu về kế hoạch Na-va và chiến dịch Điện Biên Phủ rồi cho biết mỗi ý sau đúng hay sai.', null, '[{"text":"Tập đoàn cứ điểm Điện Biên Phủ gồm 49 cứ điểm, chia thành ba phân khu.","is_true":true,"explanation":"Tư liệu: 49 cứ điểm, ba phân khu Bắc, Trung tâm và Nam.","section_id":"muc-3"},{"text":"Trong đợt 1, quân ta tiêu diệt phân khu Nam (Hồng Cúm).","is_true":false,"explanation":"Đánh tráo địa điểm: đợt 1 tiêu diệt cụm cứ điểm Him Lam và phân khu Bắc.","section_id":"muc-3","trap":"dia_diem"},{"text":"Chiều 7-5-1954, tướng Đờ Ca-xtơ-ri cùng toàn bộ Bộ chỉ huy tập đoàn cứ điểm bị bắt sống.","is_true":true,"explanation":"Đây là thời điểm kết thúc chiến dịch.","section_id":"muc-3"},{"text":"Chiến thắng Điện Biên Phủ chỉ bước đầu làm phá sản kế hoạch Na-va.","is_true":false,"explanation":"Đề đảo mốc: Đông – Xuân 1953 – 1954 làm phá sản BƯỚC ĐẦU; Điện Biên Phủ đập tan HOÀN TOÀN kế hoạch Na-va.","section_id":"muc-3","trap":"khai_niem"}]'::jsonb)
   and not exists (select 1 from public.exam_items where content_key = 'b7-m3-ds-01');
insert into public.exam_items (content_key, kind, stem, passage_id, choices, correct_index, statements, choice_notes, explanation, remember, grade, lesson_slug, section_id, topic_tag, level, competency, event_id, source_note)
values ('b7-m3-ds-01', 'true_false', 'Đọc đoạn tư liệu về kế hoạch Na-va và chiến dịch Điện Biên Phủ rồi cho biết mỗi ý sau đúng hay sai.', (select id from public.exam_passages where title = 'Kế hoạch Na-va và chiến dịch Điện Biên Phủ (1953 – 1954)' and body = 'Năm 1953, với sự giúp đỡ của Mỹ, Pháp đề ra kế hoạch Na-va, hi vọng trong vòng 18 tháng giành thắng lợi quân sự quyết định để “kết thúc chiến tranh trong danh dự”. Trong Đông – Xuân 1953 – 1954, quân ta mở nhiều cuộc tiến công trên các hướng Tây Bắc, Trung Lào, Hạ Lào, Bắc Tây Nguyên và Thượng Lào, buộc địch phải phân tán lực lượng để đối phó; kế hoạch Na-va bước đầu bị phá sản.
Pháp xây dựng Điện Biên Phủ thành tập đoàn cứ điểm mạnh nhất Đông Dương, gồm 49 cứ điểm chia thành ba phân khu: Bắc, Trung tâm và Nam. Ta quyết định mở chiến dịch Điện Biên Phủ; phương châm tác chiến được chuyển từ “đánh nhanh, giải quyết nhanh” sang “đánh chắc, tiến chắc”. Chiến dịch diễn ra từ ngày 13-3 đến ngày 7-5-1954, qua ba đợt: đợt 1 tiêu diệt cụm cứ điểm Him Lam và phân khu Bắc; đợt 2 tiến công các cứ điểm phía đông phân khu Trung tâm; đợt 3 tổng công kích. Chiều 7-5-1954, tướng Đờ Ca-xtơ-ri cùng toàn bộ Bộ chỉ huy tập đoàn cứ điểm bị bắt sống.' order by created_at limit 1), null, null, '[{"text":"Tập đoàn cứ điểm Điện Biên Phủ gồm 49 cứ điểm, chia thành ba phân khu.","is_true":true,"explanation":"Tư liệu: 49 cứ điểm, ba phân khu Bắc, Trung tâm và Nam.","section_id":"muc-3"},{"text":"Trong đợt 1, quân ta tiêu diệt phân khu Nam (Hồng Cúm).","is_true":false,"explanation":"Đánh tráo địa điểm: đợt 1 tiêu diệt cụm cứ điểm Him Lam và phân khu Bắc.","section_id":"muc-3","trap":"dia_diem"},{"text":"Chiều 7-5-1954, tướng Đờ Ca-xtơ-ri cùng toàn bộ Bộ chỉ huy tập đoàn cứ điểm bị bắt sống.","is_true":true,"explanation":"Đây là thời điểm kết thúc chiến dịch.","section_id":"muc-3"},{"text":"Chiến thắng Điện Biên Phủ chỉ bước đầu làm phá sản kế hoạch Na-va.","is_true":false,"explanation":"Đề đảo mốc: Đông – Xuân 1953 – 1954 làm phá sản BƯỚC ĐẦU; Điện Biên Phủ đập tan HOÀN TOÀN kế hoạch Na-va.","section_id":"muc-3","trap":"khai_niem"}]'::jsonb, null, 'Câu đọc hiểu: cấu trúc tập đoàn cứ điểm, diễn biến và kết quả chiến dịch.', 'Điện Biên Phủ: 49 cứ điểm, 3 phân khu, 3 đợt tiến công, 56 ngày đêm.', 12, '7-khang-chien-chong-phap', 'muc-3', null, 'thong_hieu', 'nhan_thuc_tu_duy', (select id from public.historical_events where slug = 'chien-dich-dien-bien-phu'), 'SGK Lịch sử 12 (KNTT), Bài 7, mục 3')
