update public.exam_items set content_key = 'b7-m3-ds-02'
 where content_key is null and fingerprint = public.exam_item_fingerprint('true_false', 'Đọc đoạn tư liệu về Hiệp định Giơ-ne-vơ năm 1954 và cho biết mỗi ý a), b), c), d) đúng hay sai.', null, '[{"text":"Hiệp định Giơ-ne-vơ được kí kết sau thắng lợi của chiến dịch Điện Biên Phủ.","is_true":true,"explanation":"Điện Biên Phủ kết thúc ngày 7-5-1954; ngày 8-5 hội nghị bàn về Đông Dương; hiệp định kí ngày 21-7-1954.","section_id":"muc-3"},{"text":"Vĩ tuyến 17 là đường biên giới quốc gia chia Việt Nam thành hai nước.","is_true":false,"explanation":"Tư liệu ghi rõ đây là giới tuyến quân sự TẠM THỜI, chờ tổng tuyển cử tháng 7-1956 — không phải biên giới quốc gia.","section_id":"muc-3","trap":"khai_niem"},{"text":"Các nước tham dự hội nghị cam kết tôn trọng các quyền dân tộc cơ bản của ba nước Đông Dương.","is_true":true,"explanation":"Tư liệu nêu rõ cam kết tôn trọng độc lập, chủ quyền, thống nhất và toàn vẹn lãnh thổ của Việt Nam, Lào, Cam-pu-chia.","section_id":"muc-3"},{"text":"Với Hiệp định Giơ-ne-vơ, cách mạng dân tộc dân chủ nhân dân đã hoàn thành trên cả nước.","is_true":false,"explanation":"Tuyệt đối hóa: hiệp định chỉ giải phóng hoàn toàn miền Bắc; miền Nam còn phải tiếp tục đấu tranh — vì vậy mới có cuộc kháng chiến chống Mỹ.","lesson_slug":"8-khang-chien-chong-my-cuu-nuoc","section_id":"muc-1","trap":"tuyet_doi"}]'::jsonb)
   and not exists (select 1 from public.exam_items where content_key = 'b7-m3-ds-02');
insert into public.exam_items (content_key, kind, stem, passage_id, choices, correct_index, statements, choice_notes, explanation, remember, grade, lesson_slug, section_id, topic_tag, level, competency, event_id, source_note)
values ('b7-m3-ds-02', 'true_false', 'Đọc đoạn tư liệu về Hiệp định Giơ-ne-vơ năm 1954 và cho biết mỗi ý a), b), c), d) đúng hay sai.', (select id from public.exam_passages where title = 'Hiệp định Giơ-ne-vơ về Đông Dương (1954)' and body = 'Ngày 8-5-1954, một ngày sau chiến thắng Điện Biên Phủ, Hội nghị Giơ-ne-vơ bắt đầu thảo luận về vấn đề Đông Dương. Ngày 21-7-1954, Hiệp định Giơ-ne-vơ về chấm dứt chiến tranh, lập lại hòa bình ở Đông Dương được kí kết. Các nước tham dự hội nghị cam kết tôn trọng các quyền dân tộc cơ bản là độc lập, chủ quyền, thống nhất và toàn vẹn lãnh thổ của ba nước Việt Nam, Lào, Cam-pu-chia. Ở Việt Nam, vĩ tuyến 17 (dọc theo sông Bến Hải, Quảng Trị) được lấy làm giới tuyến quân sự tạm thời; quân đội hai bên tập kết về hai miền; tổng tuyển cử tự do thống nhất đất nước sẽ được tổ chức vào tháng 7-1956.' order by created_at limit 1), null, null, '[{"text":"Hiệp định Giơ-ne-vơ được kí kết sau thắng lợi của chiến dịch Điện Biên Phủ.","is_true":true,"explanation":"Điện Biên Phủ kết thúc ngày 7-5-1954; ngày 8-5 hội nghị bàn về Đông Dương; hiệp định kí ngày 21-7-1954.","section_id":"muc-3"},{"text":"Vĩ tuyến 17 là đường biên giới quốc gia chia Việt Nam thành hai nước.","is_true":false,"explanation":"Tư liệu ghi rõ đây là giới tuyến quân sự TẠM THỜI, chờ tổng tuyển cử tháng 7-1956 — không phải biên giới quốc gia.","section_id":"muc-3","trap":"khai_niem"},{"text":"Các nước tham dự hội nghị cam kết tôn trọng các quyền dân tộc cơ bản của ba nước Đông Dương.","is_true":true,"explanation":"Tư liệu nêu rõ cam kết tôn trọng độc lập, chủ quyền, thống nhất và toàn vẹn lãnh thổ của Việt Nam, Lào, Cam-pu-chia.","section_id":"muc-3"},{"text":"Với Hiệp định Giơ-ne-vơ, cách mạng dân tộc dân chủ nhân dân đã hoàn thành trên cả nước.","is_true":false,"explanation":"Tuyệt đối hóa: hiệp định chỉ giải phóng hoàn toàn miền Bắc; miền Nam còn phải tiếp tục đấu tranh — vì vậy mới có cuộc kháng chiến chống Mỹ.","lesson_slug":"8-khang-chien-chong-my-cuu-nuoc","section_id":"muc-1","trap":"tuyet_doi"}]'::jsonb, null, 'Câu kiểm tra nội dung và ý nghĩa Hiệp định Giơ-ne-vơ: phân biệt giới tuyến quân sự tạm thời với biên giới, và thấy rõ thắng lợi mới trọn vẹn ở miền Bắc.', 'Giơ-ne-vơ 21-7-1954: vĩ tuyến 17 là giới tuyến quân sự tạm thời; miền Bắc được giải phóng.', 12, '7-khang-chien-chong-phap', 'muc-3', null, 'van_dung', 'van_dung_kien_thuc', (select id from public.historical_events where slug = 'hiep-dinh-geneve-ve-dong-duong'), 'SGK Lịch sử 12 (KNTT), Bài 7, mục 3')
