values ('b7-m3-tn-01', 'mcq', 'Đại hội đại biểu toàn quốc lần thứ II của Đảng (2-1951) đã quyết định', null, array['phát động Tổng khởi nghĩa giành chính quyền', 'đưa Đảng ra hoạt động công khai với tên Đảng Lao động Việt Nam', 'đề ra đường lối đổi mới toàn diện đất nước', 'thành lập Mặt trận Việt Minh'], 1, null, '[{"note":"Tổng khởi nghĩa giành chính quyền được phát động tháng 8-1945.","lesson_slug":"6-cach-mang-thang-tam-nam-1945","section_id":"muc-1","trap":"thoi_gian"},{"note":"Đúng. Đại hội II (2-1951, Tuyên Quang) quyết định đưa Đảng ra hoạt động công khai với tên Đảng Lao động Việt Nam; Hồ Chí Minh được bầu làm Chủ tịch Đảng, Trường Chinh làm Tổng Bí thư.","section_id":"muc-3"},{"note":"Đường lối đổi mới toàn diện do Đại hội VI (12-1986) đề ra.","lesson_slug":"10-khai-quat-ve-cong-cuoc-doi-moi","section_id":"muc-1","trap":"thoi_gian"},{"note":"Mặt trận Việt Minh thành lập năm 1941 theo quyết định của Hội nghị Trung ương 8.","lesson_slug":"16-ho-chi-minh-anh-hung-giai-phong-dan-toc","section_id":"muc-2","trap":"thoi_gian"}]'::jsonb, 'Đại hội II (2-1951) quyết định đưa Đảng ra hoạt động công khai, lấy tên Đảng Lao động Việt Nam. Đường lối đổi mới thuộc Đại hội VI (1986); Việt Minh thành lập năm 1941; Tổng khởi nghĩa năm 1945.', 'Đại hội II (2-1951): Đảng ra hoạt động công khai với tên Đảng Lao động Việt Nam.', 12, '7-khang-chien-chong-phap', 'muc-3', null, 'nhan_biet', 'tim_hieu_lich_su', null, 'SGK Lịch sử 12 (KNTT), Bài 7, mục 3')
