values ('b7-m3-tn-02', 'mcq', 'Năm 1953, với sự giúp đỡ của Mỹ, thực dân Pháp đề ra kế hoạch quân sự nào nhằm giành thắng lợi quyết định trong vòng 18 tháng?', null, array['Kế hoạch Na-va', 'Kế hoạch Rơ-ve', 'Kế hoạch Xta-lây – Tay-lo', 'Kế hoạch Mác-san'], 0, null, '[{"note":"Đúng. Kế hoạch Na-va (1953) dự định trong 18 tháng giành thắng lợi quân sự quyết định, “kết thúc chiến tranh trong danh dự”.","section_id":"muc-3"},{"note":"Kế hoạch Rơ-ve có từ năm 1949, nhằm khóa chặt biên giới Việt – Trung.","section_id":"muc-2","trap":"thoi_gian"},{"note":"Kế hoạch Xta-lây – Tay-lo (1961) của Mỹ cũng đặt mốc 18 tháng, nhưng là để bình định miền Nam trong “Chiến tranh đặc biệt” — không phải kế hoạch của Pháp năm 1953.","lesson_slug":"8-khang-chien-chong-my-cuu-nuoc","section_id":"muc-1","trap":"chu_the"},{"note":"Kế hoạch Mác-san là kế hoạch viện trợ của Mỹ giúp các nước Tây Âu phục hồi kinh tế sau Chiến tranh thế giới thứ hai.","lesson_slug":"2-trat-tu-the-gioi-trong-chien-tranh-lanh","section_id":"muc-1","trap":"khai_niem"}]'::jsonb, 'Kế hoạch Na-va (1953) hi vọng trong 18 tháng giành thắng lợi quân sự quyết định. Cẩn thận: kế hoạch Xta-lây – Tay-lo (1961) của Mỹ cũng đặt mốc 18 tháng nhưng là để bình định miền Nam.', 'Kế hoạch Na-va (1953): trong 18 tháng giành thắng lợi quyết định — bị đập tan ở Điện Biên Phủ.', 12, '7-khang-chien-chong-phap', 'muc-3', null, 'nhan_biet', 'tim_hieu_lich_su', null, 'SGK Lịch sử 12 (KNTT), Bài 7, mục 3')
