values ('b7-m3-tn-03', 'mcq', 'Chiến dịch Điện Biên Phủ kết thúc thắng lợi vào ngày', null, array['13-3-1954', '7-5-1954', '8-5-1954', '21-7-1954'], 1, null, '[{"note":"Ngày 13-3-1954, quân ta mở màn chiến dịch, tiến công cụm cứ điểm Him Lam.","section_id":"muc-3","trap":"thoi_gian"},{"note":"Đúng. Chiều 7-5-1954, tướng Đờ Ca-xtơ-ri cùng Bộ chỉ huy bị bắt sống; chiến dịch toàn thắng sau 56 ngày đêm.","section_id":"muc-3"},{"note":"Ngày 8-5-1954, Hội nghị Giơ-ne-vơ bắt đầu thảo luận về vấn đề Đông Dương.","section_id":"muc-3","trap":"thoi_gian"},{"note":"Ngày 21-7-1954, Hiệp định Giơ-ne-vơ được kí kết.","section_id":"muc-3","trap":"thoi_gian"}]'::jsonb, 'Bốn mốc liền nhau năm 1954: 13-3 (mở màn), 7-5 (toàn thắng), 8-5 (hội nghị bàn về Đông Dương), 21-7 (kí hiệp định).', 'Điện Biên Phủ: 13-3 → 7-5-1954, 56 ngày đêm.', 12, '7-khang-chien-chong-phap', 'muc-3', null, 'nhan_biet', 'tim_hieu_lich_su', (select id from public.historical_events where slug = 'chien-dich-dien-bien-phu'), 'SGK Lịch sử 12 (KNTT), Bài 7, mục 3')
