values ('b7-m3-tn-04', 'mcq', 'Hình ảnh hàng chục vạn dân công cùng hàng vạn xe đạp thồ vượt núi, băng rừng tiếp tế cho chiến dịch Điện Biên Phủ phản ánh điều gì?', null, array['Sức mạnh chiến tranh nhân dân, cả nước dồn sức cho tiền tuyến', 'Ta chỉ dựa vào phương tiện cơ giới hiện đại để tiếp tế', 'Chiến dịch Điện Biên Phủ không cần tới hậu phương', 'Dân công là lực lượng chiến đấu chủ yếu trên chiến trường'], 0, null, '[{"note":"Đúng. Hàng chục vạn dân công, hàng vạn xe đạp thồ vận chuyển lương thực, đạn dược — hậu phương dồn sức cho tiền tuyến, thể hiện sức mạnh của chiến tranh nhân dân.","section_id":"muc-3"},{"note":"Ngược lại: phương tiện thô sơ (xe đạp thồ, gánh, thuyền…) giữ vai trò chủ yếu, thể hiện sức mạnh của nhân dân.","section_id":"muc-3","trap":"ban_chat"},{"note":"Hậu phương giữ vai trò rất quan trọng: không có tiếp tế thì không thể đánh dài ngày ở vùng núi xa xôi.","section_id":"muc-4","trap":"ban_chat"},{"note":"Đánh tráo chủ thể: bộ đội chủ lực trực tiếp chiến đấu; dân công làm nhiệm vụ vận chuyển, phục vụ chiến dịch.","section_id":"muc-3","trap":"chu_the"}]'::jsonb, 'Câu nhận xét: vai trò của nhân dân và hậu phương trong chiến dịch Điện Biên Phủ.', 'Điện Biên Phủ là thắng lợi của chiến tranh nhân dân: cả nước dồn sức cho tiền tuyến.', 12, '7-khang-chien-chong-phap', 'muc-3', null, 'van_dung', 'van_dung_kien_thuc', (select id from public.historical_events where slug = 'chien-dich-dien-bien-phu'), 'SGK Lịch sử 12 (KNTT), Bài 7, mục 3')
