update public.exam_items set content_key = 'b7-m3-tn-05'
 where content_key is null and fingerprint = public.exam_item_fingerprint('mcq', 'Theo đoạn tư liệu, cuộc tiến công chiến lược Đông – Xuân 1953 – 1954 của quân ta đã', array['đập tan hoàn toàn kế hoạch Na-va', 'buộc Pháp kí ngay Hiệp định Giơ-ne-vơ', 'giải phóng hoàn toàn miền Bắc Việt Nam', 'bước đầu làm phá sản kế hoạch Na-va'], null)
   and not exists (select 1 from public.exam_items where content_key = 'b7-m3-tn-05');
insert into public.exam_items (content_key, kind, stem, passage_id, choices, correct_index, statements, choice_notes, explanation, remember, grade, lesson_slug, section_id, topic_tag, level, competency, event_id, source_note)
values ('b7-m3-tn-05', 'mcq', 'Theo đoạn tư liệu, cuộc tiến công chiến lược Đông – Xuân 1953 – 1954 của quân ta đã', (select id from public.exam_passages where title = 'Kế hoạch Na-va và chiến dịch Điện Biên Phủ (1953 – 1954)' and body = 'Năm 1953, với sự giúp đỡ của Mỹ, Pháp đề ra kế hoạch Na-va, hi vọng trong vòng 18 tháng giành thắng lợi quân sự quyết định để “kết thúc chiến tranh trong danh dự”. Trong Đông – Xuân 1953 – 1954, quân ta mở nhiều cuộc tiến công trên các hướng Tây Bắc, Trung Lào, Hạ Lào, Bắc Tây Nguyên và Thượng Lào, buộc địch phải phân tán lực lượng để đối phó; kế hoạch Na-va bước đầu bị phá sản.
Pháp xây dựng Điện Biên Phủ thành tập đoàn cứ điểm mạnh nhất Đông Dương, gồm 49 cứ điểm chia thành ba phân khu: Bắc, Trung tâm và Nam. Ta quyết định mở chiến dịch Điện Biên Phủ; phương châm tác chiến được chuyển từ “đánh nhanh, giải quyết nhanh” sang “đánh chắc, tiến chắc”. Chiến dịch diễn ra từ ngày 13-3 đến ngày 7-5-1954, qua ba đợt: đợt 1 tiêu diệt cụm cứ điểm Him Lam và phân khu Bắc; đợt 2 tiến công các cứ điểm phía đông phân khu Trung tâm; đợt 3 tổng công kích. Chiều 7-5-1954, tướng Đờ Ca-xtơ-ri cùng toàn bộ Bộ chỉ huy tập đoàn cứ điểm bị bắt sống.' order by created_at limit 1), array['đập tan hoàn toàn kế hoạch Na-va', 'buộc Pháp kí ngay Hiệp định Giơ-ne-vơ', 'giải phóng hoàn toàn miền Bắc Việt Nam', 'bước đầu làm phá sản kế hoạch Na-va'], 3, null, '[{"note":"Tuyệt đối hóa: Đông – Xuân mới làm phá sản BƯỚC ĐẦU; chiến thắng Điện Biên Phủ mới đập tan hoàn toàn kế hoạch Na-va.","section_id":"muc-3","trap":"tuyet_doi"},{"note":"Hiệp định Giơ-ne-vơ là kết quả trực tiếp của chiến thắng Điện Biên Phủ (7-5-1954), không phải của riêng cuộc tiến công Đông – Xuân.","section_id":"muc-3","trap":"nhan_qua"},{"note":"Miền Bắc chỉ được hoàn toàn giải phóng sau Hiệp định Giơ-ne-vơ (1954).","section_id":"muc-4","trap":"thoi_gian"},{"note":"Đúng. Các cuộc tiến công trên nhiều hướng buộc địch phải phân tán lực lượng — kế hoạch Na-va bước đầu bị phá sản.","section_id":"muc-3"}]'::jsonb, 'Phân biệt hai mức: Đông – Xuân (bước đầu) và Điện Biên Phủ (hoàn toàn).', 'Đông – Xuân 1953 – 1954: bước đầu làm phá sản kế hoạch Na-va; Điện Biên Phủ: đập tan hoàn toàn.', 12, '7-khang-chien-chong-phap', 'muc-3', null, 'thong_hieu', 'nhan_thuc_tu_duy', null, 'SGK Lịch sử 12 (KNTT), Bài 7, mục 3')
