 where content_key is null and fingerprint = public.exam_item_fingerprint('mcq', 'Theo đoạn tư liệu, trong đợt tiến công thứ hai của chiến dịch Điện Biên Phủ, quân ta tập trung tiến công', array['các cứ điểm phía đông phân khu Trung tâm', 'cụm cứ điểm Him Lam và phân khu Bắc', 'toàn bộ phân khu Nam (Hồng Cúm)', 'toàn bộ phân khu Trung tâm, bắt sống Đờ Ca-xtơ-ri'], null)
