values ('b7-m3-tn-06', 'mcq', 'Theo đoạn tư liệu, trong đợt tiến công thứ hai của chiến dịch Điện Biên Phủ, quân ta tập trung tiến công', (select id from public.exam_passages where title = 'Kế hoạch Na-va và chiến dịch Điện Biên Phủ (1953 – 1954)' and body = 'Năm 1953, với sự giúp đỡ của Mỹ, Pháp đề ra kế hoạch Na-va, hi vọng trong vòng 18 tháng giành thắng lợi quân sự quyết định để “kết thúc chiến tranh trong danh dự”. Trong Đông – Xuân 1953 – 1954, quân ta mở nhiều cuộc tiến công trên các hướng Tây Bắc, Trung Lào, Hạ Lào, Bắc Tây Nguyên và Thượng Lào, buộc địch phải phân tán lực lượng để đối phó; kế hoạch Na-va bước đầu bị phá sản.
Pháp xây dựng Điện Biên Phủ thành tập đoàn cứ điểm mạnh nhất Đông Dương, gồm 49 cứ điểm chia thành ba phân khu: Bắc, Trung tâm và Nam. Ta quyết định mở chiến dịch Điện Biên Phủ; phương châm tác chiến được chuyển từ “đánh nhanh, giải quyết nhanh” sang “đánh chắc, tiến chắc”. Chiến dịch diễn ra từ ngày 13-3 đến ngày 7-5-1954, qua ba đợt: đợt 1 tiêu diệt cụm cứ điểm Him Lam và phân khu Bắc; đợt 2 tiến công các cứ điểm phía đông phân khu Trung tâm; đợt 3 tổng công kích. Chiều 7-5-1954, tướng Đờ Ca-xtơ-ri cùng toàn bộ Bộ chỉ huy tập đoàn cứ điểm bị bắt sống.' order by created_at limit 1), array['các cứ điểm phía đông phân khu Trung tâm', 'cụm cứ điểm Him Lam và phân khu Bắc', 'toàn bộ phân khu Nam (Hồng Cúm)', 'toàn bộ phân khu Trung tâm, bắt sống Đờ Ca-xtơ-ri'], 0, null, '[{"note":"Đúng. Đợt 2, quân ta tiến công các cứ điểm phía đông phân khu Trung tâm, chiếm E1, D1, C1…, siết chặt vòng vây; đồi A1 giằng co quyết liệt, đến đợt 3 mới bị tiêu diệt.","section_id":"muc-3"},{"note":"Him Lam và phân khu Bắc bị tiêu diệt trong đợt 1.","section_id":"muc-3","trap":"thoi_gian"},{"note":"Phân khu Nam (Hồng Cúm) bị tiêu diệt khi chiến dịch kết thúc (7-5-1954), trong đợt tổng công kích.","section_id":"muc-3","trap":"thoi_gian"},{"note":"Đây là kết quả của đợt 3 (tổng công kích), kết thúc ngày 7-5-1954.","section_id":"muc-3","trap":"thoi_gian"}]'::jsonb, 'Ba đợt của chiến dịch Điện Biên Phủ: phân khu Bắc → phía đông phân khu Trung tâm → tổng công kích.', 'Đợt 1: Him Lam, phân khu Bắc · Đợt 2: phía đông phân khu Trung tâm · Đợt 3: tổng công kích.', 12, '7-khang-chien-chong-phap', 'muc-3', null, 'nhan_biet', 'tim_hieu_lich_su', null, 'SGK Lịch sử 12 (KNTT), Bài 7, mục 3')
