insert into public.exam_items (content_key, kind, stem, passage_id, choices, correct_index, statements, choice_notes, explanation, remember, grade, lesson_slug, section_id, topic_tag, level, competency, event_id, source_note)
values ('b7-m3-tn-07', 'mcq', 'Việc chuyển phương châm tác chiến từ “đánh nhanh, giải quyết nhanh” sang “đánh chắc, tiến chắc” ở Điện Biên Phủ thể hiện', (select id from public.exam_passages where title = 'Kế hoạch Na-va và chiến dịch Điện Biên Phủ (1953 – 1954)' and body = 'Năm 1953, với sự giúp đỡ của Mỹ, Pháp đề ra kế hoạch Na-va, hi vọng trong vòng 18 tháng giành thắng lợi quân sự quyết định để “kết thúc chiến tranh trong danh dự”. Trong Đông – Xuân 1953 – 1954, quân ta mở nhiều cuộc tiến công trên các hướng Tây Bắc, Trung Lào, Hạ Lào, Bắc Tây Nguyên và Thượng Lào, buộc địch phải phân tán lực lượng để đối phó; kế hoạch Na-va bước đầu bị phá sản.
Pháp xây dựng Điện Biên Phủ thành tập đoàn cứ điểm mạnh nhất Đông Dương, gồm 49 cứ điểm chia thành ba phân khu: Bắc, Trung tâm và Nam. Ta quyết định mở chiến dịch Điện Biên Phủ; phương châm tác chiến được chuyển từ “đánh nhanh, giải quyết nhanh” sang “đánh chắc, tiến chắc”. Chiến dịch diễn ra từ ngày 13-3 đến ngày 7-5-1954, qua ba đợt: đợt 1 tiêu diệt cụm cứ điểm Him Lam và phân khu Bắc; đợt 2 tiến công các cứ điểm phía đông phân khu Trung tâm; đợt 3 tổng công kích. Chiều 7-5-1954, tướng Đờ Ca-xtơ-ri cùng toàn bộ Bộ chỉ huy tập đoàn cứ điểm bị bắt sống.' order by created_at limit 1), array['sự chỉ đạo sáng suốt, linh hoạt, xuất phát từ thực tế chiến trường', 'ta muốn kéo dài chiến tranh để chờ thêm viện trợ', 'ta bị động trước kế hoạch của quân Pháp', 'ta từ bỏ ý định tiến công tập đoàn cứ điểm'], 0, null, '[{"note":"Đúng. Thấy địch đã củng cố mạnh, đánh nhanh khó chắc thắng, Bộ chỉ huy chiến dịch do Đại tướng Võ Nguyên Giáp đứng đầu quyết định chuyển sang “đánh chắc, tiến chắc” — góp phần quyết định thắng lợi.","section_id":"muc-3"},{"note":"Hiểu sai: “đánh chắc, tiến chắc” là để bảo đảm chắc thắng, không phải để chờ viện trợ.","section_id":"muc-3","trap":"ban_chat"},{"note":"Ta chủ động chọn cách đánh phù hợp, không bị động.","section_id":"muc-3","trap":"ban_chat"},{"note":"Ta vẫn quyết tâm tiêu diệt tập đoàn cứ điểm, chỉ thay đổi cách đánh: tiến công từng bước, tiêu diệt từng cứ điểm.","section_id":"muc-3","trap":"ban_chat"}]'::jsonb, 'Câu đánh giá một quyết định chỉ đạo quan trọng của chiến dịch.', 'Điện Biên Phủ: chuyển từ “đánh nhanh, giải quyết nhanh” sang “đánh chắc, tiến chắc”.', 12, '7-khang-chien-chong-phap', 'muc-3', null, 'van_dung', 'nhan_thuc_tu_duy', null, 'SGK Lịch sử 12 (KNTT), Bài 7, mục 3')
