update public.exam_items set content_key = 'b7-m3-tn-08'
 where content_key is null and fingerprint = public.exam_item_fingerprint('mcq', 'Theo đoạn tư liệu, điểm nào cho thấy thắng lợi của Việt Nam tại Hội nghị Giơ-ne-vơ chưa trọn vẹn?', array['Các nước cam kết tôn trọng các quyền dân tộc cơ bản của Việt Nam', 'Chiến tranh ở Đông Dương được chấm dứt, hòa bình được lập lại', 'Đất nước tạm chia cắt ở vĩ tuyến 17, chờ tổng tuyển cử thống nhất', 'Hội nghị bàn về Đông Dương ngay sau chiến thắng Điện Biên Phủ'], null)
   and not exists (select 1 from public.exam_items where content_key = 'b7-m3-tn-08');
insert into public.exam_items (content_key, kind, stem, passage_id, choices, correct_index, statements, choice_notes, explanation, remember, grade, lesson_slug, section_id, topic_tag, level, competency, event_id, source_note)
values ('b7-m3-tn-08', 'mcq', 'Theo đoạn tư liệu, điểm nào cho thấy thắng lợi của Việt Nam tại Hội nghị Giơ-ne-vơ chưa trọn vẹn?', (select id from public.exam_passages where title = 'Hiệp định Giơ-ne-vơ về Đông Dương (1954)' and body = 'Ngày 8-5-1954, một ngày sau chiến thắng Điện Biên Phủ, Hội nghị Giơ-ne-vơ bắt đầu thảo luận về vấn đề Đông Dương. Ngày 21-7-1954, Hiệp định Giơ-ne-vơ về chấm dứt chiến tranh, lập lại hòa bình ở Đông Dương được kí kết. Các nước tham dự hội nghị cam kết tôn trọng các quyền dân tộc cơ bản là độc lập, chủ quyền, thống nhất và toàn vẹn lãnh thổ của ba nước Việt Nam, Lào, Cam-pu-chia. Ở Việt Nam, vĩ tuyến 17 (dọc theo sông Bến Hải, Quảng Trị) được lấy làm giới tuyến quân sự tạm thời; quân đội hai bên tập kết về hai miền; tổng tuyển cử tự do thống nhất đất nước sẽ được tổ chức vào tháng 7-1956.' order by created_at limit 1), array['Các nước cam kết tôn trọng các quyền dân tộc cơ bản của Việt Nam', 'Chiến tranh ở Đông Dương được chấm dứt, hòa bình được lập lại', 'Đất nước tạm chia cắt ở vĩ tuyến 17, chờ tổng tuyển cử thống nhất', 'Hội nghị bàn về Đông Dương ngay sau chiến thắng Điện Biên Phủ'], 2, null, '[{"note":"Đây là thắng lợi lớn: các nước tham dự cam kết tôn trọng độc lập, chủ quyền, thống nhất, toàn vẹn lãnh thổ của ba nước Đông Dương.","section_id":"muc-3","trap":"ban_chat"},{"note":"Chấm dứt chiến tranh, lập lại hòa bình là thắng lợi, không phải hạn chế.","section_id":"muc-3","trap":"ban_chat"},{"note":"Đúng. Chỉ miền Bắc được giải phóng; Mỹ và chính quyền Sài Gòn phá hoại tổng tuyển cử nên đất nước bị chia cắt, miền Nam còn phải đấu tranh đến năm 1975.","lesson_slug":"8-khang-chien-chong-my-cuu-nuoc","section_id":"muc-1"},{"note":"Đây là bối cảnh thuận lợi cho ta trên bàn đàm phán, không phải hạn chế của hiệp định.","section_id":"muc-3","trap":"ban_chat"}]'::jsonb, 'Câu đánh giá: nhận ra cả thắng lợi và hạn chế của Hiệp định Giơ-ne-vơ.', 'Giơ-ne-vơ 1954: thắng lợi lớn nhưng chưa trọn vẹn — miền Bắc giải phóng, đất nước tạm chia cắt.', 12, '7-khang-chien-chong-phap', 'muc-3', null, 'van_dung', 'nhan_thuc_tu_duy', (select id from public.historical_events where slug = 'hiep-dinh-geneve-ve-dong-duong'), 'SGK Lịch sử 12 (KNTT), Bài 7, mục 3')
