update public.exam_items set content_key = 'b7-m3-tn-09'
 where content_key is null and fingerprint = public.exam_item_fingerprint('mcq', 'Theo đoạn tư liệu, việc các nước tham dự hội nghị cam kết tôn trọng các quyền dân tộc cơ bản của ba nước Đông Dương có ý nghĩa gì?', array['Khẳng định Việt Nam đã thống nhất ngay sau năm 1954', 'Là cơ sở pháp lí quốc tế cho cuộc đấu tranh thống nhất đất nước sau này', 'Chấm dứt mọi sự can thiệp của các nước lớn vào Đông Dương', 'Đặt Lào và Cam-pu-chia dưới sự bảo hộ của Việt Nam'], null)
   and not exists (select 1 from public.exam_items where content_key = 'b7-m3-tn-09');
insert into public.exam_items (content_key, kind, stem, passage_id, choices, correct_index, statements, choice_notes, explanation, remember, grade, lesson_slug, section_id, topic_tag, level, competency, event_id, source_note)
values ('b7-m3-tn-09', 'mcq', 'Theo đoạn tư liệu, việc các nước tham dự hội nghị cam kết tôn trọng các quyền dân tộc cơ bản của ba nước Đông Dương có ý nghĩa gì?', (select id from public.exam_passages where title = 'Hiệp định Giơ-ne-vơ về Đông Dương (1954)' and body = 'Ngày 8-5-1954, một ngày sau chiến thắng Điện Biên Phủ, Hội nghị Giơ-ne-vơ bắt đầu thảo luận về vấn đề Đông Dương. Ngày 21-7-1954, Hiệp định Giơ-ne-vơ về chấm dứt chiến tranh, lập lại hòa bình ở Đông Dương được kí kết. Các nước tham dự hội nghị cam kết tôn trọng các quyền dân tộc cơ bản là độc lập, chủ quyền, thống nhất và toàn vẹn lãnh thổ của ba nước Việt Nam, Lào, Cam-pu-chia. Ở Việt Nam, vĩ tuyến 17 (dọc theo sông Bến Hải, Quảng Trị) được lấy làm giới tuyến quân sự tạm thời; quân đội hai bên tập kết về hai miền; tổng tuyển cử tự do thống nhất đất nước sẽ được tổ chức vào tháng 7-1956.' order by created_at limit 1), array['Khẳng định Việt Nam đã thống nhất ngay sau năm 1954', 'Là cơ sở pháp lí quốc tế cho cuộc đấu tranh thống nhất đất nước sau này', 'Chấm dứt mọi sự can thiệp của các nước lớn vào Đông Dương', 'Đặt Lào và Cam-pu-chia dưới sự bảo hộ của Việt Nam'], 1, null, '[{"note":"Sai thời gian: sau năm 1954 đất nước tạm chia cắt ở vĩ tuyến 17; thống nhất phải đợi đến năm 1975 – 1976.","lesson_slug":"8-khang-chien-chong-my-cuu-nuoc","section_id":"muc-1","trap":"thoi_gian"},{"note":"Đúng. Lần đầu các nước lớn cam kết tôn trọng độc lập, chủ quyền, thống nhất, toàn vẹn lãnh thổ của Việt Nam — cơ sở pháp lí để nhân dân Việt Nam đấu tranh đòi thống nhất (Hiệp định Pa-ri 1973 cũng nhắc lại điều này).","section_id":"muc-3"},{"note":"Tuyệt đối hóa: ngay sau năm 1954, Mỹ thay chân Pháp can thiệp vào miền Nam Việt Nam.","lesson_slug":"8-khang-chien-chong-my-cuu-nuoc","section_id":"muc-1","trap":"tuyet_doi"},{"note":"Hiểu sai: hiệp định khẳng định quyền độc lập, chủ quyền của cả ba nước, không nước nào bảo hộ nước nào.","section_id":"muc-3","trap":"ban_chat"}]'::jsonb, 'Câu đánh giá ý nghĩa pháp lí của Hiệp định Giơ-ne-vơ đối với cuộc đấu tranh sau này.', 'Giơ-ne-vơ 1954: lần đầu các nước lớn cam kết tôn trọng các quyền dân tộc cơ bản của Việt Nam.', 12, '7-khang-chien-chong-phap', 'muc-3', null, 'thong_hieu', 'nhan_thuc_tu_duy', (select id from public.historical_events where slug = 'hiep-dinh-geneve-ve-dong-duong'), 'SGK Lịch sử 12 (KNTT), Bài 7, mục 3')
