 where content_key is null and fingerprint = public.exam_item_fingerprint('mcq', 'Vì sao thực dân Pháp chọn Điện Biên Phủ để xây dựng tập đoàn cứ điểm mạnh nhất Đông Dương?', array['Là nơi đặt cơ quan đầu não kháng chiến của Việt Nam', 'Có vị trí chiến lược then chốt, có thể che chở cho Thượng Lào', 'Là vùng đông dân nhất Tây Bắc, dễ tuyển mộ binh lính', 'Gần biển, thuận tiện cho quân Pháp rút lui bằng tàu thủy'], null)
   and not exists (select 1 from public.exam_items where content_key = 'b7-m3-tn-10');
insert into public.exam_items (content_key, kind, stem, passage_id, choices, correct_index, statements, choice_notes, explanation, remember, grade, lesson_slug, section_id, topic_tag, level, competency, event_id, source_note)
values ('b7-m3-tn-10', 'mcq', 'Vì sao thực dân Pháp chọn Điện Biên Phủ để xây dựng tập đoàn cứ điểm mạnh nhất Đông Dương?', null, array['Là nơi đặt cơ quan đầu não kháng chiến của Việt Nam', 'Có vị trí chiến lược then chốt, có thể che chở cho Thượng Lào', 'Là vùng đông dân nhất Tây Bắc, dễ tuyển mộ binh lính', 'Gần biển, thuận tiện cho quân Pháp rút lui bằng tàu thủy'], 1, null, '[{"note":"Cơ quan đầu não kháng chiến đặt ở căn cứ địa Việt Bắc, không phải Điện Biên Phủ.","section_id":"muc-2","trap":"dia_diem"},{"note":"Đúng. Điện Biên Phủ ở Tây Bắc, có vị trí chiến lược then chốt ở Đông Dương; Pháp muốn giữ nơi đây để che chở Thượng Lào và làm bàn đạp tiến công.","section_id":"muc-3"},{"note":"Điện Biên Phủ là vùng núi thưa dân; Pháp chọn vì vị trí chiến lược, không vì dân cư.","section_id":"muc-3","trap":"ban_chat"},{"note":"Điện Biên Phủ nằm giữa vùng núi Tây Bắc, xa biển; quân Pháp ở đây tiếp tế chủ yếu bằng đường hàng không.","section_id":"muc-3","trap":"dia_diem"}]'::jsonb, 'Câu giải thích: vị trí chiến lược của Điện Biên Phủ đối với kế hoạch Na-va.', 'Điện Biên Phủ: vị trí chiến lược then chốt ở Tây Bắc, che chở Thượng Lào — trở thành “trung tâm” của kế hoạch Na-va.', 12, '7-khang-chien-chong-phap', 'muc-3', null, 'thong_hieu', 'nhan_thuc_tu_duy', (select id from public.historical_events where slug = 'chien-dich-dien-bien-phu'), 'SGK Lịch sử 12 (KNTT), Bài 7, mục 3')
