update public.exam_items set content_key = 'b7-m4-ds-01'
 where content_key is null and fingerprint = public.exam_item_fingerprint('true_false', 'Cho thông tin: “Năm 1954, cuộc kháng chiến chống thực dân Pháp của nhân dân Việt Nam kết thúc thắng lợi.” Mỗi ý sau đây đúng hay sai?', null, '[{"text":"Thắng lợi chấm dứt cuộc chiến tranh xâm lược và ách thống trị của thực dân Pháp trên đất nước ta.","is_true":true,"explanation":"Đây là ý nghĩa trong nước của thắng lợi.","section_id":"muc-4"},{"text":"Sau năm 1954, cả nước Việt Nam được giải phóng hoàn toàn.","is_true":false,"explanation":"Tuyệt đối hóa: chỉ miền Bắc được giải phóng; miền Nam còn dưới ách Mỹ và chính quyền Sài Gòn đến năm 1975.","lesson_slug":"8-khang-chien-chong-my-cuu-nuoc","section_id":"muc-1","trap":"tuyet_doi"},{"text":"Miền Bắc được giải phóng, chuyển sang giai đoạn cách mạng xã hội chủ nghĩa.","is_true":true,"explanation":"Miền Bắc trở thành hậu phương lớn cho cách mạng cả nước.","section_id":"muc-4"},{"text":"Cuộc kháng chiến thắng lợi mà không có sự ủng hộ nào của quốc tế.","is_true":false,"explanation":"Sai bản chất: ta nhận được sự giúp đỡ của Trung Quốc, Liên Xô, các nước dân chủ nhân dân và nhân dân tiến bộ thế giới.","section_id":"muc-4","trap":"ban_chat"}]'::jsonb)
   and not exists (select 1 from public.exam_items where content_key = 'b7-m4-ds-01');
insert into public.exam_items (content_key, kind, stem, passage_id, choices, correct_index, statements, choice_notes, explanation, remember, grade, lesson_slug, section_id, topic_tag, level, competency, event_id, source_note)
values ('b7-m4-ds-01', 'true_false', 'Cho thông tin: “Năm 1954, cuộc kháng chiến chống thực dân Pháp của nhân dân Việt Nam kết thúc thắng lợi.” Mỗi ý sau đây đúng hay sai?', null, null, null, '[{"text":"Thắng lợi chấm dứt cuộc chiến tranh xâm lược và ách thống trị của thực dân Pháp trên đất nước ta.","is_true":true,"explanation":"Đây là ý nghĩa trong nước của thắng lợi.","section_id":"muc-4"},{"text":"Sau năm 1954, cả nước Việt Nam được giải phóng hoàn toàn.","is_true":false,"explanation":"Tuyệt đối hóa: chỉ miền Bắc được giải phóng; miền Nam còn dưới ách Mỹ và chính quyền Sài Gòn đến năm 1975.","lesson_slug":"8-khang-chien-chong-my-cuu-nuoc","section_id":"muc-1","trap":"tuyet_doi"},{"text":"Miền Bắc được giải phóng, chuyển sang giai đoạn cách mạng xã hội chủ nghĩa.","is_true":true,"explanation":"Miền Bắc trở thành hậu phương lớn cho cách mạng cả nước.","section_id":"muc-4"},{"text":"Cuộc kháng chiến thắng lợi mà không có sự ủng hộ nào của quốc tế.","is_true":false,"explanation":"Sai bản chất: ta nhận được sự giúp đỡ của Trung Quốc, Liên Xô, các nước dân chủ nhân dân và nhân dân tiến bộ thế giới.","section_id":"muc-4","trap":"ban_chat"}]'::jsonb, null, 'Câu nhận biết ý nghĩa và nguyên nhân thắng lợi của kháng chiến chống Pháp.', '1954: chấm dứt ách thống trị của Pháp; miền Bắc giải phóng, đi lên chủ nghĩa xã hội.', 12, '7-khang-chien-chong-phap', 'muc-4', null, 'nhan_biet', 'tim_hieu_lich_su', null, 'SGK Lịch sử 12 (KNTT), Bài 7, mục 4')
