update public.exam_items set content_key = 'b7-m4-ds-02'
 where content_key is null and fingerprint = public.exam_item_fingerprint('true_false', 'Dựa vào tư liệu tóm lược nguyên nhân và ý nghĩa thắng lợi của kháng chiến chống Pháp (1945 – 1954), hãy xác định tính đúng, sai của từng ý.', null, '[{"text":"Sự lãnh đạo của Đảng với đường lối kháng chiến đúng đắn là một nguyên nhân thắng lợi.","is_true":true,"explanation":"Tư liệu nêu nguyên nhân này đầu tiên.","section_id":"muc-4"},{"text":"Thắng lợi tạo cơ sở để nhân dân Việt Nam tiếp tục đấu tranh giải phóng miền Nam, thống nhất đất nước.","is_true":true,"explanation":"Tư liệu: thắng lợi “tạo cơ sở để giải phóng miền Nam, thống nhất đất nước”.","section_id":"muc-4"},{"text":"Theo tư liệu, thắng lợi chủ yếu nhờ viện trợ của nước ngoài.","is_true":false,"explanation":"Đánh tráo vai trò: tư liệu nêu sự giúp đỡ quốc tế “bên cạnh” các nguyên nhân bên trong — đó là nguyên nhân khách quan, hỗ trợ.","section_id":"muc-4","trap":"nhan_qua"},{"text":"Bài học kết hợp sức mạnh dân tộc với sức mạnh thời đại không còn giá trị trong bảo vệ chủ quyền biển, đảo hiện nay.","is_true":false,"explanation":"Hiểu sai: bảo vệ chủ quyền hiện nay vẫn cần phát huy sức mạnh toàn dân, kết hợp tranh thủ sự ủng hộ của cộng đồng quốc tế.","section_id":"muc-4","trap":"ban_chat"}]'::jsonb)
   and not exists (select 1 from public.exam_items where content_key = 'b7-m4-ds-02');
insert into public.exam_items (content_key, kind, stem, passage_id, choices, correct_index, statements, choice_notes, explanation, remember, grade, lesson_slug, section_id, topic_tag, level, competency, event_id, source_note)
values ('b7-m4-ds-02', 'true_false', 'Dựa vào tư liệu tóm lược nguyên nhân và ý nghĩa thắng lợi của kháng chiến chống Pháp (1945 – 1954), hãy xác định tính đúng, sai của từng ý.', (select id from public.exam_passages where title = 'Nguyên nhân thắng lợi và ý nghĩa của cuộc kháng chiến chống thực dân Pháp' and body = 'Cuộc kháng chiến chống thực dân Pháp thắng lợi nhờ sự lãnh đạo sáng suốt của Đảng, đứng đầu là Chủ tịch Hồ Chí Minh, với đường lối kháng chiến toàn dân, toàn diện, trường kì, tự lực cánh sinh. Cuộc kháng chiến có hậu phương rộng lớn, vững chắc; khối đoàn kết toàn dân được củng cố; lực lượng vũ trang ba thứ quân không ngừng lớn mạnh. Bên cạnh đó là liên minh chiến đấu của ba dân tộc Việt Nam, Lào, Cam-pu-chia và sự đồng tình, giúp đỡ của Trung Quốc, Liên Xô, các nước dân chủ nhân dân, nhân dân Pháp và nhân dân tiến bộ trên thế giới.
Thắng lợi đã chấm dứt cuộc chiến tranh xâm lược và ách thống trị của thực dân Pháp trên đất nước ta; miền Bắc được hoàn toàn giải phóng, chuyển sang giai đoạn cách mạng xã hội chủ nghĩa, tạo cơ sở để giải phóng miền Nam, thống nhất đất nước. Thắng lợi cũng giáng đòn nặng nề vào tham vọng xâm lược của chủ nghĩa đế quốc, góp phần làm tan rã hệ thống thuộc địa, cổ vũ phong trào giải phóng dân tộc trên thế giới.' order by created_at limit 1), null, null, '[{"text":"Sự lãnh đạo của Đảng với đường lối kháng chiến đúng đắn là một nguyên nhân thắng lợi.","is_true":true,"explanation":"Tư liệu nêu nguyên nhân này đầu tiên.","section_id":"muc-4"},{"text":"Thắng lợi tạo cơ sở để nhân dân Việt Nam tiếp tục đấu tranh giải phóng miền Nam, thống nhất đất nước.","is_true":true,"explanation":"Tư liệu: thắng lợi “tạo cơ sở để giải phóng miền Nam, thống nhất đất nước”.","section_id":"muc-4"},{"text":"Theo tư liệu, thắng lợi chủ yếu nhờ viện trợ của nước ngoài.","is_true":false,"explanation":"Đánh tráo vai trò: tư liệu nêu sự giúp đỡ quốc tế “bên cạnh” các nguyên nhân bên trong — đó là nguyên nhân khách quan, hỗ trợ.","section_id":"muc-4","trap":"nhan_qua"},{"text":"Bài học kết hợp sức mạnh dân tộc với sức mạnh thời đại không còn giá trị trong bảo vệ chủ quyền biển, đảo hiện nay.","is_true":false,"explanation":"Hiểu sai: bảo vệ chủ quyền hiện nay vẫn cần phát huy sức mạnh toàn dân, kết hợp tranh thủ sự ủng hộ của cộng đồng quốc tế.","section_id":"muc-4","trap":"ban_chat"}]'::jsonb, null, 'Câu đọc hiểu và vận dụng: nguyên nhân, ý nghĩa, bài học của kháng chiến chống Pháp.', 'Thắng lợi 1954: nguyên nhân chủ quan quyết định, quốc tế hỗ trợ; bài học kết hợp sức mạnh dân tộc với sức mạnh thời đại.', 12, '7-khang-chien-chong-phap', 'muc-4', null, 'van_dung', 'van_dung_kien_thuc', null, 'SGK Lịch sử 12 (KNTT), Bài 7, mục 4')
