values ('b7-m4-tn-02', 'mcq', 'Lực lượng vũ trang “ba thứ quân” được xây dựng trong cuộc kháng chiến chống thực dân Pháp gồm', null, array['chỉ có các đơn vị bộ đội chủ lực chính quy', 'lục quân, hải quân, không quân và phòng không', 'bộ đội chủ lực, bộ đội địa phương và dân quân du kích', 'bộ đội chủ lực, dân quân du kích và tự vệ thành'], 2, null, '[{"note":"Tuyệt đối hóa: ngoài bộ đội chủ lực còn có bộ đội địa phương và dân quân du kích.","section_id":"muc-4","trap":"tuyet_doi"},{"note":"Nhầm khái niệm: đây là các quân chủng, binh chủng, không phải “ba thứ quân” trong kháng chiến chống Pháp.","section_id":"muc-4","trap":"khai_niem"},{"note":"Đúng. Ba thứ quân: bộ đội chủ lực, bộ đội địa phương và dân quân du kích — nền tảng của chiến tranh nhân dân.","section_id":"muc-4"},{"note":"Thiếu một thứ quân: “ba thứ quân” gồm bộ đội chủ lực, bộ đội địa phương và dân quân du kích; tự vệ là một bộ phận của dân quân, không phải thứ quân riêng.","section_id":"muc-4","trap":"khai_niem"}]'::jsonb, 'Ba thứ quân là đặc điểm của chiến tranh nhân dân Việt Nam.', 'Ba thứ quân: bộ đội chủ lực, bộ đội địa phương, dân quân du kích.', 12, '7-khang-chien-chong-phap', 'muc-4', null, 'nhan_biet', 'tim_hieu_lich_su', null, 'SGK Lịch sử 12 (KNTT), Bài 7, mục 4')
