values ('b7-m4-tn-04', 'mcq', 'Theo đoạn tư liệu, yếu tố nào sau đây là nguyên nhân khách quan góp phần vào thắng lợi của cuộc kháng chiến chống Pháp?', (select id from public.exam_passages where title = 'Nguyên nhân thắng lợi và ý nghĩa của cuộc kháng chiến chống thực dân Pháp' and body = 'Cuộc kháng chiến chống thực dân Pháp thắng lợi nhờ sự lãnh đạo sáng suốt của Đảng, đứng đầu là Chủ tịch Hồ Chí Minh, với đường lối kháng chiến toàn dân, toàn diện, trường kì, tự lực cánh sinh. Cuộc kháng chiến có hậu phương rộng lớn, vững chắc; khối đoàn kết toàn dân được củng cố; lực lượng vũ trang ba thứ quân không ngừng lớn mạnh. Bên cạnh đó là liên minh chiến đấu của ba dân tộc Việt Nam, Lào, Cam-pu-chia và sự đồng tình, giúp đỡ của Trung Quốc, Liên Xô, các nước dân chủ nhân dân, nhân dân Pháp và nhân dân tiến bộ trên thế giới.
Thắng lợi đã chấm dứt cuộc chiến tranh xâm lược và ách thống trị của thực dân Pháp trên đất nước ta; miền Bắc được hoàn toàn giải phóng, chuyển sang giai đoạn cách mạng xã hội chủ nghĩa, tạo cơ sở để giải phóng miền Nam, thống nhất đất nước. Thắng lợi cũng giáng đòn nặng nề vào tham vọng xâm lược của chủ nghĩa đế quốc, góp phần làm tan rã hệ thống thuộc địa, cổ vũ phong trào giải phóng dân tộc trên thế giới.' order by created_at limit 1), array['Đường lối kháng chiến toàn dân, toàn diện, trường kì', 'Hậu phương kháng chiến rộng lớn, vững chắc', 'Liên minh ba nước Đông Dương và sự giúp đỡ quốc tế', 'Lực lượng vũ trang ba thứ quân không ngừng lớn mạnh'], 2, null, '[{"note":"Nhầm khái niệm: đường lối kháng chiến là nguyên nhân chủ quan (sự lãnh đạo của Đảng).","section_id":"muc-4","trap":"khai_niem"},{"note":"Nhầm khái niệm: hậu phương là nguyên nhân chủ quan (sức mạnh bên trong).","section_id":"muc-4","trap":"khai_niem"},{"note":"Đúng. Liên minh chiến đấu của ba dân tộc Đông Dương và sự giúp đỡ của Trung Quốc, Liên Xô, nhân dân tiến bộ thế giới là điều kiện bên ngoài.","section_id":"muc-4"},{"note":"Nhầm khái niệm: lực lượng vũ trang là nguyên nhân chủ quan.","section_id":"muc-4","trap":"khai_niem"}]'::jsonb, 'Phân loại nguyên nhân: bên trong (chủ quan) và bên ngoài (khách quan).', 'Khách quan: liên minh ba nước Đông Dương, sự giúp đỡ của Trung Quốc, Liên Xô và nhân dân tiến bộ.', 12, '7-khang-chien-chong-phap', 'muc-4', null, 'thong_hieu', 'nhan_thuc_tu_duy', null, 'SGK Lịch sử 12 (KNTT), Bài 7, mục 4')
