values ('b7-m4-tn-05', 'mcq', 'Từ đoạn tư liệu, bài học nào có giá trị đối với sự nghiệp bảo vệ Tổ quốc hiện nay?', (select id from public.exam_passages where title = 'Nguyên nhân thắng lợi và ý nghĩa của cuộc kháng chiến chống thực dân Pháp' and body = 'Cuộc kháng chiến chống thực dân Pháp thắng lợi nhờ sự lãnh đạo sáng suốt của Đảng, đứng đầu là Chủ tịch Hồ Chí Minh, với đường lối kháng chiến toàn dân, toàn diện, trường kì, tự lực cánh sinh. Cuộc kháng chiến có hậu phương rộng lớn, vững chắc; khối đoàn kết toàn dân được củng cố; lực lượng vũ trang ba thứ quân không ngừng lớn mạnh. Bên cạnh đó là liên minh chiến đấu của ba dân tộc Việt Nam, Lào, Cam-pu-chia và sự đồng tình, giúp đỡ của Trung Quốc, Liên Xô, các nước dân chủ nhân dân, nhân dân Pháp và nhân dân tiến bộ trên thế giới.
Thắng lợi đã chấm dứt cuộc chiến tranh xâm lược và ách thống trị của thực dân Pháp trên đất nước ta; miền Bắc được hoàn toàn giải phóng, chuyển sang giai đoạn cách mạng xã hội chủ nghĩa, tạo cơ sở để giải phóng miền Nam, thống nhất đất nước. Thắng lợi cũng giáng đòn nặng nề vào tham vọng xâm lược của chủ nghĩa đế quốc, góp phần làm tan rã hệ thống thuộc địa, cổ vũ phong trào giải phóng dân tộc trên thế giới.' order by created_at limit 1), array['Ưu tiên tranh thủ viện trợ quốc tế hơn phát huy nội lực', 'Chủ yếu dựa vào sức mạnh của quân đội chính quy', 'Tập trung cho tiền tuyến, coi nhẹ xây dựng hậu phương', 'Phát huy sức mạnh toàn dân, kết hợp với sự ủng hộ quốc tế'], 3, null, '[{"note":"Đảo ngược vai trò: tư liệu nêu sự giúp đỡ quốc tế “bên cạnh” các nguyên nhân bên trong — nội lực mới là quyết định.","section_id":"muc-4","trap":"nhan_qua"},{"note":"Tuyệt đối hóa: tư liệu nêu lực lượng vũ trang “ba thứ quân” cùng hậu phương và khối đoàn kết toàn dân, không chỉ quân đội chính quy.","section_id":"muc-4","trap":"tuyet_doi"},{"note":"Trái tư liệu: hậu phương rộng lớn, vững chắc là một nguyên nhân thắng lợi.","section_id":"muc-4","trap":"ban_chat"},{"note":"Đúng. Phát huy sức mạnh toàn dân (lãnh đạo, đoàn kết, hậu phương, lực lượng vũ trang) kết hợp với sự ủng hộ quốc tế — bài học vẫn có giá trị hiện nay.","section_id":"muc-4"}]'::jsonb, 'Câu vận dụng: rút bài học từ các nguyên nhân thắng lợi.', 'Bài học: kết hợp sức mạnh dân tộc với sức mạnh thời đại.', 12, '7-khang-chien-chong-phap', 'muc-4', null, 'van_dung', 'van_dung_kien_thuc', null, 'SGK Lịch sử 12 (KNTT), Bài 7, mục 4')
