insert into public.exam_items (content_key, kind, stem, passage_id, choices, correct_index, statements, choice_notes, explanation, remember, grade, lesson_slug, section_id, topic_tag, level, competency, event_id, source_note)
values ('b7-m4-tn-06', 'mcq', 'Hai câu thơ “Chín năm làm một Điện Biên / Nên vành hoa đỏ, nên thiên sử vàng” (Tố Hữu) phản ánh điều gì?', null, array['Điện Biên Phủ là trận đánh mở đầu cuộc kháng chiến', 'Chiến thắng là kết quả của cả quá trình kháng chiến lâu dài', 'Chiến dịch Điện Biên Phủ kéo dài liên tục suốt chín năm', 'Ta kháng chiến chín năm vì không chủ động tiến công'], 1, null, '[{"note":"Sai thời gian: Điện Biên Phủ (1954) là trận kết thúc; trước đó còn Việt Bắc 1947, Biên giới 1950, các chiến dịch 1951 – 1953 và cuộc tiến công Đông – Xuân.","section_id":"muc-3","trap":"thoi_gian"},{"note":"Đúng. “Chín năm” là cả cuộc kháng chiến (1945 – 1954); Điện Biên Phủ là đỉnh cao, kết tinh sức mạnh tích lũy suốt quá trình ấy.","section_id":"muc-4"},{"note":"Sai số liệu: chiến dịch Điện Biên Phủ kéo dài 56 ngày đêm (13-3 → 7-5-1954); “chín năm” là cả cuộc kháng chiến.","section_id":"muc-3","trap":"so_lieu"},{"note":"Hiểu sai: ta chủ động mở nhiều chiến dịch tiến công từ năm 1950; kháng chiến trường kì là để tích lũy lực lượng.","section_id":"muc-2","trap":"ban_chat"}]'::jsonb, 'Câu vận dụng: đọc hiểu một tư liệu văn học về cuộc kháng chiến.', '“Chín năm làm một Điện Biên” — Điện Biên Phủ là kết tinh của chín năm kháng chiến trường kì.', 12, '7-khang-chien-chong-phap', 'muc-4', null, 'van_dung', 'van_dung_kien_thuc', null, 'SGK Lịch sử 12 (KNTT), Bài 7, mục 4')
