-- ===== bai-08-khang-chien-chong-my.json =====
insert into public.exam_passages (title, body, source_citation, lesson_slug)
select 'Phong trào Đồng khởi (1959 – 1960)', 'Sau năm 1954, Mỹ và chính quyền Ngô Đình Diệm ra sức đàn áp phong trào cách mạng miền Nam, thi hành chính sách “tố cộng”, “diệt cộng”, ban hành “Luật 10-59” lê máy chém khắp miền Nam. Tháng 1-1959, Hội nghị lần thứ 15 Ban Chấp hành Trung ương Đảng quyết định để nhân dân miền Nam sử dụng bạo lực cách mạng, kết hợp đấu tranh chính trị với đấu tranh vũ trang để đánh đổ chính quyền Mỹ – Diệm.
Phong trào nổi dậy lan rộng khắp miền Nam, tiêu biểu là cuộc Đồng khởi ở Bến Tre (bắt đầu từ ngày 17-1-1960 ở huyện Mỏ Cày). Từ phong trào, ngày 20-12-1960, Mặt trận Dân tộc giải phóng miền Nam Việt Nam ra đời. Phong trào Đồng khởi giáng đòn nặng nề vào chính sách thực dân kiểu mới của Mỹ, làm lung lay chính quyền Ngô Đình Diệm, đánh dấu bước phát triển của cách mạng miền Nam từ thế giữ gìn lực lượng sang thế tiến công.', 'Tóm lược của biên tập viên theo SGK Lịch sử 12 (KNTT), Bài 8, mục 1', '8-khang-chien-chong-my-cuu-nuoc'
where not exists (select 1 from public.exam_passages where title = 'Phong trào Đồng khởi (1959 – 1960)' and body = 'Sau năm 1954, Mỹ và chính quyền Ngô Đình Diệm ra sức đàn áp phong trào cách mạng miền Nam, thi hành chính sách “tố cộng”, “diệt cộng”, ban hành “Luật 10-59” lê máy chém khắp miền Nam. Tháng 1-1959, Hội nghị lần thứ 15 Ban Chấp hành Trung ương Đảng quyết định để nhân dân miền Nam sử dụng bạo lực cách mạng, kết hợp đấu tranh chính trị với đấu tranh vũ trang để đánh đổ chính quyền Mỹ – Diệm.
Phong trào nổi dậy lan rộng khắp miền Nam, tiêu biểu là cuộc Đồng khởi ở Bến Tre (bắt đầu từ ngày 17-1-1960 ở huyện Mỏ Cày). Từ phong trào, ngày 20-12-1960, Mặt trận Dân tộc giải phóng miền Nam Việt Nam ra đời. Phong trào Đồng khởi giáng đòn nặng nề vào chính sách thực dân kiểu mới của Mỹ, làm lung lay chính quyền Ngô Đình Diệm, đánh dấu bước phát triển của cách mạng miền Nam từ thế giữ gìn lực lượng sang thế tiến công.');
insert into public.exam_passages (title, body, source_citation, lesson_slug)
select 'Chiến lược “Chiến tranh đặc biệt” (1961 – 1965)', 'Từ năm 1961, Mỹ tiến hành chiến lược “Chiến tranh đặc biệt” ở miền Nam. Lực lượng chủ yếu tiến hành chiến tranh là quân đội Sài Gòn, đặt dưới sự chỉ huy của hệ thống cố vấn Mỹ, dựa vào vũ khí, trang bị và phương tiện chiến tranh của Mỹ. Mỹ – chính quyền Sài Gòn đề ra kế hoạch dồn dân, lập “ấp chiến lược”, coi đó là “xương sống” của chiến lược nhằm tách dân khỏi cách mạng; sử dụng phổ biến các chiến thuật “trực thăng vận”, “thiết xa vận”.
Quân dân miền Nam vừa đấu tranh chống phá “ấp chiến lược”, vừa đánh bại các cuộc hành quân càn quét. Chiến thắng Ấp Bắc (Mỹ Tho, ngày 2-1-1963) chứng tỏ quân dân miền Nam có khả năng đánh bại chiến lược “Chiến tranh đặc biệt”. Trong Đông – Xuân 1964 – 1965, thắng lợi ở Bình Giã và nhiều nơi khác đã làm phá sản về cơ bản chiến lược này.', 'Tóm lược của biên tập viên theo SGK Lịch sử 12 (KNTT), Bài 8, mục 1', '8-khang-chien-chong-my-cuu-nuoc'
where not exists (select 1 from public.exam_passages where title = 'Chiến lược “Chiến tranh đặc biệt” (1961 – 1965)' and body = 'Từ năm 1961, Mỹ tiến hành chiến lược “Chiến tranh đặc biệt” ở miền Nam. Lực lượng chủ yếu tiến hành chiến tranh là quân đội Sài Gòn, đặt dưới sự chỉ huy của hệ thống cố vấn Mỹ, dựa vào vũ khí, trang bị và phương tiện chiến tranh của Mỹ. Mỹ – chính quyền Sài Gòn đề ra kế hoạch dồn dân, lập “ấp chiến lược”, coi đó là “xương sống” của chiến lược nhằm tách dân khỏi cách mạng; sử dụng phổ biến các chiến thuật “trực thăng vận”, “thiết xa vận”.
Quân dân miền Nam vừa đấu tranh chống phá “ấp chiến lược”, vừa đánh bại các cuộc hành quân càn quét. Chiến thắng Ấp Bắc (Mỹ Tho, ngày 2-1-1963) chứng tỏ quân dân miền Nam có khả năng đánh bại chiến lược “Chiến tranh đặc biệt”. Trong Đông – Xuân 1964 – 1965, thắng lợi ở Bình Giã và nhiều nơi khác đã làm phá sản về cơ bản chiến lược này.');
insert into public.exam_passages (title, body, source_citation, lesson_slug)
select 'Lời kêu gọi đồng bào và chiến sĩ cả nước (17-7-1966)', '“Chiến tranh có thể kéo dài 5 năm, 10 năm, 20 năm hoặc lâu hơn nữa. Hà Nội, Hải Phòng và một số thành phố, xí nghiệp có thể bị tàn phá, song nhân dân Việt Nam quyết không sợ! Không có gì quý hơn độc lập, tự do. Đến ngày thắng lợi, nhân dân ta sẽ xây dựng lại đất nước ta đàng hoàng hơn, to đẹp hơn!”', 'Hồ Chí Minh, Lời kêu gọi đồng bào và chiến sĩ cả nước, ngày 17-7-1966', '8-khang-chien-chong-my-cuu-nuoc'
where not exists (select 1 from public.exam_passages where title = 'Lời kêu gọi đồng bào và chiến sĩ cả nước (17-7-1966)' and body = '“Chiến tranh có thể kéo dài 5 năm, 10 năm, 20 năm hoặc lâu hơn nữa. Hà Nội, Hải Phòng và một số thành phố, xí nghiệp có thể bị tàn phá, song nhân dân Việt Nam quyết không sợ! Không có gì quý hơn độc lập, tự do. Đến ngày thắng lợi, nhân dân ta sẽ xây dựng lại đất nước ta đàng hoàng hơn, to đẹp hơn!”');
insert into public.exam_passages (title, body, source_citation, lesson_slug)
select 'Tổng tiến công và nổi dậy Tết Mậu Thân 1968', 'Đêm 30 rạng sáng ngày 31-1-1968 (Tết Mậu Thân), quân dân miền Nam đồng loạt tiến công và nổi dậy ở hầu khắp các đô thị miền Nam, đánh vào các cơ quan đầu não của Mỹ và chính quyền Sài Gòn. Ở Sài Gòn, các mục tiêu quan trọng như Tòa đại sứ Mỹ, Dinh Độc Lập, Bộ Tổng tham mưu quân đội Sài Gòn, sân bay Tân Sơn Nhất bị tiến công.
Cuộc Tổng tiến công và nổi dậy đã làm lung lay ý chí xâm lược của Mỹ, buộc Mỹ phải tuyên bố “phi Mỹ hóa” chiến tranh (tức là thừa nhận sự thất bại của chiến lược “Chiến tranh cục bộ”), chấm dứt ném bom miền Bắc và chấp nhận đến bàn đàm phán ở Pa-ri — mở ra bước ngoặt mới của cuộc kháng chiến.', 'Tóm lược của biên tập viên theo SGK Lịch sử 12 (KNTT), Bài 8, mục 2', '8-khang-chien-chong-my-cuu-nuoc'
where not exists (select 1 from public.exam_passages where title = 'Tổng tiến công và nổi dậy Tết Mậu Thân 1968' and body = 'Đêm 30 rạng sáng ngày 31-1-1968 (Tết Mậu Thân), quân dân miền Nam đồng loạt tiến công và nổi dậy ở hầu khắp các đô thị miền Nam, đánh vào các cơ quan đầu não của Mỹ và chính quyền Sài Gòn. Ở Sài Gòn, các mục tiêu quan trọng như Tòa đại sứ Mỹ, Dinh Độc Lập, Bộ Tổng tham mưu quân đội Sài Gòn, sân bay Tân Sơn Nhất bị tiến công.
Cuộc Tổng tiến công và nổi dậy đã làm lung lay ý chí xâm lược của Mỹ, buộc Mỹ phải tuyên bố “phi Mỹ hóa” chiến tranh (tức là thừa nhận sự thất bại của chiến lược “Chiến tranh cục bộ”), chấm dứt ném bom miền Bắc và chấp nhận đến bàn đàm phán ở Pa-ri — mở ra bước ngoặt mới của cuộc kháng chiến.');
insert into public.exam_passages (title, body, source_citation, lesson_slug)
select 'Hiệp định Pa-ri về chấm dứt chiến tranh, lập lại hòa bình ở Việt Nam (27-1-1973)', 'Điều 1 của Hiệp định ghi: “Hoa Kỳ và các nước khác tôn trọng độc lập, chủ quyền, thống nhất, toàn vẹn lãnh thổ của nước Việt Nam như Hiệp định Giơ-ne-vơ năm 1954 về Việt Nam đã công nhận.”
Hiệp định còn quy định: Hoa Kỳ rút hết quân đội của mình và quân các nước đồng minh trong vòng 60 ngày kể từ khi kí hiệp định, hủy bỏ các căn cứ quân sự của Mỹ, cam kết không tiếp tục can thiệp quân sự hoặc can thiệp vào công việc nội bộ của miền Nam Việt Nam; nhân dân miền Nam Việt Nam tự quyết định tương lai chính trị của họ thông qua tổng tuyển cử thực sự tự do, dân chủ; các bên trao trả tù binh và dân thường bị bắt; Hoa Kỳ cam kết góp phần hàn gắn vết thương chiến tranh ở Việt Nam.', 'Điều 1 trích từ văn bản Hiệp định Pa-ri (27-1-1973); các điều khoản còn lại do biên tập viên tóm lược theo SGK Lịch sử 12 (KNTT), Bài 8, mục 2', '8-khang-chien-chong-my-cuu-nuoc'
where not exists (select 1 from public.exam_passages where title = 'Hiệp định Pa-ri về chấm dứt chiến tranh, lập lại hòa bình ở Việt Nam (27-1-1973)' and body = 'Điều 1 của Hiệp định ghi: “Hoa Kỳ và các nước khác tôn trọng độc lập, chủ quyền, thống nhất, toàn vẹn lãnh thổ của nước Việt Nam như Hiệp định Giơ-ne-vơ năm 1954 về Việt Nam đã công nhận.”
Hiệp định còn quy định: Hoa Kỳ rút hết quân đội của mình và quân các nước đồng minh trong vòng 60 ngày kể từ khi kí hiệp định, hủy bỏ các căn cứ quân sự của Mỹ, cam kết không tiếp tục can thiệp quân sự hoặc can thiệp vào công việc nội bộ của miền Nam Việt Nam; nhân dân miền Nam Việt Nam tự quyết định tương lai chính trị của họ thông qua tổng tuyển cử thực sự tự do, dân chủ; các bên trao trả tù binh và dân thường bị bắt; Hoa Kỳ cam kết góp phần hàn gắn vết thương chiến tranh ở Việt Nam.');
insert into public.exam_passages (title, body, source_citation, lesson_slug)
select 'Cuộc Tổng tiến công và nổi dậy Xuân 1975', 'Cuối năm 1974 – đầu năm 1975, Bộ Chính trị đề ra kế hoạch giải phóng miền Nam trong hai năm 1975 và 1976, đồng thời nhấn mạnh: nếu thời cơ đến vào đầu hoặc cuối năm 1975 thì lập tức giải phóng miền Nam trong năm 1975. Chiến thắng Phước Long (6-1-1975) cho thấy khả năng can thiệp trở lại của Mỹ là rất hạn chế.
Cuộc Tổng tiến công và nổi dậy Xuân 1975 diễn ra qua ba chiến dịch lớn. Chiến dịch Tây Nguyên (4-3 đến 24-3-1975) mở đầu bằng trận then chốt đánh vào Buôn Ma Thuột. Chiến dịch Huế – Đà Nẵng (21-3 đến 29-3-1975) giải phóng Huế (26-3) và Đà Nẵng (29-3). Sau hai chiến dịch này, lực lượng của ta có ưu thế áp đảo. Chiến dịch Hồ Chí Minh bắt đầu từ chiều ngày 26-4-1975; 11 giờ 30 phút ngày 30-4-1975, lá cờ cách mạng tung bay trên nóc Dinh Độc Lập, chính quyền Sài Gòn tuyên bố đầu hàng không điều kiện. Ngày 2-5-1975, Châu Đốc là tỉnh cuối cùng của miền Nam được giải phóng.', 'Tóm lược của biên tập viên theo SGK Lịch sử 12 (KNTT), Bài 8, mục 3', '8-khang-chien-chong-my-cuu-nuoc'
where not exists (select 1 from public.exam_passages where title = 'Cuộc Tổng tiến công và nổi dậy Xuân 1975' and body = 'Cuối năm 1974 – đầu năm 1975, Bộ Chính trị đề ra kế hoạch giải phóng miền Nam trong hai năm 1975 và 1976, đồng thời nhấn mạnh: nếu thời cơ đến vào đầu hoặc cuối năm 1975 thì lập tức giải phóng miền Nam trong năm 1975. Chiến thắng Phước Long (6-1-1975) cho thấy khả năng can thiệp trở lại của Mỹ là rất hạn chế.
Cuộc Tổng tiến công và nổi dậy Xuân 1975 diễn ra qua ba chiến dịch lớn. Chiến dịch Tây Nguyên (4-3 đến 24-3-1975) mở đầu bằng trận then chốt đánh vào Buôn Ma Thuột. Chiến dịch Huế – Đà Nẵng (21-3 đến 29-3-1975) giải phóng Huế (26-3) và Đà Nẵng (29-3). Sau hai chiến dịch này, lực lượng của ta có ưu thế áp đảo. Chiến dịch Hồ Chí Minh bắt đầu từ chiều ngày 26-4-1975; 11 giờ 30 phút ngày 30-4-1975, lá cờ cách mạng tung bay trên nóc Dinh Độc Lập, chính quyền Sài Gòn tuyên bố đầu hàng không điều kiện. Ngày 2-5-1975, Châu Đốc là tỉnh cuối cùng của miền Nam được giải phóng.');
insert into public.exam_passages (title, body, source_citation, lesson_slug)
select 'Nguyên nhân thắng lợi và ý nghĩa của cuộc kháng chiến chống Mỹ, cứu nước', 'Cuộc kháng chiến chống Mỹ, cứu nước thắng lợi nhờ sự lãnh đạo của Đảng, đứng đầu là Chủ tịch Hồ Chí Minh, với đường lối tiến hành đồng thời cách mạng xã hội chủ nghĩa ở miền Bắc và cách mạng dân tộc dân chủ nhân dân ở miền Nam. Nhân dân hai miền đoàn kết, giàu lòng yêu nước; hậu phương miền Bắc xã hội chủ nghĩa đáp ứng kịp thời yêu cầu của tiền tuyến miền Nam. Bên cạnh đó là tình đoàn kết chiến đấu của ba dân tộc Đông Dương và sự đồng tình, ủng hộ, giúp đỡ của Liên Xô, Trung Quốc, các nước xã hội chủ nghĩa, nhân dân tiến bộ trên thế giới, trong đó có nhân dân Mỹ.
Thắng lợi đã kết thúc 21 năm kháng chiến chống Mỹ và 30 năm chiến tranh giải phóng dân tộc (1945 – 1975), hoàn thành cuộc cách mạng dân tộc dân chủ nhân dân trên cả nước, mở ra kỉ nguyên đất nước độc lập, thống nhất, đi lên chủ nghĩa xã hội. Thắng lợi tác động mạnh mẽ tới tình hình nước Mỹ và thế giới, cổ vũ phong trào giải phóng dân tộc.', 'Tóm lược của biên tập viên theo SGK Lịch sử 12 (KNTT), Bài 8, mục 4', '8-khang-chien-chong-my-cuu-nuoc'
where not exists (select 1 from public.exam_passages where title = 'Nguyên nhân thắng lợi và ý nghĩa của cuộc kháng chiến chống Mỹ, cứu nước' and body = 'Cuộc kháng chiến chống Mỹ, cứu nước thắng lợi nhờ sự lãnh đạo của Đảng, đứng đầu là Chủ tịch Hồ Chí Minh, với đường lối tiến hành đồng thời cách mạng xã hội chủ nghĩa ở miền Bắc và cách mạng dân tộc dân chủ nhân dân ở miền Nam. Nhân dân hai miền đoàn kết, giàu lòng yêu nước; hậu phương miền Bắc xã hội chủ nghĩa đáp ứng kịp thời yêu cầu của tiền tuyến miền Nam. Bên cạnh đó là tình đoàn kết chiến đấu của ba dân tộc Đông Dương và sự đồng tình, ủng hộ, giúp đỡ của Liên Xô, Trung Quốc, các nước xã hội chủ nghĩa, nhân dân tiến bộ trên thế giới, trong đó có nhân dân Mỹ.
Thắng lợi đã kết thúc 21 năm kháng chiến chống Mỹ và 30 năm chiến tranh giải phóng dân tộc (1945 – 1975), hoàn thành cuộc cách mạng dân tộc dân chủ nhân dân trên cả nước, mở ra kỉ nguyên đất nước độc lập, thống nhất, đi lên chủ nghĩa xã hội. Thắng lợi tác động mạnh mẽ tới tình hình nước Mỹ và thế giới, cổ vũ phong trào giải phóng dân tộc.');
update public.exam_items set content_key = 'b8-m1-ds-01'
 where content_key is null and fingerprint = public.exam_item_fingerprint('true_false', 'Đọc đoạn tư liệu về phong trào Đồng khởi (1959 – 1960) và cho biết mỗi ý sau đúng hay sai.', null, '[{"text":"Hội nghị Trung ương 15 (1-1959) chủ trương dùng bạo lực cách mạng, kết hợp đấu tranh chính trị với đấu tranh vũ trang.","is_true":true,"explanation":"Tư liệu nêu rõ quyết định của Hội nghị lần thứ 15.","section_id":"muc-1"},{"text":"Mặt trận Dân tộc giải phóng miền Nam Việt Nam ra đời trước phong trào Đồng khởi.","is_true":false,"explanation":"Sai thời gian: Mặt trận ra đời ngày 20-12-1960, “từ phong trào” Đồng khởi.","section_id":"muc-1","trap":"thoi_gian"},{"text":"Phong trào đánh dấu bước chuyển của cách mạng miền Nam từ thế giữ gìn lực lượng sang thế tiến công.","is_true":true,"explanation":"Đây là ý nghĩa của Đồng khởi theo tư liệu.","section_id":"muc-1"},{"text":"Sau phong trào Đồng khởi, chính quyền Sài Gòn sụp đổ hoàn toàn.","is_true":false,"explanation":"Tuyệt đối hóa: Đồng khởi chỉ “làm lung lay” chính quyền Ngô Đình Diệm; chính quyền Sài Gòn tồn tại đến năm 1975.","section_id":"muc-1","trap":"tuyet_doi"}]'::jsonb)
   and not exists (select 1 from public.exam_items where content_key = 'b8-m1-ds-01');
insert into public.exam_items (content_key, kind, stem, passage_id, choices, correct_index, statements, choice_notes, explanation, remember, grade, lesson_slug, section_id, topic_tag, level, competency, event_id, source_note)
values ('b8-m1-ds-01', 'true_false', 'Đọc đoạn tư liệu về phong trào Đồng khởi (1959 – 1960) và cho biết mỗi ý sau đúng hay sai.', (select id from public.exam_passages where title = 'Phong trào Đồng khởi (1959 – 1960)' and body = 'Sau năm 1954, Mỹ và chính quyền Ngô Đình Diệm ra sức đàn áp phong trào cách mạng miền Nam, thi hành chính sách “tố cộng”, “diệt cộng”, ban hành “Luật 10-59” lê máy chém khắp miền Nam. Tháng 1-1959, Hội nghị lần thứ 15 Ban Chấp hành Trung ương Đảng quyết định để nhân dân miền Nam sử dụng bạo lực cách mạng, kết hợp đấu tranh chính trị với đấu tranh vũ trang để đánh đổ chính quyền Mỹ – Diệm.
Phong trào nổi dậy lan rộng khắp miền Nam, tiêu biểu là cuộc Đồng khởi ở Bến Tre (bắt đầu từ ngày 17-1-1960 ở huyện Mỏ Cày). Từ phong trào, ngày 20-12-1960, Mặt trận Dân tộc giải phóng miền Nam Việt Nam ra đời. Phong trào Đồng khởi giáng đòn nặng nề vào chính sách thực dân kiểu mới của Mỹ, làm lung lay chính quyền Ngô Đình Diệm, đánh dấu bước phát triển của cách mạng miền Nam từ thế giữ gìn lực lượng sang thế tiến công.' order by created_at limit 1), null, null, '[{"text":"Hội nghị Trung ương 15 (1-1959) chủ trương dùng bạo lực cách mạng, kết hợp đấu tranh chính trị với đấu tranh vũ trang.","is_true":true,"explanation":"Tư liệu nêu rõ quyết định của Hội nghị lần thứ 15.","section_id":"muc-1"},{"text":"Mặt trận Dân tộc giải phóng miền Nam Việt Nam ra đời trước phong trào Đồng khởi.","is_true":false,"explanation":"Sai thời gian: Mặt trận ra đời ngày 20-12-1960, “từ phong trào” Đồng khởi.","section_id":"muc-1","trap":"thoi_gian"},{"text":"Phong trào đánh dấu bước chuyển của cách mạng miền Nam từ thế giữ gìn lực lượng sang thế tiến công.","is_true":true,"explanation":"Đây là ý nghĩa của Đồng khởi theo tư liệu.","section_id":"muc-1"},{"text":"Sau phong trào Đồng khởi, chính quyền Sài Gòn sụp đổ hoàn toàn.","is_true":false,"explanation":"Tuyệt đối hóa: Đồng khởi chỉ “làm lung lay” chính quyền Ngô Đình Diệm; chính quyền Sài Gòn tồn tại đến năm 1975.","section_id":"muc-1","trap":"tuyet_doi"}]'::jsonb, null, 'Câu đọc hiểu: chủ trương, diễn biến, ý nghĩa của Đồng khởi.', 'Hội nghị Trung ương 15 (1-1959) → Đồng khởi (1959 – 1960) → Mặt trận Dân tộc giải phóng (20-12-1960).', 12, '8-khang-chien-chong-my-cuu-nuoc', 'muc-1', null, 'thong_hieu', 'nhan_thuc_tu_duy', null, 'SGK Lịch sử 12 (KNTT), Bài 8, mục 1')
on conflict (content_key) do update set kind = excluded.kind, stem = excluded.stem, passage_id = excluded.passage_id, choices = excluded.choices, correct_index = excluded.correct_index, statements = excluded.statements, choice_notes = excluded.choice_notes, explanation = excluded.explanation, remember = excluded.remember, grade = excluded.grade, lesson_slug = excluded.lesson_slug, section_id = excluded.section_id, topic_tag = excluded.topic_tag, level = excluded.level, competency = excluded.competency, event_id = excluded.event_id, source_note = excluded.source_note
 where public.exam_items.workflow_status in ('draft', 'needs_revision');
update public.exam_items set content_key = 'b8-m1-ds-02'
 where content_key is null and fingerprint = public.exam_item_fingerprint('true_false', 'Đọc đoạn tư liệu về chiến lược “Chiến tranh đặc biệt” của Mỹ ở miền Nam rồi xác định mỗi ý sau đúng hay sai.', null, '[{"text":"Lực lượng chủ yếu tiến hành “Chiến tranh đặc biệt” là quân đội Sài Gòn.","is_true":true,"explanation":"Tư liệu: quân đội Sài Gòn là chủ yếu, đặt dưới sự chỉ huy của hệ thống cố vấn Mỹ.","section_id":"muc-1"},{"text":"“Ấp chiến lược” được Mỹ – chính quyền Sài Gòn coi là “xương sống” của chiến lược.","is_true":true,"explanation":"Tư liệu nêu rõ điều này.","section_id":"muc-1"},{"text":"Chiến thắng Ấp Bắc diễn ra sau khi “Chiến tranh đặc biệt” đã bị phá sản.","is_true":false,"explanation":"Sai thời gian: Ấp Bắc (1-1963) diễn ra giữa giai đoạn; “Chiến tranh đặc biệt” phá sản sau Đông – Xuân 1964 – 1965.","section_id":"muc-1","trap":"thoi_gian"},{"text":"So với “Chiến tranh cục bộ”, “Chiến tranh đặc biệt” sử dụng nhiều quân Mỹ trực tiếp chiến đấu hơn.","is_true":false,"explanation":"Đảo ngược: “Chiến tranh cục bộ” mới đưa quân Mỹ và quân đồng minh vào trực tiếp chiến đấu; “Chiến tranh đặc biệt” chủ yếu dùng quân đội Sài Gòn.","section_id":"muc-2","trap":"ban_chat"}]'::jsonb)
   and not exists (select 1 from public.exam_items where content_key = 'b8-m1-ds-02');
insert into public.exam_items (content_key, kind, stem, passage_id, choices, correct_index, statements, choice_notes, explanation, remember, grade, lesson_slug, section_id, topic_tag, level, competency, event_id, source_note)
values ('b8-m1-ds-02', 'true_false', 'Đọc đoạn tư liệu về chiến lược “Chiến tranh đặc biệt” của Mỹ ở miền Nam rồi xác định mỗi ý sau đúng hay sai.', (select id from public.exam_passages where title = 'Chiến lược “Chiến tranh đặc biệt” (1961 – 1965)' and body = 'Từ năm 1961, Mỹ tiến hành chiến lược “Chiến tranh đặc biệt” ở miền Nam. Lực lượng chủ yếu tiến hành chiến tranh là quân đội Sài Gòn, đặt dưới sự chỉ huy của hệ thống cố vấn Mỹ, dựa vào vũ khí, trang bị và phương tiện chiến tranh của Mỹ. Mỹ – chính quyền Sài Gòn đề ra kế hoạch dồn dân, lập “ấp chiến lược”, coi đó là “xương sống” của chiến lược nhằm tách dân khỏi cách mạng; sử dụng phổ biến các chiến thuật “trực thăng vận”, “thiết xa vận”.
Quân dân miền Nam vừa đấu tranh chống phá “ấp chiến lược”, vừa đánh bại các cuộc hành quân càn quét. Chiến thắng Ấp Bắc (Mỹ Tho, ngày 2-1-1963) chứng tỏ quân dân miền Nam có khả năng đánh bại chiến lược “Chiến tranh đặc biệt”. Trong Đông – Xuân 1964 – 1965, thắng lợi ở Bình Giã và nhiều nơi khác đã làm phá sản về cơ bản chiến lược này.' order by created_at limit 1), null, null, '[{"text":"Lực lượng chủ yếu tiến hành “Chiến tranh đặc biệt” là quân đội Sài Gòn.","is_true":true,"explanation":"Tư liệu: quân đội Sài Gòn là chủ yếu, đặt dưới sự chỉ huy của hệ thống cố vấn Mỹ.","section_id":"muc-1"},{"text":"“Ấp chiến lược” được Mỹ – chính quyền Sài Gòn coi là “xương sống” của chiến lược.","is_true":true,"explanation":"Tư liệu nêu rõ điều này.","section_id":"muc-1"},{"text":"Chiến thắng Ấp Bắc diễn ra sau khi “Chiến tranh đặc biệt” đã bị phá sản.","is_true":false,"explanation":"Sai thời gian: Ấp Bắc (1-1963) diễn ra giữa giai đoạn; “Chiến tranh đặc biệt” phá sản sau Đông – Xuân 1964 – 1965.","section_id":"muc-1","trap":"thoi_gian"},{"text":"So với “Chiến tranh cục bộ”, “Chiến tranh đặc biệt” sử dụng nhiều quân Mỹ trực tiếp chiến đấu hơn.","is_true":false,"explanation":"Đảo ngược: “Chiến tranh cục bộ” mới đưa quân Mỹ và quân đồng minh vào trực tiếp chiến đấu; “Chiến tranh đặc biệt” chủ yếu dùng quân đội Sài Gòn.","section_id":"muc-2","trap":"ban_chat"}]'::jsonb, null, 'Câu đọc hiểu và so sánh các chiến lược chiến tranh của Mỹ.', '“Chiến tranh đặc biệt”: quân đội Sài Gòn + cố vấn Mỹ; “Chiến tranh cục bộ”: quân Mỹ trực tiếp chiến đấu.', 12, '8-khang-chien-chong-my-cuu-nuoc', 'muc-1', null, 'van_dung', 'nhan_thuc_tu_duy', null, 'SGK Lịch sử 12 (KNTT), Bài 8, mục 1')
