values ('b8-m1-tn-01', 'mcq', 'Phong trào Đồng khởi (1959 – 1960) nổ ra tiêu biểu nhất ở tỉnh nào?', null, array['Tây Ninh', 'Cà Mau', 'Bến Tre', 'Quảng Ngãi'], 2, null, '[{"note":"Tây Ninh có phong trào nổi dậy trong thời kì này nhưng không phải nơi tiêu biểu nhất của Đồng khởi.","section_id":"muc-1","trap":"dia_diem"},{"note":"Cà Mau là vùng căn cứ cách mạng ở miền Tây Nam Bộ, không phải nơi tiêu biểu nhất của phong trào Đồng khởi.","section_id":"muc-1","trap":"dia_diem"},{"note":"Đúng. Đồng khởi bùng lên mạnh mẽ, tiêu biểu nhất ở Bến Tre (bắt đầu từ ngày 17-1-1960 ở Mỏ Cày), rồi lan rộng khắp miền Nam.","section_id":"muc-1"},{"note":"Quảng Ngãi có khởi nghĩa Trà Bồng (8-1959) trong thời kì này, nhưng nơi tiêu biểu nhất của phong trào Đồng khởi là Bến Tre.","section_id":"muc-1","trap":"dia_diem"}]'::jsonb, 'Phong trào Đồng khởi bùng lên mạnh mẽ, tiêu biểu nhất ở Bến Tre (1-1960), rồi lan rộng khắp miền Nam.', 'Đồng khởi (1959 – 1960): tiêu biểu là Bến Tre, bắt đầu ngày 17-1-1960.', 12, '8-khang-chien-chong-my-cuu-nuoc', 'muc-1', null, 'nhan_biet', 'tim_hieu_lich_su', null, 'SGK Lịch sử 12 (KNTT), Bài 8, mục 1')
