values ('b8-m1-tn-02', 'mcq', 'Mặt trận Dân tộc giải phóng miền Nam Việt Nam ra đời ngày', null, array['30-4-1975', '20-12-1960', '19-12-1946', '27-1-1973'], 1, null, '[{"note":"Ngày 30-4-1975 là ngày chiến dịch Hồ Chí Minh toàn thắng, giải phóng Sài Gòn.","section_id":"muc-3","trap":"thoi_gian"},{"note":"Đúng. Ngày 20-12-1960, Mặt trận Dân tộc giải phóng miền Nam Việt Nam ra đời — một thành quả của phong trào Đồng khởi.","section_id":"muc-1"},{"note":"Ngày 19-12-1946 là ngày bùng nổ kháng chiến toàn quốc chống thực dân Pháp.","lesson_slug":"7-khang-chien-chong-phap","section_id":"muc-1","trap":"thoi_gian"},{"note":"Ngày 27-1-1973 là ngày kí Hiệp định Pa-ri về Việt Nam.","section_id":"muc-2","trap":"thoi_gian"}]'::jsonb, 'Mặt trận Dân tộc giải phóng miền Nam Việt Nam ra đời ngày 20-12-1960, một thành quả của phong trào Đồng khởi.', '20-12-1960: Mặt trận Dân tộc giải phóng miền Nam Việt Nam ra đời.', 12, '8-khang-chien-chong-my-cuu-nuoc', 'muc-1', null, 'nhan_biet', 'tim_hieu_lich_su', null, 'SGK Lịch sử 12 (KNTT), Bài 8, mục 1')
