values ('b8-m1-tn-03', 'mcq', 'Chiến thắng Ấp Bắc (1-1963) chứng tỏ quân dân miền Nam có khả năng đánh bại chiến lược chiến tranh nào của Mỹ?', null, array['“Chiến tranh đặc biệt”', '“Chiến tranh cục bộ”', '“Việt Nam hóa chiến tranh”', '“Chiến tranh tổng lực”'], 0, null, '[{"note":"Đúng. Ấp Bắc (Mỹ Tho, 2-1-1963) diễn ra trong thời kì Mỹ thực hiện “Chiến tranh đặc biệt” (1961 – 1965), mở đầu phong trào “thi đua Ấp Bắc, giết giặc lập công”.","section_id":"muc-1"},{"note":"“Chiến tranh cục bộ” (1965 – 1968) bắt đầu sau Ấp Bắc; trận thắng lớn đầu tiên trước quân Mỹ là Vạn Tường (8-1965).","section_id":"muc-2","trap":"thoi_gian"},{"note":"“Việt Nam hóa chiến tranh” bắt đầu từ năm 1969, sau Ấp Bắc 6 năm.","section_id":"muc-2","trap":"thoi_gian"},{"note":"“Chiến tranh tổng lực” không phải tên một chiến lược chiến tranh của Mỹ ở miền Nam được nêu trong SGK (Mỹ lần lượt tiến hành “Chiến tranh đặc biệt”, “Chiến tranh cục bộ”, “Việt Nam hóa chiến tranh”).","section_id":"muc-1","trap":"khai_niem"}]'::jsonb, 'Ấp Bắc (1-1963) diễn ra trong thời kì Mỹ thực hiện “Chiến tranh đặc biệt” (1961 – 1965). Vạn Tường (8-1965) gắn với “Chiến tranh cục bộ”.', 'Ấp Bắc (2-1-1963) — chứng tỏ quân dân miền Nam có thể đánh bại “Chiến tranh đặc biệt”.', 12, '8-khang-chien-chong-my-cuu-nuoc', 'muc-1', null, 'thong_hieu', 'nhan_thuc_tu_duy', null, 'SGK Lịch sử 12 (KNTT), Bài 8, mục 1')
