values ('b8-m1-tn-04', 'mcq', 'Đại hội đại biểu toàn quốc lần thứ III của Đảng (9-1960) xác định cách mạng xã hội chủ nghĩa ở miền Bắc giữ vai trò', null, array['quyết định trực tiếp đối với sự nghiệp giải phóng miền Nam', 'quyết định nhất đối với sự phát triển của cách mạng cả nước', 'hậu phương tại chỗ của cách mạng miền Nam', 'chủ yếu là xây dựng kinh tế, tách biệt với cách mạng miền Nam'], 1, null, '[{"note":"Đánh tráo chủ thể: “quyết định trực tiếp” là vai trò của cách mạng dân tộc dân chủ nhân dân ở miền Nam.","section_id":"muc-1","trap":"chu_the"},{"note":"Đúng. Đại hội III xác định: cách mạng xã hội chủ nghĩa ở miền Bắc có vai trò quyết định nhất; cách mạng ở miền Nam có vai trò quyết định trực tiếp đối với sự nghiệp giải phóng miền Nam.","section_id":"muc-1"},{"note":"Nhầm khái niệm: hậu phương tại chỗ là vùng giải phóng ở miền Nam; miền Bắc là hậu phương LỚN của cả nước.","section_id":"muc-1","trap":"khai_niem"},{"note":"Sai bản chất: cách mạng hai miền gắn bó mật thiết, cùng hướng tới mục tiêu chung là giải phóng miền Nam, thống nhất đất nước.","section_id":"muc-1","trap":"ban_chat"}]'::jsonb, 'Phân biệt vai trò của hai miền theo Đại hội III: miền Bắc — quyết định nhất; miền Nam — quyết định trực tiếp.', 'Đại hội III (9-1960): miền Bắc — vai trò quyết định nhất; miền Nam — quyết định trực tiếp.', 12, '8-khang-chien-chong-my-cuu-nuoc', 'muc-1', null, 'thong_hieu', 'nhan_thuc_tu_duy', null, 'SGK Lịch sử 12 (KNTT), Bài 8, mục 1')
