insert into public.exam_items (content_key, kind, stem, passage_id, choices, correct_index, statements, choice_notes, explanation, remember, grade, lesson_slug, section_id, topic_tag, level, competency, event_id, source_note)
values ('b8-m1-tn-05', 'mcq', 'Theo đoạn tư liệu, phong trào Đồng khởi đánh dấu bước phát triển nào của cách mạng miền Nam?', (select id from public.exam_passages where title = 'Phong trào Đồng khởi (1959 – 1960)' and body = 'Sau năm 1954, Mỹ và chính quyền Ngô Đình Diệm ra sức đàn áp phong trào cách mạng miền Nam, thi hành chính sách “tố cộng”, “diệt cộng”, ban hành “Luật 10-59” lê máy chém khắp miền Nam. Tháng 1-1959, Hội nghị lần thứ 15 Ban Chấp hành Trung ương Đảng quyết định để nhân dân miền Nam sử dụng bạo lực cách mạng, kết hợp đấu tranh chính trị với đấu tranh vũ trang để đánh đổ chính quyền Mỹ – Diệm.
Phong trào nổi dậy lan rộng khắp miền Nam, tiêu biểu là cuộc Đồng khởi ở Bến Tre (bắt đầu từ ngày 17-1-1960 ở huyện Mỏ Cày). Từ phong trào, ngày 20-12-1960, Mặt trận Dân tộc giải phóng miền Nam Việt Nam ra đời. Phong trào Đồng khởi giáng đòn nặng nề vào chính sách thực dân kiểu mới của Mỹ, làm lung lay chính quyền Ngô Đình Diệm, đánh dấu bước phát triển của cách mạng miền Nam từ thế giữ gìn lực lượng sang thế tiến công.' order by created_at limit 1), array['Từ thế tiến công chuyển sang thế phòng ngự', 'Từ đấu tranh vũ trang chuyển sang đấu tranh ngoại giao', 'Từ thế giữ gìn lực lượng chuyển sang thế tiến công', 'Từ khởi nghĩa từng phần tiến lên tổng khởi nghĩa toàn quốc'], 2, null, '[{"note":"Đảo ngược: tư liệu ghi Đồng khởi đánh dấu bước chuyển “từ thế giữ gìn lực lượng sang thế tiến công”.","section_id":"muc-1","trap":"ban_chat"},{"note":"Sai bản chất: Hội nghị Trung ương 15 chủ trương dùng bạo lực cách mạng, kết hợp đấu tranh chính trị với vũ trang — không chuyển sang ngoại giao.","section_id":"muc-1","trap":"ban_chat"},{"note":"Đúng. Đồng khởi giáng đòn nặng nề vào chính sách thực dân kiểu mới của Mỹ, đưa cách mạng miền Nam từ thế giữ gìn lực lượng sang thế tiến công.","section_id":"muc-1"},{"note":"Nhầm khái niệm và thời gian: “khởi nghĩa từng phần tiến lên tổng khởi nghĩa” là bài học của Cách mạng tháng Tám năm 1945.","lesson_slug":"6-cach-mang-thang-tam-nam-1945","section_id":"muc-2","trap":"khai_niem"}]'::jsonb, 'Câu đọc hiểu ý nghĩa của phong trào Đồng khởi.', 'Đồng khởi: cách mạng miền Nam từ thế giữ gìn lực lượng sang thế tiến công.', 12, '8-khang-chien-chong-my-cuu-nuoc', 'muc-1', null, 'thong_hieu', 'nhan_thuc_tu_duy', null, 'SGK Lịch sử 12 (KNTT), Bài 8, mục 1')
