update public.exam_items set content_key = 'b8-m1-tn-06'
 where content_key is null and fingerprint = public.exam_item_fingerprint('mcq', 'Vì sao Mỹ – chính quyền Sài Gòn coi “ấp chiến lược” là “xương sống” của chiến lược “Chiến tranh đặc biệt”?', array['Vì đó là nơi đóng quân chủ yếu của quân viễn chinh Mỹ', 'Vì muốn tách dân khỏi cách mạng, kiểm soát vùng nông thôn', 'Vì đó là các căn cứ sản xuất vũ khí cho quân đội Sài Gòn', 'Vì đó là các khu kinh tế mới để phát triển nông nghiệp'], null)
   and not exists (select 1 from public.exam_items where content_key = 'b8-m1-tn-06');
insert into public.exam_items (content_key, kind, stem, passage_id, choices, correct_index, statements, choice_notes, explanation, remember, grade, lesson_slug, section_id, topic_tag, level, competency, event_id, source_note)
values ('b8-m1-tn-06', 'mcq', 'Vì sao Mỹ – chính quyền Sài Gòn coi “ấp chiến lược” là “xương sống” của chiến lược “Chiến tranh đặc biệt”?', null, array['Vì đó là nơi đóng quân chủ yếu của quân viễn chinh Mỹ', 'Vì muốn tách dân khỏi cách mạng, kiểm soát vùng nông thôn', 'Vì đó là các căn cứ sản xuất vũ khí cho quân đội Sài Gòn', 'Vì đó là các khu kinh tế mới để phát triển nông nghiệp'], 1, null, '[{"note":"Đánh tráo chủ thể: “Chiến tranh đặc biệt” dùng quân đội Sài Gòn là chủ yếu; quân viễn chinh Mỹ chỉ ồ ạt vào miền Nam từ năm 1965.","section_id":"muc-2","trap":"chu_the"},{"note":"Đúng. Dồn dân lập “ấp chiến lược” nhằm “tách dân khỏi cách mạng” — không có dân thì cách mạng mất chỗ dựa; vì vậy phá “ấp chiến lược” là nhiệm vụ trọng tâm của ta.","section_id":"muc-1"},{"note":"Hiểu sai: vũ khí, trang bị của quân đội Sài Gòn chủ yếu do Mỹ cung cấp.","section_id":"muc-1","trap":"ban_chat"},{"note":"Hiểu sai bản chất: “ấp chiến lược” là biện pháp quân sự – chính trị để kiểm soát dân, không phải chương trình phát triển kinh tế.","section_id":"muc-1","trap":"ban_chat"}]'::jsonb, 'Câu giải thích: mục đích của “ấp chiến lược” trong “Chiến tranh đặc biệt”.', '“Ấp chiến lược” — “xương sống” của “Chiến tranh đặc biệt”, nhằm tách dân khỏi cách mạng.', 12, '8-khang-chien-chong-my-cuu-nuoc', 'muc-1', null, 'van_dung', 'nhan_thuc_tu_duy', null, 'SGK Lịch sử 12 (KNTT), Bài 8, mục 1')
