update public.exam_items set content_key = 'b8-m1-tn-07'
 where content_key is null and fingerprint = public.exam_item_fingerprint('mcq', 'Tuyến đường Trường Sơn (đường Hồ Chí Minh) được mở từ tháng 5-1959 nhằm mục đích chủ yếu nào?', array['Vận chuyển hàng hóa thương mại sang các nước Đông Dương', 'Phục vụ chiến dịch Điện Biên Phủ của quân đội ta', 'Chi viện sức người, sức của từ miền Bắc cho miền Nam', 'Chủ yếu chi viện cho cách mạng Lào và Cam-pu-chia'], null)
   and not exists (select 1 from public.exam_items where content_key = 'b8-m1-tn-07');
insert into public.exam_items (content_key, kind, stem, passage_id, choices, correct_index, statements, choice_notes, explanation, remember, grade, lesson_slug, section_id, topic_tag, level, competency, event_id, source_note)
values ('b8-m1-tn-07', 'mcq', 'Tuyến đường Trường Sơn (đường Hồ Chí Minh) được mở từ tháng 5-1959 nhằm mục đích chủ yếu nào?', null, array['Vận chuyển hàng hóa thương mại sang các nước Đông Dương', 'Phục vụ chiến dịch Điện Biên Phủ của quân đội ta', 'Chi viện sức người, sức của từ miền Bắc cho miền Nam', 'Chủ yếu chi viện cho cách mạng Lào và Cam-pu-chia'], 2, null, '[{"note":"Hiểu sai bản chất: đường Trường Sơn là tuyến chi viện chiến lược phục vụ kháng chiến, không phải đường thương mại.","section_id":"muc-1","trap":"ban_chat"},{"note":"Sai thời gian: chiến dịch Điện Biên Phủ diễn ra năm 1954, trước khi mở đường Trường Sơn 5 năm.","lesson_slug":"7-khang-chien-chong-phap","section_id":"muc-3","trap":"thoi_gian"},{"note":"Đúng. Từ tháng 5-1959, đường Trường Sơn được mở để chi viện sức người, sức của từ hậu phương miền Bắc cho chiến trường miền Nam.","section_id":"muc-1"},{"note":"Đường Trường Sơn có đoạn đi qua Lào và có hỗ trợ nước bạn, nhưng mục đích chủ yếu là chi viện cho chiến trường miền Nam Việt Nam.","section_id":"muc-1","trap":"chu_the"}]'::jsonb, 'Đường Trường Sơn nối hậu phương lớn miền Bắc với tiền tuyến lớn miền Nam.', 'Đường Trường Sơn (từ 5-1959): tuyến chi viện chiến lược Bắc – Nam.', 12, '8-khang-chien-chong-my-cuu-nuoc', 'muc-1', null, 'nhan_biet', 'tim_hieu_lich_su', null, 'SGK Lịch sử 12 (KNTT), Bài 8, mục 1')
