update public.exam_items set content_key = 'b8-m2-ds-01'
 where content_key is null and fingerprint = public.exam_item_fingerprint('true_false', 'Cho thông tin: “Ngày 27-1-1973, Hiệp định Pa-ri về chấm dứt chiến tranh, lập lại hòa bình ở Việt Nam được kí chính thức.”', null, '[{"text":"Hoa Kỳ cam kết tôn trọng độc lập, chủ quyền, thống nhất và toàn vẹn lãnh thổ của Việt Nam.","is_true":true,"explanation":"Đây là điều khoản quan trọng nhất của Hiệp định Pa-ri (Điều 1).","section_id":"muc-2"},{"text":"Hiệp định quy định quân đội Mỹ và quân đồng minh của Mỹ được tiếp tục ở lại miền Nam.","is_true":false,"explanation":"Trái với hiệp định: Mỹ phải rút hết quân đội và quân đồng minh trong vòng 60 ngày.","section_id":"muc-2","trap":"ban_chat"},{"text":"Hiệp định Pa-ri đánh dấu việc hoàn thành thống nhất đất nước.","is_true":false,"explanation":"Sai thời gian: miền Nam được giải phóng năm 1975; đất nước thống nhất về mặt nhà nước năm 1976.","section_id":"muc-4","trap":"thoi_gian"},{"text":"Hiệp định Pa-ri là kết quả của cuộc đấu tranh quân sự, chính trị và ngoại giao.","is_true":true,"explanation":"Thắng lợi trên chiến trường, đặc biệt là “Điện Biên Phủ trên không” cuối năm 1972, kết hợp đấu tranh chính trị, ngoại giao buộc Mỹ kí hiệp định.","section_id":"muc-2"}]'::jsonb)
   and not exists (select 1 from public.exam_items where content_key = 'b8-m2-ds-01');
insert into public.exam_items (content_key, kind, stem, passage_id, choices, correct_index, statements, choice_notes, explanation, remember, grade, lesson_slug, section_id, topic_tag, level, competency, event_id, source_note)
values ('b8-m2-ds-01', 'true_false', 'Cho thông tin: “Ngày 27-1-1973, Hiệp định Pa-ri về chấm dứt chiến tranh, lập lại hòa bình ở Việt Nam được kí chính thức.”', null, null, null, '[{"text":"Hoa Kỳ cam kết tôn trọng độc lập, chủ quyền, thống nhất và toàn vẹn lãnh thổ của Việt Nam.","is_true":true,"explanation":"Đây là điều khoản quan trọng nhất của Hiệp định Pa-ri (Điều 1).","section_id":"muc-2"},{"text":"Hiệp định quy định quân đội Mỹ và quân đồng minh của Mỹ được tiếp tục ở lại miền Nam.","is_true":false,"explanation":"Trái với hiệp định: Mỹ phải rút hết quân đội và quân đồng minh trong vòng 60 ngày.","section_id":"muc-2","trap":"ban_chat"},{"text":"Hiệp định Pa-ri đánh dấu việc hoàn thành thống nhất đất nước.","is_true":false,"explanation":"Sai thời gian: miền Nam được giải phóng năm 1975; đất nước thống nhất về mặt nhà nước năm 1976.","section_id":"muc-4","trap":"thoi_gian"},{"text":"Hiệp định Pa-ri là kết quả của cuộc đấu tranh quân sự, chính trị và ngoại giao.","is_true":true,"explanation":"Thắng lợi trên chiến trường, đặc biệt là “Điện Biên Phủ trên không” cuối năm 1972, kết hợp đấu tranh chính trị, ngoại giao buộc Mỹ kí hiệp định.","section_id":"muc-2"}]'::jsonb, null, 'Câu kiểm tra nội dung và ý nghĩa của Hiệp định Pa-ri năm 1973.', 'Hiệp định Pa-ri (27-1-1973): Mỹ rút hết quân trong 60 ngày — “đánh cho Mỹ cút”, tạo thời cơ giải phóng miền Nam.', 12, '8-khang-chien-chong-my-cuu-nuoc', 'muc-2', null, 'thong_hieu', 'nhan_thuc_tu_duy', (select id from public.historical_events where slug = 'hiep-dinh-paris-ve-viet-nam'), 'SGK Lịch sử 12 (KNTT), Bài 8, mục 2')
