update public.exam_items set content_key = 'b8-m2-ds-02'
 where content_key is null and fingerprint = public.exam_item_fingerprint('true_false', 'Đọc đoạn tư liệu về cuộc Tổng tiến công và nổi dậy Tết Mậu Thân năm 1968, rồi xác định mỗi ý sau đúng hay sai.', null, '[{"text":"Cuộc tiến công và nổi dậy diễn ra đồng loạt ở hầu khắp các đô thị miền Nam.","is_true":true,"explanation":"Tư liệu: “đồng loạt tiến công và nổi dậy ở hầu khắp các đô thị miền Nam”.","section_id":"muc-2"},{"text":"Sau Tết Mậu Thân, Mỹ chuyển sang chiến lược “Chiến tranh đặc biệt”.","is_true":false,"explanation":"Sai thời gian: “Chiến tranh đặc biệt” (1961 – 1965) đã bị phá sản từ trước; sau năm 1968, Mỹ chuyển sang “Việt Nam hóa chiến tranh”.","section_id":"muc-2","trap":"thoi_gian"},{"text":"Thắng lợi buộc Mỹ chấp nhận đến bàn đàm phán ở Pa-ri.","is_true":true,"explanation":"Đây là một kết quả trực tiếp được tư liệu nêu.","section_id":"muc-2"},{"text":"Từ tư liệu có thể khẳng định Tết Mậu Thân là trận quyết chiến chiến lược kết thúc cuộc kháng chiến.","is_true":false,"explanation":"Nhầm khái niệm: Tết Mậu Thân “mở ra bước ngoặt”; cuộc kháng chiến kết thúc bằng Tổng tiến công và nổi dậy Xuân 1975.","section_id":"muc-3","trap":"khai_niem"}]'::jsonb)
   and not exists (select 1 from public.exam_items where content_key = 'b8-m2-ds-02');
insert into public.exam_items (content_key, kind, stem, passage_id, choices, correct_index, statements, choice_notes, explanation, remember, grade, lesson_slug, section_id, topic_tag, level, competency, event_id, source_note)
values ('b8-m2-ds-02', 'true_false', 'Đọc đoạn tư liệu về cuộc Tổng tiến công và nổi dậy Tết Mậu Thân năm 1968, rồi xác định mỗi ý sau đúng hay sai.', (select id from public.exam_passages where title = 'Tổng tiến công và nổi dậy Tết Mậu Thân 1968' and body = 'Đêm 30 rạng sáng ngày 31-1-1968 (Tết Mậu Thân), quân dân miền Nam đồng loạt tiến công và nổi dậy ở hầu khắp các đô thị miền Nam, đánh vào các cơ quan đầu não của Mỹ và chính quyền Sài Gòn. Ở Sài Gòn, các mục tiêu quan trọng như Tòa đại sứ Mỹ, Dinh Độc Lập, Bộ Tổng tham mưu quân đội Sài Gòn, sân bay Tân Sơn Nhất bị tiến công.
Cuộc Tổng tiến công và nổi dậy đã làm lung lay ý chí xâm lược của Mỹ, buộc Mỹ phải tuyên bố “phi Mỹ hóa” chiến tranh (tức là thừa nhận sự thất bại của chiến lược “Chiến tranh cục bộ”), chấm dứt ném bom miền Bắc và chấp nhận đến bàn đàm phán ở Pa-ri — mở ra bước ngoặt mới của cuộc kháng chiến.' order by created_at limit 1), null, null, '[{"text":"Cuộc tiến công và nổi dậy diễn ra đồng loạt ở hầu khắp các đô thị miền Nam.","is_true":true,"explanation":"Tư liệu: “đồng loạt tiến công và nổi dậy ở hầu khắp các đô thị miền Nam”.","section_id":"muc-2"},{"text":"Sau Tết Mậu Thân, Mỹ chuyển sang chiến lược “Chiến tranh đặc biệt”.","is_true":false,"explanation":"Sai thời gian: “Chiến tranh đặc biệt” (1961 – 1965) đã bị phá sản từ trước; sau năm 1968, Mỹ chuyển sang “Việt Nam hóa chiến tranh”.","section_id":"muc-2","trap":"thoi_gian"},{"text":"Thắng lợi buộc Mỹ chấp nhận đến bàn đàm phán ở Pa-ri.","is_true":true,"explanation":"Đây là một kết quả trực tiếp được tư liệu nêu.","section_id":"muc-2"},{"text":"Từ tư liệu có thể khẳng định Tết Mậu Thân là trận quyết chiến chiến lược kết thúc cuộc kháng chiến.","is_true":false,"explanation":"Nhầm khái niệm: Tết Mậu Thân “mở ra bước ngoặt”; cuộc kháng chiến kết thúc bằng Tổng tiến công và nổi dậy Xuân 1975.","section_id":"muc-3","trap":"khai_niem"}]'::jsonb, null, 'Câu đọc hiểu và đánh giá: diễn biến, kết quả, vị trí của Tết Mậu Thân 1968.', 'Tết Mậu Thân 1968: bước ngoặt — Mỹ “phi Mỹ hóa” chiến tranh, chấp nhận đàm phán.', 12, '8-khang-chien-chong-my-cuu-nuoc', 'muc-2', null, 'van_dung', 'van_dung_kien_thuc', (select id from public.historical_events where slug = 'tong-tien-cong-va-noi-day-tet-mau-than-1968'), 'SGK Lịch sử 12 (KNTT), Bài 8, mục 2')
