   and not exists (select 1 from public.exam_items where content_key = 'b8-m2-tn-01');
insert into public.exam_items (content_key, kind, stem, passage_id, choices, correct_index, statements, choice_notes, explanation, remember, grade, lesson_slug, section_id, topic_tag, level, competency, event_id, source_note)
values ('b8-m2-tn-01', 'mcq', 'Chiến thắng Vạn Tường (Quảng Ngãi, 8-1965) mở đầu cao trào “tìm Mỹ mà đánh” trong thời kì Mỹ tiến hành chiến lược', null, array['“Chiến tranh đặc biệt”', '“Việt Nam hóa chiến tranh”', '“Chiến tranh đơn phương”', '“Chiến tranh cục bộ”'], 3, null, '[{"note":"“Chiến tranh đặc biệt” (1961 – 1965) dùng quân đội Sài Gòn là chủ yếu; Vạn Tường là trận đánh quân Mỹ.","section_id":"muc-1","trap":"thoi_gian"},{"note":"“Việt Nam hóa chiến tranh” bắt đầu từ năm 1969, sau Vạn Tường bốn năm.","section_id":"muc-2","trap":"thoi_gian"},{"note":"“Chiến tranh đơn phương” là cách gọi chính sách khủng bố, đàn áp của Mỹ – Diệm những năm 1954 – 1960, trước Vạn Tường.","section_id":"muc-1","trap":"thoi_gian"},{"note":"Đúng. Vạn Tường (Quảng Ngãi, 18-8-1965) là trận thắng lớn đầu tiên trước quân viễn chinh Mỹ trong “Chiến tranh cục bộ” (1965 – 1968), mở đầu cao trào “tìm Mỹ mà đánh, lùng ngụy mà diệt”.","section_id":"muc-2"}]'::jsonb, 'Vạn Tường được coi là “Ấp Bắc” đối với quân Mỹ: chứng tỏ quân dân miền Nam có thể đánh thắng quân viễn chinh Mỹ.', 'Vạn Tường (8-1965): mở đầu cao trào “tìm Mỹ mà đánh, lùng ngụy mà diệt” trong “Chiến tranh cục bộ”.', 12, '8-khang-chien-chong-my-cuu-nuoc', 'muc-2', null, 'thong_hieu', 'nhan_thuc_tu_duy', null, 'SGK Lịch sử 12 (KNTT), Bài 8, mục 2')
