 where content_key is null and fingerprint = public.exam_item_fingerprint('mcq', 'Chiến lược “Chiến tranh cục bộ” (1965 – 1968) của Mỹ ở miền Nam được tiến hành bằng lực lượng nào?', array['Quân đội Sài Gòn là chủ yếu, dưới sự chỉ huy của cố vấn Mỹ', 'Quân Mỹ, quân đồng minh của Mỹ và quân đội Sài Gòn', 'Chỉ có quân đội Sài Gòn, được hỏa lực Mỹ yểm trợ', 'Chỉ có không quân và hải quân Mỹ đánh phá từ xa'], null)
