values ('b8-m2-tn-02', 'mcq', 'Chiến lược “Chiến tranh cục bộ” (1965 – 1968) của Mỹ ở miền Nam được tiến hành bằng lực lượng nào?', null, array['Quân đội Sài Gòn là chủ yếu, dưới sự chỉ huy của cố vấn Mỹ', 'Quân Mỹ, quân đồng minh của Mỹ và quân đội Sài Gòn', 'Chỉ có quân đội Sài Gòn, được hỏa lực Mỹ yểm trợ', 'Chỉ có không quân và hải quân Mỹ đánh phá từ xa'], 1, null, '[{"note":"Đây là lực lượng của “Chiến tranh đặc biệt” (1961 – 1965).","section_id":"muc-1","trap":"thoi_gian"},{"note":"Đúng. Trong “Chiến tranh cục bộ”, Mỹ đưa quân viễn chinh Mỹ và quân các nước đồng minh vào trực tiếp chiến đấu cùng quân đội Sài Gòn.","section_id":"muc-2"},{"note":"Đây gần với “Việt Nam hóa chiến tranh” (từ năm 1969): quân đội Sài Gòn là chủ yếu, có hỏa lực Mỹ hỗ trợ.","section_id":"muc-2","trap":"thoi_gian"},{"note":"Nhầm khái niệm: không quân, hải quân Mỹ đánh phá từ xa là đặc điểm của chiến tranh phá hoại miền Bắc.","section_id":"muc-2","trap":"khai_niem"}]'::jsonb, 'Lực lượng là dấu hiệu dễ nhận ra nhất để phân biệt các chiến lược chiến tranh của Mỹ.', '“Chiến tranh cục bộ”: quân Mỹ + quân đồng minh + quân đội Sài Gòn.', 12, '8-khang-chien-chong-my-cuu-nuoc', 'muc-2', null, 'nhan_biet', 'tim_hieu_lich_su', null, 'SGK Lịch sử 12 (KNTT), Bài 8, mục 2')
