values ('b8-m2-tn-03', 'mcq', 'Cuộc Tổng tiến công và nổi dậy Tết Mậu Thân của quân dân miền Nam bắt đầu vào', null, array['đêm 30, rạng sáng 31-1-1968', 'đêm 18-12-1972', 'ngày 30-3-1972', 'chiều ngày 26-4-1975'], 0, null, '[{"note":"Đúng. Đêm 30 rạng sáng ngày 31-1-1968 (Tết Mậu Thân), quân dân miền Nam đồng loạt tiến công và nổi dậy ở hầu khắp các đô thị.","section_id":"muc-2"},{"note":"Đêm 18-12-1972 mở đầu cuộc tập kích chiến lược bằng B-52 của Mỹ vào Hà Nội, Hải Phòng — trận “Điện Biên Phủ trên không”.","section_id":"muc-2","trap":"thoi_gian"},{"note":"Ngày 30-3-1972 là ngày bắt đầu cuộc Tiến công chiến lược năm 1972 ở miền Nam.","section_id":"muc-2","trap":"thoi_gian"},{"note":"Chiều ngày 26-4-1975 là thời điểm bắt đầu chiến dịch Hồ Chí Minh.","section_id":"muc-3","trap":"thoi_gian"}]'::jsonb, 'Các mốc tiến công lớn: Tết Mậu Thân (31-1-1968), Tiến công chiến lược (30-3-1972), chiến dịch Hồ Chí Minh (26-4-1975).', 'Tết Mậu Thân: đêm 30 rạng sáng 31-1-1968.', 12, '8-khang-chien-chong-my-cuu-nuoc', 'muc-2', null, 'nhan_biet', 'tim_hieu_lich_su', (select id from public.historical_events where slug = 'tong-tien-cong-va-noi-day-tet-mau-than-1968'), 'SGK Lịch sử 12 (KNTT), Bài 8, mục 2')
