values ('b8-m2-tn-04', 'mcq', 'Theo đoạn tư liệu, cuộc Tổng tiến công và nổi dậy Tết Mậu Thân 1968 đã buộc Mỹ phải', (select id from public.exam_passages where title = 'Tổng tiến công và nổi dậy Tết Mậu Thân 1968' and body = 'Đêm 30 rạng sáng ngày 31-1-1968 (Tết Mậu Thân), quân dân miền Nam đồng loạt tiến công và nổi dậy ở hầu khắp các đô thị miền Nam, đánh vào các cơ quan đầu não của Mỹ và chính quyền Sài Gòn. Ở Sài Gòn, các mục tiêu quan trọng như Tòa đại sứ Mỹ, Dinh Độc Lập, Bộ Tổng tham mưu quân đội Sài Gòn, sân bay Tân Sơn Nhất bị tiến công.
Cuộc Tổng tiến công và nổi dậy đã làm lung lay ý chí xâm lược của Mỹ, buộc Mỹ phải tuyên bố “phi Mỹ hóa” chiến tranh (tức là thừa nhận sự thất bại của chiến lược “Chiến tranh cục bộ”), chấm dứt ném bom miền Bắc và chấp nhận đến bàn đàm phán ở Pa-ri — mở ra bước ngoặt mới của cuộc kháng chiến.' order by created_at limit 1), array['kí ngay Hiệp định Pa-ri, rút hết quân khỏi miền Nam', 'tuyên bố “phi Mỹ hóa” chiến tranh và chấp nhận đàm phán ở Pa-ri', 'chuyển sang chiến lược “Chiến tranh đặc biệt”', 'mở rộng ném bom ra toàn bộ miền Bắc'], 1, null, '[{"note":"Sai thời gian: Hiệp định Pa-ri được kí năm 1973; Mỹ rút hết quân sau đó 60 ngày.","section_id":"muc-2","trap":"thoi_gian"},{"note":"Đúng. Mỹ phải tuyên bố “phi Mỹ hóa” chiến tranh (thừa nhận thất bại của “Chiến tranh cục bộ”), chấm dứt ném bom miền Bắc và chấp nhận đàm phán ở Pa-ri.","section_id":"muc-2"},{"note":"Sai thời gian: “Chiến tranh đặc biệt” (1961 – 1965) đã bị phá sản trước đó; sau năm 1968 Mỹ chuyển sang “Việt Nam hóa chiến tranh”.","section_id":"muc-1","trap":"thoi_gian"},{"note":"Ngược tư liệu: Mỹ phải “chấm dứt ném bom miền Bắc”.","section_id":"muc-2","trap":"ban_chat"}]'::jsonb, 'Câu đọc hiểu kết quả của Tết Mậu Thân — bước ngoặt của cuộc kháng chiến.', 'Tết Mậu Thân 1968 → Mỹ “phi Mỹ hóa” chiến tranh, ngừng ném bom miền Bắc, đàm phán ở Pa-ri.', 12, '8-khang-chien-chong-my-cuu-nuoc', 'muc-2', null, 'thong_hieu', 'nhan_thuc_tu_duy', (select id from public.historical_events where slug = 'tong-tien-cong-va-noi-day-tet-mau-than-1968'), 'SGK Lịch sử 12 (KNTT), Bài 8, mục 2')
