insert into public.exam_items (content_key, kind, stem, passage_id, choices, correct_index, statements, choice_notes, explanation, remember, grade, lesson_slug, section_id, topic_tag, level, competency, event_id, source_note)
values ('b8-m2-tn-05', 'mcq', 'Việc chọn thời điểm Tết Nguyên đán và đánh vào các đô thị, cơ quan đầu não của địch trong năm 1968 cho thấy điều gì?', (select id from public.exam_passages where title = 'Tổng tiến công và nổi dậy Tết Mậu Thân 1968' and body = 'Đêm 30 rạng sáng ngày 31-1-1968 (Tết Mậu Thân), quân dân miền Nam đồng loạt tiến công và nổi dậy ở hầu khắp các đô thị miền Nam, đánh vào các cơ quan đầu não của Mỹ và chính quyền Sài Gòn. Ở Sài Gòn, các mục tiêu quan trọng như Tòa đại sứ Mỹ, Dinh Độc Lập, Bộ Tổng tham mưu quân đội Sài Gòn, sân bay Tân Sơn Nhất bị tiến công.
Cuộc Tổng tiến công và nổi dậy đã làm lung lay ý chí xâm lược của Mỹ, buộc Mỹ phải tuyên bố “phi Mỹ hóa” chiến tranh (tức là thừa nhận sự thất bại của chiến lược “Chiến tranh cục bộ”), chấm dứt ném bom miền Bắc và chấp nhận đến bàn đàm phán ở Pa-ri — mở ra bước ngoặt mới của cuộc kháng chiến.' order by created_at limit 1), array['Ta tạo yếu tố bất ngờ, đánh vào nơi địch cho là an toàn nhất', 'Ta muốn tránh giao chiến trực tiếp với quân Mỹ', 'Ta chủ trương chỉ chiến đấu ở nông thôn là chính', 'Ta chỉ dùng lực lượng chính trị, không dùng vũ trang'], 0, null, '[{"note":"Đúng. Tiến công vào dịp Tết, vào các đô thị và cơ quan đầu não (như Tòa đại sứ Mỹ, Dinh Độc Lập) — nơi địch tưởng an toàn nhất — tạo bất ngờ lớn, tác động mạnh tới ý chí xâm lược của Mỹ.","section_id":"muc-2"},{"note":"Trái tư liệu: các mục tiêu như Tòa đại sứ Mỹ, sân bay Tân Sơn Nhất cho thấy ta đánh thẳng vào Mỹ và chính quyền Sài Gòn.","section_id":"muc-2","trap":"ban_chat"},{"note":"Trái tư liệu: Tết Mậu Thân là cuộc tiến công vào “hầu khắp các đô thị miền Nam”.","section_id":"muc-2","trap":"dia_diem"},{"note":"Tuyệt đối hóa: đây là cuộc “tiến công và nổi dậy” — kết hợp lực lượng vũ trang với nổi dậy của quần chúng.","section_id":"muc-2","trap":"tuyet_doi"}]'::jsonb, 'Câu nhận xét về nghệ thuật chọn thời điểm và mục tiêu tiến công.', 'Tết Mậu Thân: bất ngờ về thời điểm (Tết) và mục tiêu (đô thị, cơ quan đầu não).', 12, '8-khang-chien-chong-my-cuu-nuoc', 'muc-2', null, 'van_dung', 'nhan_thuc_tu_duy', (select id from public.historical_events where slug = 'tong-tien-cong-va-noi-day-tet-mau-than-1968'), 'SGK Lịch sử 12 (KNTT), Bài 8, mục 2')
