update public.exam_items set content_key = 'b8-m2-tn-06'
 where content_key is null and fingerprint = public.exam_item_fingerprint('mcq', 'Theo Điều 1 của Hiệp định Pa-ri (27-1-1973), Hoa Kỳ và các nước khác cam kết tôn trọng', array['quyền của Mỹ được duy trì quân đội ở miền Nam Việt Nam', 'sự chia cắt lâu dài giữa hai miền Nam – Bắc Việt Nam', 'độc lập, chủ quyền, thống nhất, toàn vẹn lãnh thổ của Việt Nam', 'quyền tự quyết của riêng chính quyền Sài Gòn'], null)
   and not exists (select 1 from public.exam_items where content_key = 'b8-m2-tn-06');
insert into public.exam_items (content_key, kind, stem, passage_id, choices, correct_index, statements, choice_notes, explanation, remember, grade, lesson_slug, section_id, topic_tag, level, competency, event_id, source_note)
values ('b8-m2-tn-06', 'mcq', 'Theo Điều 1 của Hiệp định Pa-ri (27-1-1973), Hoa Kỳ và các nước khác cam kết tôn trọng', (select id from public.exam_passages where title = 'Hiệp định Pa-ri về chấm dứt chiến tranh, lập lại hòa bình ở Việt Nam (27-1-1973)' and body = 'Điều 1 của Hiệp định ghi: “Hoa Kỳ và các nước khác tôn trọng độc lập, chủ quyền, thống nhất, toàn vẹn lãnh thổ của nước Việt Nam như Hiệp định Giơ-ne-vơ năm 1954 về Việt Nam đã công nhận.”
Hiệp định còn quy định: Hoa Kỳ rút hết quân đội của mình và quân các nước đồng minh trong vòng 60 ngày kể từ khi kí hiệp định, hủy bỏ các căn cứ quân sự của Mỹ, cam kết không tiếp tục can thiệp quân sự hoặc can thiệp vào công việc nội bộ của miền Nam Việt Nam; nhân dân miền Nam Việt Nam tự quyết định tương lai chính trị của họ thông qua tổng tuyển cử thực sự tự do, dân chủ; các bên trao trả tù binh và dân thường bị bắt; Hoa Kỳ cam kết góp phần hàn gắn vết thương chiến tranh ở Việt Nam.' order by created_at limit 1), array['quyền của Mỹ được duy trì quân đội ở miền Nam Việt Nam', 'sự chia cắt lâu dài giữa hai miền Nam – Bắc Việt Nam', 'độc lập, chủ quyền, thống nhất, toàn vẹn lãnh thổ của Việt Nam', 'quyền tự quyết của riêng chính quyền Sài Gòn'], 2, null, '[{"note":"Trái tư liệu: hiệp định quy định Hoa Kỳ rút hết quân đội và quân đồng minh trong vòng 60 ngày.","section_id":"muc-2","trap":"ban_chat"},{"note":"Trái tư liệu: Điều 1 khẳng định tôn trọng sự “thống nhất” của nước Việt Nam.","section_id":"muc-2","trap":"ban_chat"},{"note":"Đúng. “Hoa Kỳ và các nước khác tôn trọng độc lập, chủ quyền, thống nhất, toàn vẹn lãnh thổ của nước Việt Nam như Hiệp định Giơ-ne-vơ năm 1954 về Việt Nam đã công nhận.”","section_id":"muc-2"},{"note":"Đánh tráo chủ thể: hiệp định quy định “nhân dân miền Nam Việt Nam” tự quyết định tương lai chính trị qua tổng tuyển cử.","section_id":"muc-2","trap":"chu_the"}]'::jsonb, 'Câu đọc hiểu điều khoản quan trọng nhất của Hiệp định Pa-ri.', 'Hiệp định Pa-ri, Điều 1: Hoa Kỳ tôn trọng độc lập, chủ quyền, thống nhất, toàn vẹn lãnh thổ của Việt Nam.', 12, '8-khang-chien-chong-my-cuu-nuoc', 'muc-2', null, 'nhan_biet', 'tim_hieu_lich_su', (select id from public.historical_events where slug = 'hiep-dinh-paris-ve-viet-nam'), 'SGK Lịch sử 12 (KNTT), Bài 8, mục 2')
