 where content_key is null and fingerprint = public.exam_item_fingerprint('mcq', 'Đoạn trích Lời kêu gọi ngày 17-7-1966 của Chủ tịch Hồ Chí Minh thể hiện rõ nhất điều gì?', array['Quyết tâm chiến đấu lâu dài để giữ độc lập, tự do', 'Mong muốn sớm kết thúc chiến tranh bằng mọi giá', 'Chủ trương tránh để chiến tranh lan ra miền Bắc', 'Kêu gọi chỉ tập trung bảo vệ miền Bắc'], null)
   and not exists (select 1 from public.exam_items where content_key = 'b8-m2-tn-07');
insert into public.exam_items (content_key, kind, stem, passage_id, choices, correct_index, statements, choice_notes, explanation, remember, grade, lesson_slug, section_id, topic_tag, level, competency, event_id, source_note)
values ('b8-m2-tn-07', 'mcq', 'Đoạn trích Lời kêu gọi ngày 17-7-1966 của Chủ tịch Hồ Chí Minh thể hiện rõ nhất điều gì?', (select id from public.exam_passages where title = 'Lời kêu gọi đồng bào và chiến sĩ cả nước (17-7-1966)' and body = '“Chiến tranh có thể kéo dài 5 năm, 10 năm, 20 năm hoặc lâu hơn nữa. Hà Nội, Hải Phòng và một số thành phố, xí nghiệp có thể bị tàn phá, song nhân dân Việt Nam quyết không sợ! Không có gì quý hơn độc lập, tự do. Đến ngày thắng lợi, nhân dân ta sẽ xây dựng lại đất nước ta đàng hoàng hơn, to đẹp hơn!”' order by created_at limit 1), array['Quyết tâm chiến đấu lâu dài để giữ độc lập, tự do', 'Mong muốn sớm kết thúc chiến tranh bằng mọi giá', 'Chủ trương tránh để chiến tranh lan ra miền Bắc', 'Kêu gọi chỉ tập trung bảo vệ miền Bắc'], 0, null, '[{"note":"Đúng. Sẵn sàng chịu đựng chiến tranh lâu dài, thành phố bị tàn phá — “nhân dân Việt Nam quyết không sợ! Không có gì quý hơn độc lập, tự do.”","section_id":"muc-2"},{"note":"Trái tư liệu: “chiến tranh có thể kéo dài 5 năm, 10 năm, 20 năm hoặc lâu hơn nữa” — ta sẵn sàng đánh lâu dài, không kết thúc bằng mọi giá.","section_id":"muc-2","trap":"ban_chat"},{"note":"Trái tư liệu: lời kêu gọi đã tính tới việc Hà Nội, Hải Phòng có thể bị tàn phá — chiến tranh đã lan ra miền Bắc (chiến tranh phá hoại của Mỹ).","section_id":"muc-2","trap":"ban_chat"},{"note":"Thu hẹp sai: lời kêu gọi gửi đồng bào và chiến sĩ cả nước, vì độc lập, tự do của cả dân tộc — không chỉ bảo vệ miền Bắc.","section_id":"muc-2","trap":"tuyet_doi"}]'::jsonb, 'Câu đọc hiểu tinh thần của Lời kêu gọi năm 1966.', '“Không có gì quý hơn độc lập, tự do.” (Hồ Chí Minh, 17-7-1966)', 12, '8-khang-chien-chong-my-cuu-nuoc', 'muc-2', null, 'thong_hieu', 'nhan_thuc_tu_duy', null, 'SGK Lịch sử 12 (KNTT), Bài 8, mục 2')
