update public.exam_items set content_key = 'b8-m2-tn-08'
 where content_key is null and fingerprint = public.exam_item_fingerprint('mcq', 'Chân lí “Không có gì quý hơn độc lập, tự do” trong đoạn tư liệu có giá trị như thế nào đối với Việt Nam ngày nay?', array['Chủ yếu là bài học quân sự cho thời chiến', 'Đề cao tự do của mỗi cá nhân hơn lợi ích của dân tộc', 'Khẳng định Việt Nam không cần hợp tác với bất kì nước nào', 'Là động lực bảo vệ chủ quyền và xây dựng đất nước vững mạnh'], null)
   and not exists (select 1 from public.exam_items where content_key = 'b8-m2-tn-08');
insert into public.exam_items (content_key, kind, stem, passage_id, choices, correct_index, statements, choice_notes, explanation, remember, grade, lesson_slug, section_id, topic_tag, level, competency, event_id, source_note)
values ('b8-m2-tn-08', 'mcq', 'Chân lí “Không có gì quý hơn độc lập, tự do” trong đoạn tư liệu có giá trị như thế nào đối với Việt Nam ngày nay?', (select id from public.exam_passages where title = 'Lời kêu gọi đồng bào và chiến sĩ cả nước (17-7-1966)' and body = '“Chiến tranh có thể kéo dài 5 năm, 10 năm, 20 năm hoặc lâu hơn nữa. Hà Nội, Hải Phòng và một số thành phố, xí nghiệp có thể bị tàn phá, song nhân dân Việt Nam quyết không sợ! Không có gì quý hơn độc lập, tự do. Đến ngày thắng lợi, nhân dân ta sẽ xây dựng lại đất nước ta đàng hoàng hơn, to đẹp hơn!”' order by created_at limit 1), array['Chủ yếu là bài học quân sự cho thời chiến', 'Đề cao tự do của mỗi cá nhân hơn lợi ích của dân tộc', 'Khẳng định Việt Nam không cần hợp tác với bất kì nước nào', 'Là động lực bảo vệ chủ quyền và xây dựng đất nước vững mạnh'], 3, null, '[{"note":"Tuyệt đối hóa: độc lập, tự do vẫn là giá trị cốt lõi khi bảo vệ chủ quyền biên giới, biển đảo và phát triển đất nước hiện nay.","section_id":"muc-4","trap":"tuyet_doi"},{"note":"Nhầm khái niệm: “độc lập, tự do” ở đây là của dân tộc, đất nước — không đặt tự do cá nhân lên trên lợi ích dân tộc.","section_id":"muc-2","trap":"khai_niem"},{"note":"Hiểu sai: giữ độc lập không có nghĩa là đóng cửa; Việt Nam hiện nay độc lập, tự chủ và chủ động hội nhập quốc tế.","lesson_slug":"14-doi-ngoai-tu-nam-1975-den-nay","section_id":"muc-2","trap":"ban_chat"},{"note":"Đúng. Chân lí ấy vẫn là động lực, là mục tiêu trong sự nghiệp bảo vệ chủ quyền, xây dựng và phát triển đất nước hôm nay.","section_id":"muc-4"}]'::jsonb, 'Câu liên hệ: giá trị lâu dài của tư tưởng độc lập, tự do.', 'Độc lập, tự do — giá trị cốt lõi từ kháng chiến đến bảo vệ và xây dựng đất nước hôm nay.', 12, '8-khang-chien-chong-my-cuu-nuoc', 'muc-2', null, 'van_dung', 'van_dung_kien_thuc', null, 'SGK Lịch sử 12 (KNTT), Bài 8, mục 2')
