insert into public.exam_items (content_key, kind, stem, passage_id, choices, correct_index, statements, choice_notes, explanation, remember, grade, lesson_slug, section_id, topic_tag, level, competency, event_id, source_note)
values ('b8-m2-tn-09', 'mcq', 'Trận “Điện Biên Phủ trên không” cuối năm 1972 diễn ra chủ yếu ở', null, array['Sài Gòn, Biên Hòa và các tỉnh Nam Bộ', 'Điện Biên Phủ và các tỉnh Tây Bắc', 'Quảng Trị, Thừa Thiên Huế và Đà Nẵng', 'Hà Nội, Hải Phòng và một số địa phương miền Bắc'], 3, null, '[{"note":"Sài Gòn và Nam Bộ không phải nơi Mỹ dùng B-52 tập kích chiến lược tháng 12-1972.","section_id":"muc-2","trap":"dia_diem"},{"note":"Nhầm địa điểm: “Điện Biên Phủ trên không” là cách gọi so sánh với chiến thắng Điện Biên Phủ năm 1954 — trận đánh không diễn ra ở Điện Biên Phủ.","lesson_slug":"7-khang-chien-chong-phap","section_id":"muc-3","trap":"dia_diem"},{"note":"Quảng Trị, Thừa Thiên Huế là hướng chủ yếu của cuộc Tiến công chiến lược năm 1972, không phải nơi diễn ra trận “Điện Biên Phủ trên không”.","section_id":"muc-2","trap":"dia_diem"},{"note":"Đúng. Trong 12 ngày đêm (18 – 29-12-1972), quân dân miền Bắc, trọng tâm là Hà Nội và Hải Phòng, đánh bại cuộc tập kích chiến lược bằng B-52 của Mỹ.","section_id":"muc-2"}]'::jsonb, '“Điện Biên Phủ trên không” buộc Mỹ trở lại bàn đàm phán và kí Hiệp định Pa-ri (1-1973).', '“Điện Biên Phủ trên không”: 12 ngày đêm (18 – 29-12-1972), Hà Nội – Hải Phòng.', 12, '8-khang-chien-chong-my-cuu-nuoc', 'muc-2', null, 'nhan_biet', 'tim_hieu_lich_su', (select id from public.historical_events where slug = 'ha-noi-dien-bien-phu-tren-khong-1972'), 'SGK Lịch sử 12 (KNTT), Bài 8, mục 2')
