update public.exam_items set content_key = 'b8-m3-ds-01'
 where content_key is null and fingerprint = public.exam_item_fingerprint('true_false', 'Đọc đoạn tư liệu về cuộc Tổng tiến công và nổi dậy Xuân 1975 và xác định mỗi ý sau đúng hay sai.', null, '[{"text":"Chiến dịch Tây Nguyên mở đầu cuộc Tổng tiến công và nổi dậy Xuân 1975.","is_true":true,"explanation":"Chiến dịch Tây Nguyên (4-3 → 24-3-1975) là chiến dịch đầu tiên trong ba chiến dịch lớn.","section_id":"muc-3"},{"text":"Huế được giải phóng sau Sài Gòn.","is_true":false,"explanation":"Sai thời gian: Huế giải phóng ngày 26-3, Sài Gòn ngày 30-4-1975.","section_id":"muc-3","trap":"thoi_gian"},{"text":"Chính quyền Sài Gòn tuyên bố đầu hàng không điều kiện ngày 30-4-1975.","is_true":true,"explanation":"Tư liệu nêu rõ điều này.","section_id":"muc-3"},{"text":"Đến ngày 30-4-1975, toàn bộ các tỉnh miền Nam đã được giải phóng.","is_true":false,"explanation":"Sai thời gian: ngày 2-5-1975, Châu Đốc mới là tỉnh cuối cùng được giải phóng.","section_id":"muc-3","trap":"thoi_gian"}]'::jsonb)
   and not exists (select 1 from public.exam_items where content_key = 'b8-m3-ds-01');
insert into public.exam_items (content_key, kind, stem, passage_id, choices, correct_index, statements, choice_notes, explanation, remember, grade, lesson_slug, section_id, topic_tag, level, competency, event_id, source_note)
values ('b8-m3-ds-01', 'true_false', 'Đọc đoạn tư liệu về cuộc Tổng tiến công và nổi dậy Xuân 1975 và xác định mỗi ý sau đúng hay sai.', (select id from public.exam_passages where title = 'Cuộc Tổng tiến công và nổi dậy Xuân 1975' and body = 'Cuối năm 1974 – đầu năm 1975, Bộ Chính trị đề ra kế hoạch giải phóng miền Nam trong hai năm 1975 và 1976, đồng thời nhấn mạnh: nếu thời cơ đến vào đầu hoặc cuối năm 1975 thì lập tức giải phóng miền Nam trong năm 1975. Chiến thắng Phước Long (6-1-1975) cho thấy khả năng can thiệp trở lại của Mỹ là rất hạn chế.
Cuộc Tổng tiến công và nổi dậy Xuân 1975 diễn ra qua ba chiến dịch lớn. Chiến dịch Tây Nguyên (4-3 đến 24-3-1975) mở đầu bằng trận then chốt đánh vào Buôn Ma Thuột. Chiến dịch Huế – Đà Nẵng (21-3 đến 29-3-1975) giải phóng Huế (26-3) và Đà Nẵng (29-3). Sau hai chiến dịch này, lực lượng của ta có ưu thế áp đảo. Chiến dịch Hồ Chí Minh bắt đầu từ chiều ngày 26-4-1975; 11 giờ 30 phút ngày 30-4-1975, lá cờ cách mạng tung bay trên nóc Dinh Độc Lập, chính quyền Sài Gòn tuyên bố đầu hàng không điều kiện. Ngày 2-5-1975, Châu Đốc là tỉnh cuối cùng của miền Nam được giải phóng.' order by created_at limit 1), null, null, '[{"text":"Chiến dịch Tây Nguyên mở đầu cuộc Tổng tiến công và nổi dậy Xuân 1975.","is_true":true,"explanation":"Chiến dịch Tây Nguyên (4-3 → 24-3-1975) là chiến dịch đầu tiên trong ba chiến dịch lớn.","section_id":"muc-3"},{"text":"Huế được giải phóng sau Sài Gòn.","is_true":false,"explanation":"Sai thời gian: Huế giải phóng ngày 26-3, Sài Gòn ngày 30-4-1975.","section_id":"muc-3","trap":"thoi_gian"},{"text":"Chính quyền Sài Gòn tuyên bố đầu hàng không điều kiện ngày 30-4-1975.","is_true":true,"explanation":"Tư liệu nêu rõ điều này.","section_id":"muc-3"},{"text":"Đến ngày 30-4-1975, toàn bộ các tỉnh miền Nam đã được giải phóng.","is_true":false,"explanation":"Sai thời gian: ngày 2-5-1975, Châu Đốc mới là tỉnh cuối cùng được giải phóng.","section_id":"muc-3","trap":"thoi_gian"}]'::jsonb, null, 'Câu đọc hiểu trình tự và các mốc của cuộc Tổng tiến công Xuân 1975.', 'Xuân 1975: Tây Nguyên → Huế – Đà Nẵng → Hồ Chí Minh (30-4); Châu Đốc giải phóng ngày 2-5-1975.', 12, '8-khang-chien-chong-my-cuu-nuoc', 'muc-3', null, 'thong_hieu', 'nhan_thuc_tu_duy', (select id from public.historical_events where slug = 'chien-dich-ho-chi-minh'), 'SGK Lịch sử 12 (KNTT), Bài 8, mục 3')
