 where content_key is null and fingerprint = public.exam_item_fingerprint('true_false', 'Cho thông tin: “Ngày 6-1-1975, quân dân ta giải phóng thị xã và toàn tỉnh Phước Long.” Mỗi ý sau đây đúng hay sai?', null, '[{"text":"Phước Long là tỉnh đầu tiên ở miền Nam được giải phóng hoàn toàn.","is_true":true,"explanation":"Phước Long là tỉnh đầu tiên được giải phóng hoàn toàn, trước cuộc Tổng tiến công Xuân 1975.","section_id":"muc-3"},{"text":"Sau Phước Long, Mỹ đưa quân trở lại trực tiếp tham chiến ở miền Nam.","is_true":false,"explanation":"Sai bản chất: Mỹ chỉ phản ứng yếu ớt — điều đó cho thấy khả năng can thiệp trở lại của Mỹ rất hạn chế.","section_id":"muc-3","trap":"ban_chat"},{"text":"Thắng lợi Phước Long góp phần giúp Bộ Chính trị hạ quyết tâm giải phóng miền Nam.","is_true":true,"explanation":"Từ thắng lợi này, Bộ Chính trị bổ sung, hoàn chỉnh kế hoạch giải phóng miền Nam.","section_id":"muc-3"},{"text":"Chiến thắng Phước Long diễn ra sau chiến dịch Tây Nguyên.","is_true":false,"explanation":"Sai thời gian: Phước Long (đầu tháng 1-1975) trước chiến dịch Tây Nguyên (tháng 3-1975).","section_id":"muc-3","trap":"thoi_gian"}]'::jsonb)
   and not exists (select 1 from public.exam_items where content_key = 'b8-m3-ds-02');
