values ('b8-m3-tn-04', 'mcq', 'Từ đoạn tư liệu, có thể nhận xét gì về kế hoạch giải phóng miền Nam của Bộ Chính trị?', (select id from public.exam_passages where title = 'Cuộc Tổng tiến công và nổi dậy Xuân 1975' and body = 'Cuối năm 1974 – đầu năm 1975, Bộ Chính trị đề ra kế hoạch giải phóng miền Nam trong hai năm 1975 và 1976, đồng thời nhấn mạnh: nếu thời cơ đến vào đầu hoặc cuối năm 1975 thì lập tức giải phóng miền Nam trong năm 1975. Chiến thắng Phước Long (6-1-1975) cho thấy khả năng can thiệp trở lại của Mỹ là rất hạn chế.
Cuộc Tổng tiến công và nổi dậy Xuân 1975 diễn ra qua ba chiến dịch lớn. Chiến dịch Tây Nguyên (4-3 đến 24-3-1975) mở đầu bằng trận then chốt đánh vào Buôn Ma Thuột. Chiến dịch Huế – Đà Nẵng (21-3 đến 29-3-1975) giải phóng Huế (26-3) và Đà Nẵng (29-3). Sau hai chiến dịch này, lực lượng của ta có ưu thế áp đảo. Chiến dịch Hồ Chí Minh bắt đầu từ chiều ngày 26-4-1975; 11 giờ 30 phút ngày 30-4-1975, lá cờ cách mạng tung bay trên nóc Dinh Độc Lập, chính quyền Sài Gòn tuyên bố đầu hàng không điều kiện. Ngày 2-5-1975, Châu Đốc là tỉnh cuối cùng của miền Nam được giải phóng.' order by created_at limit 1), array['Cứng nhắc, chỉ đặt mục tiêu giải phóng miền Nam trong năm 1976', 'Có kế hoạch cơ bản, lại linh hoạt chớp thời cơ ngay năm 1975', 'Chỉ nhằm giải phóng Tây Nguyên, chưa tính tới Sài Gòn', 'Chờ Mỹ rút hết quân mới đề ra kế hoạch giải phóng'], 1, null, '[{"note":"Trái tư liệu: kế hoạch dự kiến hai năm 1975 – 1976 nhưng nhấn mạnh nếu thời cơ đến thì giải phóng ngay trong năm 1975.","section_id":"muc-3","trap":"ban_chat"},{"note":"Đúng. Kế hoạch hai năm nhưng có dự kiến thời cơ để giải phóng miền Nam ngay năm 1975 — vì vậy ta chớp được thời cơ sau Tây Nguyên, Huế – Đà Nẵng.","section_id":"muc-3"},{"note":"Tuyệt đối hóa sai: Tây Nguyên chỉ là hướng mở đầu; mục tiêu là giải phóng toàn bộ miền Nam.","section_id":"muc-3","trap":"tuyet_doi"},{"note":"Sai thời gian: quân Mỹ đã rút hết khỏi miền Nam từ năm 1973, theo Hiệp định Pa-ri.","section_id":"muc-2","trap":"thoi_gian"}]'::jsonb, 'Câu nhận xét: sự kết hợp giữa kế hoạch và chớp thời cơ trong chỉ đạo năm 1975.', 'Kế hoạch năm 1975: hai năm 1975 – 1976, nhưng thời cơ đến thì giải phóng ngay trong năm 1975.', 12, '8-khang-chien-chong-my-cuu-nuoc', 'muc-3', null, 'van_dung', 'nhan_thuc_tu_duy', null, 'SGK Lịch sử 12 (KNTT), Bài 8, mục 3')
