 where content_key is null and fingerprint = public.exam_item_fingerprint('mcq', 'Việc chiến dịch Hồ Chí Minh giành toàn thắng chỉ sau 5 ngày (26-4 → 30-4-1975) cho thấy điều gì?', array['Quân đội Sài Gòn hoàn toàn không kháng cự', 'Ta chỉ dựa vào yếu tố bất ngờ về thời điểm', 'Thế và lực của ta đã áp đảo, ta chớp đúng thời cơ chiến lược', 'Ta chỉ dựa vào nổi dậy của quần chúng, không cần lực lượng vũ trang'], null)
   and not exists (select 1 from public.exam_items where content_key = 'b8-m3-tn-06');
insert into public.exam_items (content_key, kind, stem, passage_id, choices, correct_index, statements, choice_notes, explanation, remember, grade, lesson_slug, section_id, topic_tag, level, competency, event_id, source_note)
values ('b8-m3-tn-06', 'mcq', 'Việc chiến dịch Hồ Chí Minh giành toàn thắng chỉ sau 5 ngày (26-4 → 30-4-1975) cho thấy điều gì?', (select id from public.exam_passages where title = 'Cuộc Tổng tiến công và nổi dậy Xuân 1975' and body = 'Cuối năm 1974 – đầu năm 1975, Bộ Chính trị đề ra kế hoạch giải phóng miền Nam trong hai năm 1975 và 1976, đồng thời nhấn mạnh: nếu thời cơ đến vào đầu hoặc cuối năm 1975 thì lập tức giải phóng miền Nam trong năm 1975. Chiến thắng Phước Long (6-1-1975) cho thấy khả năng can thiệp trở lại của Mỹ là rất hạn chế.
Cuộc Tổng tiến công và nổi dậy Xuân 1975 diễn ra qua ba chiến dịch lớn. Chiến dịch Tây Nguyên (4-3 đến 24-3-1975) mở đầu bằng trận then chốt đánh vào Buôn Ma Thuột. Chiến dịch Huế – Đà Nẵng (21-3 đến 29-3-1975) giải phóng Huế (26-3) và Đà Nẵng (29-3). Sau hai chiến dịch này, lực lượng của ta có ưu thế áp đảo. Chiến dịch Hồ Chí Minh bắt đầu từ chiều ngày 26-4-1975; 11 giờ 30 phút ngày 30-4-1975, lá cờ cách mạng tung bay trên nóc Dinh Độc Lập, chính quyền Sài Gòn tuyên bố đầu hàng không điều kiện. Ngày 2-5-1975, Châu Đốc là tỉnh cuối cùng của miền Nam được giải phóng.' order by created_at limit 1), array['Quân đội Sài Gòn hoàn toàn không kháng cự', 'Ta chỉ dựa vào yếu tố bất ngờ về thời điểm', 'Thế và lực của ta đã áp đảo, ta chớp đúng thời cơ chiến lược', 'Ta chỉ dựa vào nổi dậy của quần chúng, không cần lực lượng vũ trang'], 2, null, '[{"note":"Tuyệt đối hóa: quân đội Sài Gòn vẫn chống cự ở nhiều nơi (như tuyến phòng thủ Xuân Lộc trước đó); ta thắng nhanh vì thế và lực áp đảo.","section_id":"muc-3","trap":"tuyet_doi"},{"note":"Tuyệt đối hóa: bất ngờ là một yếu tố, nhưng quyết định là ưu thế áp đảo về thế và lực sau Tây Nguyên, Huế – Đà Nẵng.","section_id":"muc-3","trap":"tuyet_doi"},{"note":"Đúng. Sau Tây Nguyên và Huế – Đà Nẵng, ta có thế và lực vượt trội, tập trung lực lượng lớn, chớp đúng thời cơ để giải phóng Sài Gòn nhanh chóng.","section_id":"muc-3"},{"note":"Tuyệt đối hóa: Xuân 1975 là cuộc “tổng tiến công và nổi dậy” — kết hợp tiến công của các quân đoàn chủ lực với nổi dậy của quần chúng.","section_id":"muc-3","trap":"tuyet_doi"}]'::jsonb, 'Câu đánh giá nguyên nhân thắng lợi nhanh chóng của chiến dịch Hồ Chí Minh.', 'Chiến dịch Hồ Chí Minh: 5 ngày, thắng nhờ thế và lực áp đảo, chớp đúng thời cơ.', 12, '8-khang-chien-chong-my-cuu-nuoc', 'muc-3', null, 'van_dung', 'nhan_thuc_tu_duy', (select id from public.historical_events where slug = 'chien-dich-ho-chi-minh'), 'SGK Lịch sử 12 (KNTT), Bài 8, mục 3')
