insert into public.exam_items (content_key, kind, stem, passage_id, choices, correct_index, statements, choice_notes, explanation, remember, grade, lesson_slug, section_id, topic_tag, level, competency, event_id, source_note)
values ('b8-m3-tn-07', 'mcq', 'Điểm giống nhau giữa Cách mạng tháng Tám năm 1945 và cuộc Tổng tiến công và nổi dậy Xuân 1975 là', null, array['đều kết thúc bằng việc kí một hiệp định quốc tế', 'đều chớp thời cơ, kết hợp vũ trang với nổi dậy của quần chúng', 'đều diễn ra chủ yếu ở vùng nông thôn, rừng núi', 'đều có quân Đồng minh hỗ trợ trực tiếp trên chiến trường'], 1, null, '[{"note":"Sai bản chất: năm 1945 là tổng khởi nghĩa giành chính quyền, năm 1975 là tổng tiến công và nổi dậy — đều không kết thúc bằng hiệp định.","section_id":"muc-3","trap":"ban_chat"},{"note":"Đúng. Năm 1945 và năm 1975, Đảng đều chớp đúng thời cơ; thắng lợi là sự kết hợp giữa lực lượng vũ trang và nổi dậy của quần chúng.","section_id":"muc-3"},{"note":"Sai địa điểm: cả hai đều có thắng lợi quyết định ở các đô thị lớn (Hà Nội, Huế, Sài Gòn năm 1945; Huế, Đà Nẵng, Sài Gòn năm 1975).","section_id":"muc-3","trap":"dia_diem"},{"note":"Sai chủ thể: năm 1945 Đồng minh chỉ tạo thời cơ; năm 1975 không có quân nước ngoài chiến đấu cùng ta.","lesson_slug":"6-cach-mang-thang-tam-nam-1945","section_id":"muc-2","trap":"chu_the"}]'::jsonb, 'Câu so sánh hai thắng lợi lớn của cách mạng Việt Nam.', '1945 và 1975: chớp thời cơ + kết hợp lực lượng vũ trang với nổi dậy của quần chúng.', 12, '8-khang-chien-chong-my-cuu-nuoc', 'muc-3', null, 'van_dung', 'van_dung_kien_thuc', null, 'SGK Lịch sử 12 (KNTT), Bài 8, mục 3')
