values ('b8-m3-tn-08', 'mcq', 'Vì sao năm 1975 Bộ Chính trị chọn Tây Nguyên làm hướng tiến công chủ yếu?', null, array['Tây Nguyên là nơi tập trung đông quân Mỹ nhất ở miền Nam', 'Tây Nguyên là nơi địch tập trung quân chủ lực mạnh nhất', 'Tây Nguyên có vị trí chiến lược quan trọng nhưng địch bố phòng sơ hở', 'Tây Nguyên là địa bàn gần hậu phương miền Bắc nhất'], 2, null, '[{"note":"Sai thời gian: quân chiến đấu Mỹ đã rút hết khỏi miền Nam từ tháng 3-1973, theo Hiệp định Pa-ri.","section_id":"muc-2","trap":"thoi_gian"},{"note":"Ngược lại: ở Tây Nguyên địch bố phòng có nhiều sơ hở; lực lượng mạnh của địch tập trung ở Huế – Đà Nẵng và quanh Sài Gòn.","section_id":"muc-3","trap":"ban_chat"},{"note":"Đúng. Tây Nguyên là địa bàn chiến lược quan trọng, đánh chiếm được sẽ chia cắt miền Nam; trong khi đó địch ở đây bố phòng có nhiều sơ hở.","section_id":"muc-3"},{"note":"Sai địa điểm: Quảng Trị, Thừa Thiên Huế mới gần miền Bắc hơn; Tây Nguyên được chọn vì vị trí chiến lược, đánh chiếm được sẽ chia cắt miền Nam.","section_id":"muc-3","trap":"dia_diem"}]'::jsonb, 'Câu giải thích lựa chọn hướng tiến công chiến lược năm 1975.', 'Tây Nguyên: vị trí chiến lược quan trọng, địch bố phòng sơ hở → hướng tiến công chủ yếu năm 1975.', 12, '8-khang-chien-chong-my-cuu-nuoc', 'muc-3', null, 'van_dung', 'van_dung_kien_thuc', null, 'SGK Lịch sử 12 (KNTT), Bài 8, mục 3')
