 where content_key is null and fingerprint = public.exam_item_fingerprint('true_false', 'Cho thông tin: “Ngày 30-4-1975, chiến dịch Hồ Chí Minh toàn thắng; đến ngày 2-5-1975, miền Nam hoàn toàn giải phóng.” Mỗi ý sau đây về ý nghĩa của thắng lợi này đúng hay sai?', null, '[{"text":"Thắng lợi kết thúc 21 năm kháng chiến chống Mỹ, cứu nước.","is_true":true,"explanation":"Cuộc kháng chiến kéo dài từ năm 1954 đến năm 1975.","section_id":"muc-4"},{"text":"Ngay sau ngày 30-4-1975, Việt Nam đã hoàn thành thống nhất đất nước về mặt nhà nước.","is_true":false,"explanation":"Sai thời gian: thống nhất về mặt nhà nước được hoàn thành năm 1976 (Quốc hội chung của cả nước).","section_id":"muc-4","trap":"thoi_gian"},{"text":"Thắng lợi mở ra kỉ nguyên đất nước độc lập, thống nhất, đi lên chủ nghĩa xã hội.","is_true":true,"explanation":"Đây là ý nghĩa trong nước của thắng lợi năm 1975.","section_id":"muc-4"},{"text":"Thắng lợi chỉ có ý nghĩa đối với Việt Nam, không ảnh hưởng tới thế giới.","is_true":false,"explanation":"Tuyệt đối hóa: thắng lợi tác động mạnh tới nước Mỹ và thế giới, cổ vũ phong trào giải phóng dân tộc.","section_id":"muc-4","trap":"tuyet_doi"}]'::jsonb)
   and not exists (select 1 from public.exam_items where content_key = 'b8-m4-ds-01');
