update public.exam_items set content_key = 'b8-m4-ds-02'
 where content_key is null and fingerprint = public.exam_item_fingerprint('true_false', 'Dựa vào đoạn tư liệu về nguyên nhân thắng lợi và ý nghĩa của cuộc kháng chiến chống Mỹ, cứu nước, hãy cho biết mỗi ý sau đúng hay sai.', null, '[{"text":"Hậu phương miền Bắc xã hội chủ nghĩa là một nguyên nhân quan trọng của thắng lợi.","is_true":true,"explanation":"Tư liệu: hậu phương miền Bắc “đáp ứng kịp thời yêu cầu của tiền tuyến miền Nam”.","section_id":"muc-4"},{"text":"Theo tư liệu, nguyên nhân quyết định thắng lợi là sự giúp đỡ của Liên Xô và Trung Quốc.","is_true":false,"explanation":"Đánh giá sai vai trò: tư liệu nêu sự giúp đỡ quốc tế “bên cạnh” các nguyên nhân bên trong; đó là nguyên nhân khách quan.","section_id":"muc-4","trap":"nhan_qua"},{"text":"Thắng lợi năm 1975 hoàn thành cuộc cách mạng dân tộc dân chủ nhân dân trên cả nước.","is_true":true,"explanation":"Tư liệu nêu rõ ý nghĩa này.","section_id":"muc-4"},{"text":"Bài học đoàn kết quốc tế không còn ý nghĩa khi Việt Nam đã hòa bình, thống nhất.","is_true":false,"explanation":"Hiểu sai: đoàn kết, hợp tác quốc tế vẫn là nguồn sức mạnh quan trọng trong bảo vệ và xây dựng đất nước hiện nay.","section_id":"muc-4","trap":"ban_chat"}]'::jsonb)
   and not exists (select 1 from public.exam_items where content_key = 'b8-m4-ds-02');
insert into public.exam_items (content_key, kind, stem, passage_id, choices, correct_index, statements, choice_notes, explanation, remember, grade, lesson_slug, section_id, topic_tag, level, competency, event_id, source_note)
values ('b8-m4-ds-02', 'true_false', 'Dựa vào đoạn tư liệu về nguyên nhân thắng lợi và ý nghĩa của cuộc kháng chiến chống Mỹ, cứu nước, hãy cho biết mỗi ý sau đúng hay sai.', (select id from public.exam_passages where title = 'Nguyên nhân thắng lợi và ý nghĩa của cuộc kháng chiến chống Mỹ, cứu nước' and body = 'Cuộc kháng chiến chống Mỹ, cứu nước thắng lợi nhờ sự lãnh đạo của Đảng, đứng đầu là Chủ tịch Hồ Chí Minh, với đường lối tiến hành đồng thời cách mạng xã hội chủ nghĩa ở miền Bắc và cách mạng dân tộc dân chủ nhân dân ở miền Nam. Nhân dân hai miền đoàn kết, giàu lòng yêu nước; hậu phương miền Bắc xã hội chủ nghĩa đáp ứng kịp thời yêu cầu của tiền tuyến miền Nam. Bên cạnh đó là tình đoàn kết chiến đấu của ba dân tộc Đông Dương và sự đồng tình, ủng hộ, giúp đỡ của Liên Xô, Trung Quốc, các nước xã hội chủ nghĩa, nhân dân tiến bộ trên thế giới, trong đó có nhân dân Mỹ.
Thắng lợi đã kết thúc 21 năm kháng chiến chống Mỹ và 30 năm chiến tranh giải phóng dân tộc (1945 – 1975), hoàn thành cuộc cách mạng dân tộc dân chủ nhân dân trên cả nước, mở ra kỉ nguyên đất nước độc lập, thống nhất, đi lên chủ nghĩa xã hội. Thắng lợi tác động mạnh mẽ tới tình hình nước Mỹ và thế giới, cổ vũ phong trào giải phóng dân tộc.' order by created_at limit 1), null, null, '[{"text":"Hậu phương miền Bắc xã hội chủ nghĩa là một nguyên nhân quan trọng của thắng lợi.","is_true":true,"explanation":"Tư liệu: hậu phương miền Bắc “đáp ứng kịp thời yêu cầu của tiền tuyến miền Nam”.","section_id":"muc-4"},{"text":"Theo tư liệu, nguyên nhân quyết định thắng lợi là sự giúp đỡ của Liên Xô và Trung Quốc.","is_true":false,"explanation":"Đánh giá sai vai trò: tư liệu nêu sự giúp đỡ quốc tế “bên cạnh” các nguyên nhân bên trong; đó là nguyên nhân khách quan.","section_id":"muc-4","trap":"nhan_qua"},{"text":"Thắng lợi năm 1975 hoàn thành cuộc cách mạng dân tộc dân chủ nhân dân trên cả nước.","is_true":true,"explanation":"Tư liệu nêu rõ ý nghĩa này.","section_id":"muc-4"},{"text":"Bài học đoàn kết quốc tế không còn ý nghĩa khi Việt Nam đã hòa bình, thống nhất.","is_true":false,"explanation":"Hiểu sai: đoàn kết, hợp tác quốc tế vẫn là nguồn sức mạnh quan trọng trong bảo vệ và xây dựng đất nước hiện nay.","section_id":"muc-4","trap":"ban_chat"}]'::jsonb, null, 'Câu đọc hiểu và vận dụng: nguyên nhân, ý nghĩa, bài học của kháng chiến chống Mỹ.', 'Thắng lợi 1975: nhân tố bên trong quyết định; hậu phương miền Bắc, đoàn kết quốc tế góp phần quan trọng.', 12, '8-khang-chien-chong-my-cuu-nuoc', 'muc-4', null, 'van_dung', 'van_dung_kien_thuc', null, 'SGK Lịch sử 12 (KNTT), Bài 8, mục 4')
