insert into public.exam_items (content_key, kind, stem, passage_id, choices, correct_index, statements, choice_notes, explanation, remember, grade, lesson_slug, section_id, topic_tag, level, competency, event_id, source_note)
values ('b8-m4-tn-04', 'mcq', 'Theo đoạn tư liệu, đường lối nào của Đảng là cơ sở quan trọng cho thắng lợi của cuộc kháng chiến chống Mỹ?', (select id from public.exam_passages where title = 'Nguyên nhân thắng lợi và ý nghĩa của cuộc kháng chiến chống Mỹ, cứu nước' and body = 'Cuộc kháng chiến chống Mỹ, cứu nước thắng lợi nhờ sự lãnh đạo của Đảng, đứng đầu là Chủ tịch Hồ Chí Minh, với đường lối tiến hành đồng thời cách mạng xã hội chủ nghĩa ở miền Bắc và cách mạng dân tộc dân chủ nhân dân ở miền Nam. Nhân dân hai miền đoàn kết, giàu lòng yêu nước; hậu phương miền Bắc xã hội chủ nghĩa đáp ứng kịp thời yêu cầu của tiền tuyến miền Nam. Bên cạnh đó là tình đoàn kết chiến đấu của ba dân tộc Đông Dương và sự đồng tình, ủng hộ, giúp đỡ của Liên Xô, Trung Quốc, các nước xã hội chủ nghĩa, nhân dân tiến bộ trên thế giới, trong đó có nhân dân Mỹ.
Thắng lợi đã kết thúc 21 năm kháng chiến chống Mỹ và 30 năm chiến tranh giải phóng dân tộc (1945 – 1975), hoàn thành cuộc cách mạng dân tộc dân chủ nhân dân trên cả nước, mở ra kỉ nguyên đất nước độc lập, thống nhất, đi lên chủ nghĩa xã hội. Thắng lợi tác động mạnh mẽ tới tình hình nước Mỹ và thế giới, cổ vũ phong trào giải phóng dân tộc.' order by created_at limit 1), array['Tiến hành đồng thời hai chiến lược cách mạng ở hai miền Nam, Bắc', 'Tập trung xây dựng chủ nghĩa xã hội, tạm gác việc giải phóng miền Nam', 'Chỉ đấu tranh ngoại giao để thống nhất đất nước', 'Dựa vào viện trợ nước ngoài để giải phóng miền Nam'], 0, null, '[{"note":"Đúng. Tiến hành đồng thời cách mạng xã hội chủ nghĩa ở miền Bắc và cách mạng dân tộc dân chủ nhân dân ở miền Nam.","section_id":"muc-4"},{"note":"Trái tư liệu: hai nhiệm vụ được tiến hành đồng thời, không tạm gác nhiệm vụ nào.","section_id":"muc-4","trap":"ban_chat"},{"note":"Tuyệt đối hóa: ta kết hợp đấu tranh quân sự, chính trị và ngoại giao; ngoại giao không phải hình thức duy nhất.","section_id":"muc-2","trap":"tuyet_doi"},{"note":"Đánh giá sai vai trò: sự giúp đỡ quốc tế là nguyên nhân khách quan; nhân tố quyết định là sự lãnh đạo của Đảng và sức mạnh của nhân dân hai miền.","section_id":"muc-4","trap":"nhan_qua"}]'::jsonb, 'Câu đọc hiểu về đường lối kháng chiến chống Mỹ.', 'Đường lối kháng chiến chống Mỹ: tiến hành đồng thời hai chiến lược cách mạng ở hai miền.', 12, '8-khang-chien-chong-my-cuu-nuoc', 'muc-4', null, 'thong_hieu', 'nhan_thuc_tu_duy', null, 'SGK Lịch sử 12 (KNTT), Bài 8, mục 4')
