values ('b8-m4-tn-05', 'mcq', 'Kinh nghiệm tranh thủ sự ủng hộ của nhân dân tiến bộ thế giới, “trong đó có nhân dân Mỹ”, gợi ý gì cho hoạt động đối ngoại của Việt Nam hiện nay?', (select id from public.exam_passages where title = 'Nguyên nhân thắng lợi và ý nghĩa của cuộc kháng chiến chống Mỹ, cứu nước' and body = 'Cuộc kháng chiến chống Mỹ, cứu nước thắng lợi nhờ sự lãnh đạo của Đảng, đứng đầu là Chủ tịch Hồ Chí Minh, với đường lối tiến hành đồng thời cách mạng xã hội chủ nghĩa ở miền Bắc và cách mạng dân tộc dân chủ nhân dân ở miền Nam. Nhân dân hai miền đoàn kết, giàu lòng yêu nước; hậu phương miền Bắc xã hội chủ nghĩa đáp ứng kịp thời yêu cầu của tiền tuyến miền Nam. Bên cạnh đó là tình đoàn kết chiến đấu của ba dân tộc Đông Dương và sự đồng tình, ủng hộ, giúp đỡ của Liên Xô, Trung Quốc, các nước xã hội chủ nghĩa, nhân dân tiến bộ trên thế giới, trong đó có nhân dân Mỹ.
Thắng lợi đã kết thúc 21 năm kháng chiến chống Mỹ và 30 năm chiến tranh giải phóng dân tộc (1945 – 1975), hoàn thành cuộc cách mạng dân tộc dân chủ nhân dân trên cả nước, mở ra kỉ nguyên đất nước độc lập, thống nhất, đi lên chủ nghĩa xã hội. Thắng lợi tác động mạnh mẽ tới tình hình nước Mỹ và thế giới, cổ vũ phong trào giải phóng dân tộc.' order by created_at limit 1), array['Chỉ tranh thủ chính phủ của các nước lớn', 'Hạn chế quan hệ với các nước từng là đối thủ trong chiến tranh', 'Không cần giới thiệu với thế giới về chính nghĩa của mình', 'Tranh thủ sự đồng tình của cộng đồng quốc tế với chính nghĩa của ta'], 3, null, '[{"note":"Thu hẹp sai: kinh nghiệm cho thấy cần tranh thủ cả nhân dân các nước (kể cả nhân dân Mỹ), không chỉ chính phủ các nước lớn.","section_id":"muc-4","trap":"tuyet_doi"},{"note":"Hiểu sai: Việt Nam đã bình thường hóa quan hệ với Mỹ (1995), khép lại quá khứ, hướng tới tương lai.","lesson_slug":"14-doi-ngoai-tu-nam-1975-den-nay","section_id":"muc-2","trap":"ban_chat"},{"note":"Trái kinh nghiệm lịch sử: sự ủng hộ của nhân dân thế giới có được nhờ chính nghĩa của ta được biết đến rộng rãi.","section_id":"muc-4","trap":"ban_chat"},{"note":"Đúng. Tranh thủ sự đồng tình, ủng hộ của bạn bè quốc tế, kể cả nhân dân nước đối phương — kinh nghiệm vẫn có giá trị khi bảo vệ chủ quyền, phát triển đất nước hiện nay.","section_id":"muc-4"}]'::jsonb, 'Câu liên hệ bài học đối ngoại nhân dân với hiện nay.', 'Kháng chiến chống Mỹ được nhân dân tiến bộ thế giới, kể cả nhân dân Mỹ, ủng hộ.', 12, '8-khang-chien-chong-my-cuu-nuoc', 'muc-4', null, 'van_dung', 'van_dung_kien_thuc', null, 'SGK Lịch sử 12 (KNTT), Bài 8, mục 4')
