values ('b8-m4-tn-06', 'mcq', 'So với cuộc kháng chiến chống thực dân Pháp (1945 – 1954), điểm khác biệt nổi bật của cuộc kháng chiến chống Mỹ, cứu nước là', null, array['chủ yếu dựa vào đấu tranh ngoại giao', 'không nhận được sự giúp đỡ của quốc tế', 'kết thúc bằng một hiệp định chia cắt đất nước', 'cả nước tiến hành đồng thời hai nhiệm vụ chiến lược ở hai miền'], 3, null, '[{"note":"Tuyệt đối hóa: ngoại giao là một mặt trận quan trọng (Hội nghị Pa-ri), nhưng thắng lợi quyết định là trên chiến trường.","section_id":"muc-4","trap":"tuyet_doi"},{"note":"Sai bản chất: ta nhận được sự giúp đỡ của Liên Xô, Trung Quốc, các nước xã hội chủ nghĩa và nhân dân tiến bộ thế giới.","section_id":"muc-4","trap":"ban_chat"},{"note":"Đánh tráo thời gian: hiệp định tạm chia cắt đất nước là Hiệp định Giơ-ne-vơ (1954), kết thúc kháng chiến chống Pháp; kháng chiến chống Mỹ kết thúc bằng thắng lợi quân sự năm 1975.","lesson_slug":"7-khang-chien-chong-phap","section_id":"muc-3","trap":"thoi_gian"},{"note":"Đúng. Trong kháng chiến chống Mỹ, đất nước tạm chia cắt; miền Bắc xây dựng chủ nghĩa xã hội, miền Nam làm cách mạng dân tộc dân chủ nhân dân — hai nhiệm vụ tiến hành đồng thời.","section_id":"muc-4"}]'::jsonb, 'Câu so sánh hai cuộc kháng chiến.', 'Kháng chiến chống Mỹ: một Đảng lãnh đạo, hai miền tiến hành đồng thời hai nhiệm vụ chiến lược.', 12, '8-khang-chien-chong-my-cuu-nuoc', 'muc-4', null, 'van_dung', 'van_dung_kien_thuc', null, 'SGK Lịch sử 12 (KNTT), Bài 8, mục 4')
