values ('mcq', 'Trụ sở chính của Liên hợp quốc đặt tại thành phố nào?', null, array['Niu Oóc (Mỹ)', 'Giơ-ne-vơ (Thụy Sĩ)', 'Pa-ri (Pháp)', 'Luân Đôn (Anh)'], 0, null, null, 'Trụ sở chính của Liên hợp quốc đặt tại Niu Oóc (Mỹ). Giơ-ne-vơ là nơi đặt một số cơ quan, tổ chức của Liên hợp quốc nhưng không phải trụ sở chính.', null, 12, '1-lien-hop-quoc', null, null, 'nhan_biet', 'tim_hieu_lich_su', null, 'SGK Lịch sử 12 (KNTT), Bài 1')
