values ('mcq', 'Kế hoạch Mác-san (1947) của Mỹ là kế hoạch', null, array['thành lập liên minh quân sự với các nước Đông Âu', 'chạy đua chinh phục vũ trụ với Liên Xô', 'hỗ trợ các nước Mỹ La-tinh giành độc lập', 'viện trợ kinh tế cho các nước Tây Âu khôi phục sau chiến tranh'], 3, null, null, 'Kế hoạch Mác-san viện trợ cho các nước Tây Âu khôi phục kinh tế, đồng thời lôi kéo các nước này vào liên minh chống Liên Xô — góp phần chia châu Âu thành hai khối đối lập.', null, 12, '2-trat-tu-the-gioi-trong-chien-tranh-lanh', null, null, 'thong_hieu', 'nhan_thuc_tu_duy', null, 'SGK Lịch sử 12 (KNTT), Bài 2')
