values ('mcq', 'Sau Chiến tranh lạnh, hầu hết các quốc gia điều chỉnh chiến lược phát triển theo hướng', null, array['đóng cửa, hạn chế quan hệ quốc tế', 'lấy phát triển kinh tế làm trọng điểm', 'tăng cường chạy đua vũ trang', 'tham gia các liên minh quân sự đối đầu'], 1, null, null, 'Sau Chiến tranh lạnh, các nước tập trung vào phát triển kinh tế, coi đó là trọng điểm để xây dựng sức mạnh quốc gia; hòa bình, hợp tác và phát triển trở thành xu thế chủ đạo.', null, 12, '3-trat-tu-the-gioi-sau-chien-tranh-lanh', null, null, 'thong_hieu', 'nhan_thuc_tu_duy', null, 'SGK Lịch sử 12 (KNTT), Bài 3')
