values ('mcq', 'Đại hội VIII của Đảng (1996) xác định nước ta chuyển sang thời kì nào?', null, array['Xây dựng chủ nghĩa xã hội ở miền Bắc', 'Đẩy mạnh công nghiệp hóa, hiện đại hóa đất nước', 'Khôi phục kinh tế sau chiến tranh', 'Bắt đầu tiến hành công cuộc Đổi mới'], 1, null, null, 'Đại hội VIII (1996) nhận định nước ta đã ra khỏi khủng hoảng kinh tế – xã hội và chuyển sang thời kì đẩy mạnh công nghiệp hóa, hiện đại hóa.', null, 12, '10-khai-quat-ve-cong-cuoc-doi-moi', null, null, 'thong_hieu', 'nhan_thuc_tu_duy', null, 'SGK Lịch sử 12 (KNTT), Bài 10')
