values ('true_false', 'Cho thông tin: “Sau gần 40 năm Đổi mới, Việt Nam đạt được những thành tựu to lớn, có ý nghĩa lịch sử.”', null, null, null, '[{"text":"Công cuộc Đổi mới đã đưa đất nước ra khỏi khủng hoảng kinh tế – xã hội.","is_true":true,"explanation":"Đại hội VIII (1996) nhận định nước ta đã ra khỏi khủng hoảng kinh tế – xã hội."},{"text":"Đời sống vật chất và tinh thần của nhân dân được cải thiện rõ rệt.","is_true":true,"explanation":"Đây là thành tựu về xã hội của công cuộc Đổi mới."},{"text":"Đến nay Việt Nam đã hoàn thành công nghiệp hóa, hiện đại hóa đất nước.","is_true":false,"explanation":"Công nghiệp hóa, hiện đại hóa vẫn đang được đẩy mạnh, chưa hoàn thành."},{"text":"Đổi mới chỉ đạt thành tựu về kinh tế, không có thành tựu về chính trị và đối ngoại.","is_true":false,"explanation":"Từ tuyệt đối “chỉ”: Đổi mới đạt thành tựu trên nhiều lĩnh vực, trong đó có chính trị, quốc phòng – an ninh và đối ngoại."}]'::jsonb, null, 'Câu kiểm tra đánh giá thành tựu của công cuộc Đổi mới.', null, 12, '11-thanh-tuu-va-bai-hoc-cua-cong-cuoc-doi-moi', null, null, 'thong_hieu', 'nhan_thuc_tu_duy', null, 'SGK Lịch sử 12 (KNTT), Bài 11')
