values ('mcq', 'Người thay mặt Chính phủ Cách mạng lâm thời Cộng hòa miền Nam Việt Nam kí Hiệp định Pa-ri năm 1973 là', null, array['Xuân Thủy', 'Phạm Văn Đồng', 'Nguyễn Thị Bình', 'Lê Đức Thọ'], 2, null, null, 'Bộ trưởng Ngoại giao Nguyễn Thị Bình thay mặt Chính phủ Cách mạng lâm thời Cộng hòa miền Nam Việt Nam kí Hiệp định Pa-ri. Lê Đức Thọ là cố vấn đặc biệt, Xuân Thủy là trưởng đoàn của Việt Nam Dân chủ Cộng hòa trong đàm phán.', null, 12, '13-doi-ngoai-trong-khang-chien-1945-1975', null, null, 'nhan_biet', 'tim_hieu_lich_su', null, 'SGK Lịch sử 12 (KNTT), Bài 13')
