values ('mcq', 'Tên khai sinh của Chủ tịch Hồ Chí Minh là', null, array['Nguyễn Ái Quốc', 'Lý Thụy', 'Nguyễn Sinh Cung', 'Nguyễn Tất Thành'], 2, null, null, 'Tên khai sinh là Nguyễn Sinh Cung; khi đi học đổi tên là Nguyễn Tất Thành; Nguyễn Ái Quốc là tên dùng từ năm 1919; Lý Thụy là bí danh khi hoạt động ở Trung Quốc.', null, 12, '15-khai-quat-cuoc-doi-va-su-nghiep-ho-chi-minh', null, null, 'nhan_biet', 'tim_hieu_lich_su', null, 'SGK Lịch sử 12 (KNTT), Bài 15')
