insert into public.exam_items (kind, stem, passage_id, choices, correct_index, statements, choice_notes, explanation, remember, grade, lesson_slug, section_id, topic_tag, level, competency, event_id, source_note)
values ('mcq', 'Tháng 7-1920, Nguyễn Ái Quốc đọc văn kiện nào và từ đó tìm thấy con đường cứu nước đúng đắn?', null, array['Bản Tuyên ngôn Độc lập năm 1776 của nước Mỹ', 'Sơ thảo lần thứ nhất những luận cương về vấn đề dân tộc và vấn đề thuộc địa của Lê-nin', 'Tuyên ngôn của Đảng Cộng sản của C. Mác và Ph. Ăng-ghen', 'Tuyên ngôn Nhân quyền và Dân quyền năm 1791 của Cách mạng Pháp'], 1, null, null, 'Tháng 7-1920, Nguyễn Ái Quốc đọc bản Sơ thảo lần thứ nhất những luận cương về vấn đề dân tộc và vấn đề thuộc địa của Lê-nin, tìm thấy con đường giải phóng dân tộc theo con đường cách mạng vô sản.', null, 12, '15-khai-quat-cuoc-doi-va-su-nghiep-ho-chi-minh', null, null, 'nhan_biet', 'tim_hieu_lich_su', null, 'SGK Lịch sử 12 (KNTT), Bài 15')
