insert into public.exam_items (kind, stem, passage_id, choices, correct_index, statements, choice_notes, explanation, remember, grade, lesson_slug, section_id, topic_tag, level, competency, event_id, source_note)
values ('true_false', 'Cho thông tin: “Chủ tịch Hồ Chí Minh (1890 – 1969) đã cống hiến trọn đời cho sự nghiệp giải phóng dân tộc và xây dựng đất nước.”', null, null, null, '[{"text":"Năm 1911, Nguyễn Tất Thành rời bến Nhà Rồng ra đi tìm đường cứu nước.","is_true":true,"explanation":"Ngày 5-6-1911, Người rời bến Nhà Rồng."},{"text":"Nguyễn Ái Quốc chủ trì hội nghị hợp nhất các tổ chức cộng sản, thành lập Đảng Cộng sản Việt Nam đầu năm 1930.","is_true":true,"explanation":"Hội nghị thành lập Đảng họp đầu năm 1930 tại Hương Cảng (Trung Quốc) do Nguyễn Ái Quốc chủ trì."},{"text":"Chủ tịch Hồ Chí Minh qua đời năm 1975, sau khi đất nước thống nhất.","is_true":false,"explanation":"Đánh tráo thời gian: Người mất ngày 2-9-1969."},{"text":"Nguyễn Ái Quốc tìm thấy con đường cứu nước ngay khi vừa rời Tổ quốc năm 1911.","is_true":false,"explanation":"Phải đến tháng 7-1920, khi đọc Sơ thảo luận cương của Lê-nin, Người mới tìm thấy con đường cứu nước."}]'::jsonb, null, 'Câu kiểm tra các mốc chính trong cuộc đời Chủ tịch Hồ Chí Minh.', null, 12, '15-khai-quat-cuoc-doi-va-su-nghiep-ho-chi-minh', null, null, 'thong_hieu', 'nhan_thuc_tu_duy', null, 'SGK Lịch sử 12 (KNTT), Bài 15')
