values ('mcq', 'Đội Việt Nam Tuyên truyền Giải phóng quân được thành lập ngày', null, array['19-8-1945', '19-12-1946', '22-12-1944', '19-5-1941'], 2, null, null, 'Thực hiện chỉ thị của Hồ Chí Minh, Đội Việt Nam Tuyên truyền Giải phóng quân thành lập ngày 22-12-1944. Ngày 19-5-1941 thành lập Mặt trận Việt Minh.', null, 12, '16-ho-chi-minh-anh-hung-giai-phong-dan-toc', null, null, 'nhan_biet', 'tim_hieu_lich_su', null, 'SGK Lịch sử 12 (KNTT), Bài 16')
