insert into public.exam_items (kind, stem, passage_id, choices, correct_index, statements, choice_notes, explanation, remember, grade, lesson_slug, section_id, topic_tag, level, competency, event_id, source_note)
values ('true_false', 'Cho thông tin: “Hình ảnh và tư tưởng của Chủ tịch Hồ Chí Minh để lại dấu ấn sâu đậm trong lòng nhân dân Việt Nam và bạn bè thế giới.”', null, null, null, '[{"text":"UNESCO đã tôn vinh Chủ tịch Hồ Chí Minh là Anh hùng giải phóng dân tộc, Nhà văn hóa kiệt xuất.","is_true":true,"explanation":"Nghị quyết của Đại hội đồng UNESCO năm 1987."},{"text":"Dấu ấn Hồ Chí Minh chỉ có ở Việt Nam, không có ở nước ngoài.","is_true":false,"explanation":"Từ tuyệt đối “chỉ”: nhiều nước có tượng đài, đường phố, công trình mang tên hoặc tưởng niệm Hồ Chí Minh."},{"text":"Năm 1976, thành phố Sài Gòn – Gia Định được đổi tên thành Thành phố Hồ Chí Minh.","is_true":true,"explanation":"Quốc hội nước Việt Nam thống nhất quyết định đổi tên năm 1976."},{"text":"Nghị quyết tôn vinh của UNESCO được thông qua khi Chủ tịch Hồ Chí Minh còn sống.","is_true":false,"explanation":"Người mất năm 1969; nghị quyết được thông qua năm 1987."}]'::jsonb, null, 'Câu kiểm tra hiểu biết về dấu ấn của Chủ tịch Hồ Chí Minh.', null, 12, '17-dau-an-ho-chi-minh', null, null, 'thong_hieu', 'nhan_thuc_tu_duy', null, 'SGK Lịch sử 12 (KNTT), Bài 17')
